/* Accounting course data for acc.html (cards, summaries, quiz).
   Loaded by the course page before scripts/study-course-engine.js; other pages read the D line as JSON.
   Keep "const D = {...};" on one line: Today, Lessons, Grades, Calendar and search parse it. */
const D = {"key": "acc", "title": "Foundations of Accounting", "sub": "สรุป · แฟลชการ์ด · แบบฝึก Ch01–09", "theme": {"paper": "#f3f5f1", "accent": "#2b6f58", "soft": "#dcebe4", "accentd": "#6fc59d", "softd": "#1f3a30"}, "cats": [["c1", "01 Business"], ["c2", "02 Recording"], ["c3", "03 Adjusting"], ["c4", "04 Cycle"], ["c5", "05 Merchandising"], ["c6", "06 Inventory"], ["c7", "07 AIS"], ["c8", "08 Cash"], ["c9", "09 Receivables"]], "cards": [["c1", "Accounting ต่างจาก Bookkeeping อย่างไร?", "Accounting = ระบบ ระบุ → บันทึก → สื่อสาร ข้อมูลที่เกี่ยวข้อง เชื่อถือได้ และเปรียบเทียบได้ เพื่อการตัดสินใจ\nBookkeeping = แค่ส่วน “บันทึก” รายการค้า เป็นส่วนหนึ่งของ Accounting", "Slides 01–02", "01-1"], ["c1", "Accounting Process มี 3 ขั้นตอนอะไร?", "1) Identifying — คัดเลือกรายการ/เหตุการณ์\n2) Recording — วัด บันทึก จัดหมวด\n3) Communicating — จัดทำ วิเคราะห์ ตีความรายงาน", "Slide 02", "01-2"], ["c1", "ผู้ใช้ข้อมูลบัญชีภายนอก (External users) มีใครบ้าง ใช้ทำอะไร?", "เจ้าหนี้ (Lenders), ผู้ถือหุ้น, รัฐ, ลูกค้า, กลุ่มผู้บริโภค, ผู้สอบบัญชีภายนอก\nใช้ประเมินฐานะและผลการดำเนินงานของกิจการ", "Slide 03", "01-3"], ["c1", "Financial Accounting กับ Managerial Accounting ต่างกันอย่างไร?", "Financial = สื่อสารข้อมูลการเงินให้ “บุคคลภายนอก”\nManagerial = ช่วยผู้บริหาร “ภายใน” วางแผนและตัดสินใจ", "Slides 03–04", "01-4"], ["c1", "ทำไมจริยธรรม (Ethics) สำคัญต่อการทำบัญชี?", "ทำให้ผู้จัดทำเลือกสิ่งที่ถูกต้อง ไม่บิดเบือนตัวเลข และผู้ใช้เชื่อถือรายงานได้\n“Good ethics are good business”", "Slides 06–07", "01-5"], ["c1", "เจอปัญหาจริยธรรม ตัดสินใจด้วย 3 ขั้นตอนอะไร?", "1) Identify ethical concern\n2) Analyze options — พิจารณาผลทุกทาง\n3) Make ethical decision — เลือกทางที่ดีที่สุด", "Slide 07", "01-6"], ["c1", "GAAP กับ IFRS คืออะไร?", "GAAP = หลักการบัญชีที่รับรองทั่วไป\nIFRS = มาตรฐานรายงานการเงินระหว่างประเทศ ออกโดย IASB", "Slides 08–09", "01-7"], ["c1", "หลักการบัญชี (Principles) 4 ข้อ?", "1) Cost Principle — บันทึกตามราคาทุนจริง\n2) Revenue Recognition — รับรู้รายได้เมื่อเกิดขึ้น (earned)\n3) Expense Recognition / Matching — จับคู่ค่าใช้จ่ายกับรายได้\n4) Full Disclosure — เปิดเผยข้อมูลที่มีผลต่อการตัดสินใจ", "Slide 11", "01-8"], ["c1", "Revenue Recognition ต่างจาก Expense Recognition อย่างไร?", "Revenue Recognition: รับรู้รายได้เมื่อ “ได้รับสิทธิ์” แล้ว ไม่จำเป็นต้องได้เงินสด\nExpense Recognition (Matching): บันทึกค่าใช้จ่ายในงวดเดียวกับรายได้ที่มันช่วยสร้าง", "Slide 11", "01-9"], ["c1", "ข้อสมมติทางบัญชี (Assumptions) 4 ข้อ?", "Going-concern · Monetary unit · Business entity · Time period", "Slide 12", "01-10"], ["c1", "Business Entity Assumption หมายความว่าอะไร?", "บัญชีของกิจการต้องแยกจากเจ้าของและหน่วยงานอื่น\nเช่น ของใช้ส่วนตัวเจ้าของไม่ใช่ค่าใช้จ่ายกิจการ", "Slide 12", "01-11"], ["c1", "Sole Proprietorship, Partnership, Corporation ต่างกันอย่างไร?", "Sole Proprietorship = เจ้าของคนเดียว\nPartnership = หุ้นส่วน 2 คนขึ้นไป\nCorporation = นิติบุคคลแยก เจ้าของคือ Shareholders ความรับผิดจำกัด (หุ้นประเภทเดียว = Ordinary shares)", "Slides 13–14", "01-12"], ["c1", "Fundamental Qualitative Characteristics มี 2 อะไร?", "Relevance — มีผลต่อการตัดสินใจ\nFaithful Representation — นำเสนอตรงความจริง", "Slides 15–18", "01-13"], ["c1", "Relevance ประกอบด้วยอะไรบ้าง?", "Predictive value · Confirmatory value · Materiality\n(Materiality = ถ้าละเว้นหรือแสดงผิดแล้วกระทบการตัดสินใจ)", "Slide 17", "01-14"], ["c1", "Faithful Representation ต้องมีคุณสมบัติ 3 ข้อ?", "Complete (ครบถ้วน) · Neutral (เป็นกลาง) · Free from error (ไม่มีข้อผิดพลาด)", "Slide 18", "01-15"], ["c1", "Enhancing Qualitative Characteristics 4 ข้อ?", "Comparability · Verifiability · Timeliness · Understandability", "Slides 16, 19", "01-16"], ["c1", "Verifiability คืออะไร?", "ผู้สังเกตที่มีความรู้และเป็นอิสระหลายคน “เห็นพ้องตรงกัน” (reach consensus) ในข้อมูลได้", "Slide 19", "01-17"], ["c1", "Cost-benefit Constraint คืออะไร?", "ต้นทุนการจัดทำข้อมูลต้องคุ้มกับประโยชน์ที่ผู้ใช้ได้รับ", "Slides 15–16", "01-18"], ["c1", "สมการบัญชีคืออะไร ทำไมต้องสมดุล?", "Assets = Liabilities + Equity\nสินทรัพย์ทุกบาทได้มาจากเจ้าหนี้หรือเจ้าของ จึงต้องเท่ากันเสมอ", "Slide 20", "01-19"], ["c1", "Assets, Liabilities, Equity หมายถึงอะไร?", "Assets = ทรัพยากรที่กิจการควบคุม\nLiabilities = ภาระผูกพันต่อบุคคลภายนอก\nEquity = ส่วนที่เหลือของเจ้าของหลังหักหนี้สิน", "Slides 21–23", "01-20"], ["c1", "เจ้าของนำเงินสดมาลงทุน กระทบสมการอย่างไร?", "Cash (Asset) ↑ และ Equity ↑ เท่ากัน", "Slide 26", "01-21"], ["c1", "ซื้อวัสดุเป็นเงินสด vs เงินเชื่อ ต่างกันอย่างไร?", "เงินสด: Supplies ↑ Cash ↓ (สินทรัพย์รวมเท่าเดิม)\nเงินเชื่อ: Supplies ↑ Accounts Payable ↑", "Slides 27, 29", "01-22"], ["c1", "ทำไมให้บริการเป็นเงินเชื่อต้องเพิ่ม Accounts Receivable?", "รับรู้รายได้แล้ว (ทำงานเสร็จ) แต่ยังไม่ได้เงินสด จึงมีสิทธิเรียกร้องจากลูกค้า", "Slide 32", "01-23"], ["c1", "เก็บเงินจากลูกหนี้ เป็นรายได้ใหม่ไหม?", "ไม่ใช่ รายได้รับรู้ไปแล้วตอนให้บริการ\nแค่ Cash ↑ Accounts Receivable ↓", "Slide 33", "01-24"], ["c1", "จ่ายเจ้าหนี้ / เจ้าของถอนเงิน กระทบอะไร? Withdrawal เป็น Expense ไหม?", "จ่ายเจ้าหนี้: Cash ↓ Accounts Payable ↓\nถอนเงิน: Cash ↓ Equity ↓ — ไม่ใช่ Expense (เป็นการคืนทรัพยากรให้เจ้าของ)", "Slides 34–35", "01-25"], ["c1", "งบการเงินหลัก 4 งบ?", "Income Statement — กำไรขาดทุนตลอดงวด\nStatement of Changes in Equity — ทุนต้นงวด → ปลายงวด\nStatement of Financial Position — ฐานะ ณ วันหนึ่ง\nStatement of Cash Flows — เงินสดเข้าออก", "Slides 37–41", "01-26"], ["c1", "Income Statement กับ Balance Sheet ต่างกันเรื่องเวลาอย่างไร?", "Income Statement = ตลอด “ช่วงเวลา”\nBalance Sheet = ณ “วันใดวันหนึ่ง”", "ตำรา p.15–18", "01-27"], ["c1", "Statement of Owner’s Equity ส่งตัวเลขอะไรต่อไป Balance Sheet?", "Capital ปลายงวด = ต้นงวด + ลงทุนเพิ่ม + กำไรสุทธิ − ถอนใช้", "ตำรา p.15–18", "01-28"], ["c1", "กำไรสุทธิ ต่างจาก เงินสดสุทธิ อย่างไร?", "กำไรสุทธิ = Revenue − Expenses (งบกำไรขาดทุน)\nเงินสดสุทธิ = Cash inflows − outflows (งบกระแสเงินสด)", "Slides 38, 41", "01-29"], ["c1", "ROA คำนวณอย่างไร?", "ROA = Net Income ÷ Average Total Assets\nวัดว่าใช้สินทรัพย์สร้างกำไรได้ดีแค่ไหน", "Slide 42", "01-30"], ["c1", "กิจกรรม Financing, Investing, Operating คืออะไร?", "Financing = หาเงินทุน (เจ้าของ/เจ้าหนี้)\nInvesting = ซื้อขายสินทรัพย์ระยะยาว\nOperating = ดำเนินงานหลัก ผลิต ขาย บริการ", "Slide 44", "01-31"], ["c2", "ขั้นตอน Analyzing & Recording Process มีอะไรบ้าง?", "1) Analyze รายการจาก Source documents\n2) Record ลง Journal\n3) Post ไป Ledger\n4) จัดทำและวิเคราะห์ Trial balance", "Slide 2-2", "02-1"], ["c2", "Source documents ตามสไลด์มีอะไรบ้าง?", "Checks · Bills from suppliers · Employee earnings records · Purchase orders · Bank statements · Sales tickets", "Slide 2-3", "02-2"], ["c2", "Account คืออะไร?", "บันทึกการเพิ่ม/ลดของรายการเฉพาะ (สินทรัพย์ หนี้สิน ทุน รายได้ หรือค่าใช้จ่าย)\nGeneral ledger = บันทึกที่รวมทุกบัญชีของกิจการ", "Slide 2-4", "02-3"], ["c2", "Asset accounts ในบทมีอะไรบ้าง?", "Cash · Accounts Receivable · Notes Receivable · Prepaid Accounts · Supplies · Equipment · Buildings · Land", "Slide 2-6", "02-4"], ["c2", "Liability accounts มีอะไรบ้าง?", "Accounts Payable · Notes Payable · Unearned Revenue · Accrued Liabilities", "Slide 2-7", "02-5"], ["c2", "Equity accounts มีอะไรบ้าง และอันไหนเพิ่ม/ลดทุน?", "Owner’s Capital (+) · Revenues (+)\nOwner’s Withdrawals (−) · Expenses (−)", "Slides 2-8, 2-9", "02-6"], ["c2", "Ledger กับ Chart of Accounts ต่างกันอย่างไร?", "Ledger = ชุดบัญชีทั้งหมดของระบบ\nChart of Accounts = รายชื่อบัญชีทั้งหมดพร้อมเลขรหัส (เช่น 101 Cash, 201 Accounts Payable, 301 Capital)", "Slide 2-10", "02-7"], ["c2", "T-account คืออะไร ซ้าย/ขวาเรียกว่าอะไร?", "เครื่องมือแสดงผลรายการต่อบัญชีหนึ่ง\nซ้าย = Debit (Dr.) · ขวา = Credit (Cr.)", "Slide 2-11", "02-8"], ["c2", "Assets, Liabilities, Equity เพิ่มฝั่งไหน?", "Assets: เพิ่ม Debit (ยอดปกติ Debit)\nLiabilities, Equity: เพิ่ม Credit (ยอดปกติ Credit)", "Slide 2-12", "02-9"], ["c2", "Revenue, Expenses, Withdrawals มียอดปกติฝั่งไหน?", "Revenue → Credit\nExpenses, Owner’s Withdrawals → Debit", "Slide 2-13", "02-10"], ["c2", "ทำไม Debit รวมต้องเท่ากับ Credit รวม?", "Double-entry: ทุกรายการกระทบอย่างน้อย 2 บัญชี เพื่อให้ Assets = Liabilities + Equity สมดุลเสมอ", "Slides 2-12–2-14", "02-11"], ["c2", "Debit แปลว่าเงินสดเพิ่มทุกครั้งไหม?", "ไม่ Debit คือ “ฝั่งซ้าย”\nCash (Asset) → Debit = เพิ่ม\nAccounts Payable (Liability) → Debit = ลด", "ตำรา p.49–51", "02-12"], ["c2", "Journalizing กับ Posting ต่างกันอย่างไร?", "Journalizing = บันทึกรายการตามลำดับวันที่ลง Journal\nPosting = ย้ายจาก Journal ไปแต่ละบัญชีใน Ledger", "Slide 2-15", "02-13"], ["c2", "Journal entry หนึ่งรายการมีข้อมูล 4 อะไร?", "1) วันที่ 2) ชื่อบัญชีที่ Dr./Cr. 3) จำนวนเงิน Dr./Cr. 4) คำอธิบายรายการ", "Slide 2-16", "02-14"], ["c2", "ขั้นตอน Posting journal entries 6 ขั้น?", "1) หาบัญชีใน Ledger 2) ใส่วันที่ 3) ใส่จำนวนเงินและคำอธิบาย 4) ใส่เลขอ้างอิง Journal 5) คำนวณยอดคงเหลือ 6) ใส่เลขบัญชี Ledger กลับใน Journal", "Slides 2-18–2-23", "02-15"], ["c2", "เจ้าของลงทุนเงินสด บันทึกอย่างไร?", "Dr. Cash (101)\n    Cr. Owner’s Capital (301)", "Slide 2-24", "02-16"], ["c2", "ซื้อ Supplies ด้วยเงินสด / เงินเชื่อ บันทึกอย่างไร?", "เงินสด: Dr. Supplies (126) Cr. Cash (101)\nเงินเชื่อ: Dr. Supplies (126) Cr. Accounts Payable (201)", "Slides 2-25, 2-27", "02-17"], ["c2", "Trial balance คืออะไร จัดทำ 3 ขั้นอย่างไร?", "รายการยอดคงเหลือทุกบัญชีจาก Ledger\n1) ใส่ชื่อบัญชีและยอด 2) รวมยอด Debit และ Credit 3) ตรวจว่าเท่ากัน", "Slides 2-29, 2-30", "02-18"], ["c2", "Trial balance ไม่เท่ากัน ตรวจ 6 ขั้นอะไร?", "1) บวกคอลัมน์ใหม่ 2) ตรวจยอดที่คัดจาก Ledger 3) ดูว่าวางผิดฝั่งไหม 4) คำนวณยอด Ledger ใหม่ 5) ตรวจการ Post 6) ตรวจว่าทุก entry Dr. = Cr.", "Slide 2-31", "02-19"], ["c2", "Trial balance สมดุล แต่รายงานยังผิดได้เพราะอะไร?", "ลงผิดบัญชี, ผิดจำนวนแต่ Dr./Cr. เท่ากัน, หรือลืมบันทึกรายการทั้งรายการ", "ตำรา p.51–60", "02-20"], ["c2", "Trial balance ใช้ทำงบการเงินอย่างไร?", "Revenue/Expense → Income Statement\nNet profit + ลงทุน − ถอน → Statement of Changes in Equity\nAssets/Liabilities/Capital ปลายงวด → Statement of Financial Position", "Slides 2-32–2-35", "02-21"], ["c2", "ตัวอย่าง FastForward: ทุนต้นงวด 0, ลงทุน 30,000, กำไร 3,470, ถอน 200 → Capital ปลายงวด?", "0 + 30,000 + 3,470 − 200 = 33,270", "Slide 2-34", "02-22"], ["c2", "Presentation issues: ใส่ $ และจุลภาคอย่างไร?", "Journal/Ledger ไม่ใส่ $\nงบการเงิน/Trial balance ใส่ $ เฉพาะตัวแรกและตัวสุดท้ายของคอลัมน์\nงบการเงินใส่จุลภาคเสมอ", "Slide 2-36", "02-23"], ["c2", "Debt ratio คำนวณอย่างไร ค่าสูงหมายถึงอะไร?", "Debt ratio = Total Liabilities ÷ Total Assets\nสูง = มีโอกาสชำระหนี้ไม่ได้ในอนาคตมากขึ้น (ความเสี่ยงหนี้สูง)", "Slide 2-37", "02-24"], ["c2", "Debt ratio = 0.65 ตีความอย่างไร?", "ประมาณ 65% ของสินทรัพย์ได้มาจากหนี้สิน ต้องเทียบกับธุรกิจประเภทเดียวกัน", "ตำรา p.62", "02-25"], ["c3", "Accounting period คืออะไร?", "การแบ่งอายุกิจการเป็นช่วงเวลาเพื่อทำรายงาน เช่น เดือน ไตรมาส ปี", "Slide 3-2", "03-1"], ["c3", "Accrual basis กับ Cash basis ต่างกันอย่างไร?", "Accrual: รับรู้รายได้เมื่อหาได้ ค่าใช้จ่ายเมื่อเกิดขึ้น\nCash: รับรู้เมื่อรับ/จ่ายเงินสด (ไม่ใช่ GAAP)", "Slides 3-3, 3-4", "03-2"], ["c3", "จ่ายค่าประกัน 2,400 คุ้มครอง 24 เดือน (ธ.ค. 2015 – พ.ย. 2017) แต่ละปีรับรู้ค่าใช้จ่ายเท่าไรตาม Accrual?", "2015 = 100 · 2016 = 1,200 · 2017 = 1,100\n(Cash basis จะลง 2,400 ทั้งหมดใน 2015)", "Slides 3-5, 3-6", "03-3"], ["c3", "Revenue recognition กับ Matching principle คืออะไร?", "Revenue recognition = รับรู้รายได้เมื่อส่งมอบสินค้า/บริการแล้ว\nMatching = จับคู่ค่าใช้จ่ายที่ใช้สร้างรายได้นั้นในงวดเดียวกัน", "Slides 3-7, 3-8", "03-4"], ["c3", "Adjusting entries มี 4 แบบอะไร?", "จ่าย/รับเงินก่อนรับรู้: Prepaid expenses (รวมค่าเสื่อม) · Unearned revenues\nจ่าย/รับเงินหลังรับรู้: Accrued expenses · Accrued revenues", "Slide 3-9", "03-5"], ["c3", "Prepaid expenses คืออะไร?", "ทรัพยากรที่จ่ายเงินไปก่อนได้รับประโยชน์จริง → เริ่มเป็นสินทรัพย์ แล้วทยอยเป็นค่าใช้จ่าย", "Slide 3-10", "03-6"], ["c3", "ปรับ Prepaid insurance เดือน ธ.ค. (2,400 / 24 เดือน)?", "Dr. Insurance expense 100 / Cr. Prepaid insurance 100", "Slide 3-11", "03-7"], ["c3", "ซื้อ Supplies 9,720 นับคงเหลือได้ 8,670 ปรับอย่างไร?", "ใช้ไป 1,050 → Dr. Supplies expense 1,050 / Cr. Supplies 1,050", "Slide 3-12", "03-8"], ["c3", "Prepaid ที่จ่ายและใช้หมดในงวดเดียว (เช่น ค่าเช่ารายเดือน) บันทึกอย่างไร?", "บันทึก Dr. ค่าใช้จ่ายได้เลย แทนการบันทึกเป็นสินทรัพย์", "Slide 3-13", "03-9"], ["c3", "Straight-line depreciation คำนวณอย่างไร?", "(Asset cost − Residual value) ÷ Useful life", "Slide 3-14", "03-10"], ["c3", "อุปกรณ์ 26,000 มูลค่าซาก 8,000 อายุ 48 เดือน ค่าเสื่อมต่อเดือน?", "(26,000 − 8,000) ÷ 48 = 375\nDr. Depreciation expense 375 / Cr. Accumulated depreciation 375", "Slide 3-15", "03-11"], ["c3", "Accumulated depreciation คือบัญชีประเภทไหน?", "Contra asset — แสดงหักจากอุปกรณ์ในงบฐานะการเงิน (แสดงยอดสุทธิ)", "Slides 3-16, 3-17", "03-12"], ["c3", "Unearned revenue คืออะไร?", "เงินที่รับมาก่อนส่งมอบสินค้า/บริการ → เป็นหนี้สิน", "Slide 3-18", "03-13"], ["c3", "รับค่าที่ปรึกษาล่วงหน้า 3,000 สำหรับ 60 วัน ทำงานแล้ว 5 วัน ปรับอย่างไร?", "3,000 ÷ 60 = 50/วัน × 5 = 250\nDr. Unearned consulting revenue 250 / Cr. Consulting revenue 250", "Slides 3-19, 3-20", "03-14"], ["c3", "Accrued expenses คืออะไร?", "ต้นทุนที่เกิดขึ้นในงวดแล้ว แต่ยังไม่ได้จ่ายและยังไม่ได้บันทึก", "Slide 3-21", "03-15"], ["c3", "ลูกจ้างได้ 70/วัน ทำงานหลังวันจ่ายเงินเดือน 3 วันก่อนสิ้นปี ปรับอย่างไร?", "3 × 70 = 210\nDr. Salaries expense 210 / Cr. Salaries payable 210", "Slides 3-22, 3-23", "03-16"], ["c3", "กู้ 6,000 ดอกเบี้ย 6%/ปี ดอกเบี้ยค้างจ่าย 1 เดือนเท่าไร?", "6,000 × 6% × 1/12 = 30\nDr. Interest expense 30 / Cr. Interest payable 30", "Slide 3-25", "03-17"], ["c3", "Accrued revenues คืออะไร?", "รายได้ที่หาได้ในงวดแล้ว แต่ยังไม่บันทึกและยังไม่ได้รับเงิน", "Slide 3-26", "03-18"], ["c3", "สัญญา 30 วัน 2,700 (90/วัน) เริ่ม 12 ธ.ค. ณ 31 ธ.ค. ปรับอย่างไร?", "20 วัน × 90 = 1,800\nDr. Accounts receivable 1,800 / Cr. Consulting revenue 1,800\n(อีก 900 เป็นรายได้เดือน ม.ค.)", "Slides 3-27, 3-28", "03-19"], ["c3", "ลำดับการทำงบการเงินจาก Adjusted trial balance?", "1) Income statement 2) Statement of changes in equity (รับ Net profit) 3) Statement of financial position", "Slides 3-33 – 3-36", "03-20"], ["c3", "Profit margin คำนวณอย่างไร?", "Net profit ÷ Net sales", "Slide 3-37", "03-21"], ["c3", "Appendix 3A: ถ้าบันทึก Prepaid เป็นค่าใช้จ่ายตั้งแต่ต้น สิ้นงวดต้องทำอะไร?", "ปรับส่วนที่ยังไม่ใช้กลับเป็นสินทรัพย์ (Dr. Prepaid / Cr. Expense)\nรายการปรับขึ้นกับว่าตอนจ่ายบันทึกไว้อย่างไร", "Slide 3-38", "03-22"], ["c4", "Work sheet มีประโยชน์อะไร และบังคับไหม?", "ช่วยทำงบ · เชื่อมบัญชีกับรายการปรับปรุง · ลดข้อผิดพลาด · ช่วยทำงบระหว่างกาล · ช่วยวางแผน audit · ดูผลของรายการที่เสนอ\nไม่ใช่รายงานบังคับ", "Slide 4-2", "04-1"], ["c4", "คอลัมน์ของ Work sheet มีอะไรบ้าง?", "Unadjusted trial balance → Adjustments → Adjusted trial balance → Income statement → Statement of financial position & changes in equity", "Slides 4-3 – 4-7", "04-2"], ["c4", "Closing entries มีจุดประสงค์ 2 ข้อ?", "1) ทำให้ Revenue, Expense, Withdrawals เป็นศูนย์เมื่อสิ้นงวด\n2) สรุปรายได้และค่าใช้จ่ายของงวดไว้ใน Income summary", "Slide 4-9", "04-3"], ["c4", "ขั้นตอนการปิดบัญชี 3 ขั้น?", "ระบุบัญชีที่ต้องปิด → บันทึกและผ่านรายการปิดบัญชี → ทำ Post-closing trial balance", "Slide 4-9", "04-4"], ["c4", "Temporary กับ Permanent accounts ต่างกันอย่างไร?", "Temporary (Revenues, Expenses, Withdrawals, Income summary) → ปิดทุกงวด\nPermanent (Assets, Liabilities, Equity) → ยกยอดไปงวดหน้า", "Slide 4-10", "04-5"], ["c4", "รายการปิดบัญชี 4 ขั้นตามลำดับ?", "1) ปิด Revenue → Income summary\n2) ปิด Expense → Income summary\n3) ปิด Income summary → Owner’s capital\n4) ปิด Withdrawals → Owner’s capital", "Slides 4-11, 4-25", "04-6"], ["c4", "ปิดรายได้ Consulting 7,850 และ Rental 300 บันทึกอย่างไร?", "Dr. Consulting revenue 7,850\nDr. Rental revenue 300\n   Cr. Income summary 8,150", "Slide 4-14", "04-7"], ["c4", "ปิดค่าใช้จ่ายเข้า Income summary บันทึกอย่างไร?", "Dr. Income summary (รวม) / Cr. Expense แต่ละบัญชี", "Slides 4-17, 4-18", "04-8"], ["c4", "ขั้นที่ 3 กรณีมีกำไรสุทธิ บันทึกอย่างไร?", "Dr. Income summary / Cr. Owner’s capital (เท่ากับกำไรสุทธิ)\nขาดทุน → กลับทิศ", "Slides 4-20, 4-21", "04-9"], ["c4", "ปิด Withdrawals บันทึกอย่างไร?", "Dr. Owner’s capital / Cr. Owner’s withdrawals", "Slides 4-23, 4-24", "04-10"], ["c4", "Post-closing trial balance คืออะไร?", "รายการบัญชีถาวรและยอดคงเหลือหลังผ่านรายการปิดบัญชี — Dr. รวมต้องเท่ากับ Cr. รวม", "Slides 4-26, 4-27", "04-11"], ["c4", "Post-closing trial balance มีบัญชี Salaries expense ไหม?", "ไม่มี เพราะค่าใช้จ่ายเป็นบัญชีชั่วคราวที่ถูกปิดแล้ว", "ตำรา ch.4", "04-12"], ["c4", "ลำดับ Accounting cycle?", "Analyze → Journalize → Post → Unadjusted TB → Adjust → Adjusted TB → Prepare statements → Close → Post-closing TB (→ Reverse เป็นทางเลือก)", "Slide 4-28", "04-13"], ["c4", "เกณฑ์ “Current” ในงบจัดประเภทคืออะไร?", "คาดว่าจะเก็บได้หรือถึงกำหนดชำระภายใน 1 ปี หรือรอบการดำเนินงานปกติ แล้วแต่อย่างไหนนานกว่า", "Slide 4-29", "04-14"], ["c4", "Current assets คืออะไร?", "สินทรัพย์ที่คาดว่าจะขาย เก็บเงิน หรือใช้หมดภายใน 1 ปี/รอบการดำเนินงาน", "Slide 4-30", "04-15"], ["c4", "Long-term investments คืออะไร?", "สินทรัพย์ทางการเงิน/เงินลงทุนที่ตั้งใจถือนานกว่า 1 ปีหรือรอบการดำเนินงาน", "Slide 4-31", "04-16"], ["c4", "PP&E กับ Intangible assets ต่างกันอย่างไร?", "ทั้งคู่ใช้ระยะยาวเพื่อผลิต/ขาย\nPP&E มีตัวตน · Intangible ไม่มีรูปร่าง", "Slides 4-32, 4-33", "04-17"], ["c4", "Current กับ Noncurrent liabilities ต่างกันอย่างไร?", "Current = ถึงกำหนดภายใน 1 ปีหรือรอบการดำเนินงาน (ที่นานกว่า)\nNoncurrent = ไม่ถึงกำหนดภายในช่วงนั้น", "Slides 4-34, 4-35", "04-18"], ["c4", "Equity คืออะไร?", "สิทธิของเจ้าของในสินทรัพย์ของกิจการ", "Slide 4-36", "04-19"], ["c4", "Current ratio คำนวณอย่างไร บอกอะไร?", "Current assets ÷ Current liabilities\nใช้ดูความสามารถชำระหนี้ระยะสั้น", "Slide 4-37", "04-20"], ["c4", "Reversing entries คืออะไร ต้องทำไหม?", "ทางเลือก (ไม่บังคับ) ทำต้นงวดใหม่เพื่อกลับรายการ Accrued assets/liabilities ที่ปรับไว้ ทำให้บันทึกบัญชีง่ายขึ้น", "Slides 4-38 – 4-40", "04-21"], ["c5", "Service company กับ Merchandising company ต่างกันอย่างไร?", "Service = ขาย “เวลา/บริการ” (สำนักงานบัญชี กฎหมาย ช่างประปา)\nMerchandising = ซื้อสินค้ามาขาย มี Merchandise Inventory (ร้านกีฬา เสื้อผ้า อะไหล่รถ)", "Slides 5-2, 5-4", "05-1"], ["c5", "ลำดับช่องทางสินค้า Manufacturer → ? → ? → Consumers", "Manufacturer → Wholesaler → Retailer → Consumers\nWholesaler ขายให้ Retailer · Retailer ขายให้ผู้บริโภค", "Slide 5-3", "05-2"], ["c5", "Operating cycle ของ Merchandiser เริ่มและจบที่ไหน?", "เริ่มที่ “ซื้อสินค้า” → เก็บเป็น Inventory → ขาย → จบที่ “เก็บเงินสด” จากลูกค้า", "Slide 5-5", "05-3"], ["c5", "Perpetual vs Periodic inventory system?", "Perpetual = อัปเดต Inventory และ COGS ทุกครั้งที่ซื้อ/ขาย\nPeriodic = อัปเดตเฉพาะ “สิ้นงวด”", "Slides 5-7, 5-39", "05-4"], ["c5", "ซื้อสินค้าเงินสด $1,200 (Perpetual) บันทึกอย่างไร?", "Dr. Merchandise Inventory 1,200\n    Cr. Cash 1,200", "Slide 5-8", "05-5"], ["c5", "Trade discount คืออะไร? ราคาป้าย $5.25 ลด 30% ราคาจริงเท่าไร?", "ส่วนลดจากราคาป้ายเมื่อซื้อปริมาณมาก บันทึกตามราคาสุทธิ\n5.25 × 70% = $3.675 ต่อหน่วย", "Slide 5-9", "05-6"], ["c5", "Purchase discount คืออะไร?", "ส่วนลดจากราคาในใบแจ้งหนี้ เพื่อจูงใจให้ “จ่ายเร็ว”", "Slide 5-11", "05-7"], ["c5", "2/10, n/30 แปลว่าอะไร?", "ลด 2% ถ้าจ่ายภายใน 10 วัน\nไม่งั้นจ่ายเต็มจำนวนภายใน 30 วัน (Credit period)", "Slide 5-12", "05-8"], ["c5", "ซื้อเชื่อ $1,200 เงื่อนไข 2/10, n/30 แล้วจ่ายวันที่ 10 บันทึกอย่างไร?", "ซื้อ: Dr. Inventory 1,200 / Cr. A/P 1,200\nจ่าย: Dr. A/P 1,200 / Cr. Cash 1,176 / Cr. Inventory 24", "Slides 5-13–5-15", "05-9"], ["c5", "Purchase return กับ Purchase allowance ต่างกันอย่างไร?", "Return = ส่งสินค้าคืนผู้ขาย\nAllowance = เก็บสินค้าที่บกพร่องไว้ แต่ได้ลดราคา", "Slide 5-16", "05-10"], ["c5", "ผู้ซื้อออก Debit memorandum $300 ขอลดราคาสินค้าบกพร่อง บันทึกอย่างไร?", "Dr. Accounts Payable 300\n    Cr. Merchandise Inventory 300", "Slide 5-17", "05-11"], ["c5", "ซื้อ $1,000 (2/10, n/60) คืน $100 แล้วจ่ายในช่วงส่วนลด จ่ายเท่าไร?", "ส่วนลดคิดจากยอดคงเหลือ $900 → 2% = $18\nจ่ายเงินสด $882", "Slide 5-18", "05-12"], ["c5", "FOB shipping point vs FOB destination?", "Shipping point: กรรมสิทธิ์โอนตอนส่งของ ผู้ซื้อจ่ายค่าขนส่ง (Freight-in รวมในต้นทุน Inventory)\nDestination: โอนเมื่อถึงปลายทาง ผู้ขายจ่ายค่าขนส่ง", "Slides 5-19, 5-20", "05-13"], ["c5", "ซื้อ FOB shipping point ค่าขนส่ง $75 บันทึกอย่างไร?", "Dr. Merchandise Inventory 75\n    Cr. Cash 75 (Freight-in เป็นต้นทุนสินค้า)", "Slide 5-20", "05-14"], ["c5", "รายการขายใน Perpetual มี 2 ส่วนอะไร?", "1) รับรู้รายได้: Dr. Cash/AR · Cr. Sales\n2) รับรู้ต้นทุน: Dr. COGS · Cr. Merchandise Inventory", "Slide 5-23", "05-15"], ["c5", "ขายเชื่อ $2,400 ต้นทุน $1,600 บันทึกอย่างไร? กำไรขั้นต้นเท่าไร?", "Dr. AR 2,400 / Cr. Sales 2,400\nDr. COGS 1,600 / Cr. Inventory 1,600\nGross profit = $800", "Slide 5-24", "05-16"], ["c5", "Sales discount ช่วยผู้ขายอย่างไร? ขาย $1,000 (2/10) ลูกค้าจ่ายใน 10 วัน รับเงินเท่าไร?", "ได้เงินเร็วขึ้น ลดงานติดตามหนี้\nรับ $980 · Sales discount $20 (หักจาก Sales)", "Slides 5-25, 5-26", "05-17"], ["c5", "Sales return กับ Sales allowance ต่างกันอย่างไร?", "Return = ลูกค้าคืนสินค้า\nAllowance = ลดราคาให้ ลูกค้าเก็บสินค้าไว้", "Slide 5-27", "05-18"], ["c5", "ลูกค้าคืนสินค้าราคาขาย $800 ต้นทุน $600 ผู้ขายบันทึกอะไร?", "Dr. Sales Returns & Allowances 800 / Cr. AR 800\nDr. Merchandise Inventory 600 / Cr. COGS 600", "Slide 5-28", "05-19"], ["c5", "สูตร COGS?", "Beginning inventory + Net purchases = Merchandise available for sale\nCOGS = Available for sale − Ending inventory", "Slide 5-30", "05-20"], ["c5", "บัญชี Inventory $21,250 นับจริงได้ $21,000 ปรับอย่างไร?", "สินค้าขาดหาย (Shrinkage) $250\nDr. COGS 250 / Cr. Merchandise Inventory 250", "Slide 5-31", "05-21"], ["c5", "Gross profit ต่างจาก Net income อย่างไร?", "Gross profit = Net sales − COGS\nNet income = Gross profit − Operating expenses ± รายการอื่น", "Slide 5-33", "05-22"], ["c5", "Acid-test ratio คำนวณอย่างไร เกณฑ์เท่าไร?", "(Cash + S-T Investments + Current Receivables) ÷ Current Liabilities\nควร ≥ 1.0 (ไม่รวม Inventory)", "Slide 5-35", "05-23"], ["c5", "Gross margin ratio คำนวณอย่างไร?", "(Net sales − COGS) ÷ Net sales\n= สัดส่วนยอดขายที่เหลือไว้จ่ายค่าใช้จ่ายและเป็นกำไร", "Slide 5-36", "05-24"], ["c5", "Periodic system ตอนขายต่างจาก Perpetual อย่างไร?", "Periodic ไม่บันทึก COGS/ลด Inventory ทุกครั้งที่ขาย\nหา COGS ตอนสิ้นงวดจากการนับสินค้า", "Slides 5-39, 5-40", "05-25"], ["c6", "Merchandise inventory รวมสินค้าแบบไหน?", "สินค้าทุกชิ้นที่กิจการ “เป็นเจ้าของ” และถือไว้เพื่อขาย ไม่ว่าสินค้าจะอยู่ที่ไหนตอนนับ", "Slide 6-2", "06-1"], ["c6", "สินค้า 3 กลุ่มที่ต้องระวังตอนนับ Inventory?", "Goods in transit · Goods on consignment · Goods damaged or obsolete", "Slide 6-2", "06-2"], ["c6", "Goods in transit เป็นของใคร?", "FOB shipping point → ของผู้ซื้อตั้งแต่ส่งออก\nFOB destination → ยังเป็นของผู้ขายจนถึงปลายทาง", "Slide 6-3", "06-3"], ["c6", "Goods on consignment นับใน Inventory ของใคร?", "ของ Consignor (ผู้ฝากขาย ซึ่งเป็นเจ้าของ)\nไม่ใช่ Consignee (ร้านที่รับฝากขาย)", "Slide 6-4", "06-4"], ["c6", "สินค้าชำรุด/ล้าสมัย จัดการอย่างไร?", "ขายไม่ได้ → ไม่นับใน Inventory\nยังขายได้ → ลดมูลค่าเป็น NRV", "Slide 6-5", "06-5"], ["c6", "NRV (Net realizable value) คืออะไร?", "ราคาขายที่คาดว่าจะได้ − ต้นทุนที่ต้องทำให้เสร็จ − ต้นทุนที่จำเป็นในการขาย", "Slides 6-5, 6-27", "06-6"], ["c6", "ต้นทุน Inventory รวมอะไรบ้าง?", "Invoice cost − Discounts & Allowances + Import duties + Freight + Storage + Insurance\n(ทุกรายจ่ายที่ทำให้สินค้าพร้อมขาย)", "Slide 6-6", "06-7"], ["c6", "การควบคุมภายในตอนตรวจนับสินค้า 5 ข้อ?", "1) ใบนับมีเลขเรียง 2) คนนับไม่ใช่คนดูแลสินค้า 3) ยืนยันมีอยู่จริง จำนวน คุณภาพ 4) นับซ้ำครั้งที่สอง 5) ผู้จัดการยืนยันว่านับครบ", "Slide 6-7", "06-8"], ["c6", "ผู้บริหารต้องตัดสินใจเรื่อง Inventory 4 อะไร?", "1) อะไรนับเป็น Inventory และต้นทุนเท่าไร 2) วิธีคิดต้นทุน (Specific ID, FIFO, WAC) 3) ระบบ Perpetual/Periodic 4) ใช้ราคาตลาดหรือประมาณการไหม", "Slide 6-9", "06-9"], ["c6", "LIFO ใช้ได้ภายใต้ IFRS ไหม?", "ไม่ได้ LIFO ไม่อนุญาตภายใต้ IFRS", "Slides 6-9, 6-37", "06-10"], ["c6", "Specific identification, FIFO, Weighted average ต่างกันอย่างไร?", "Specific ID = ใช้ต้นทุนจริงของชิ้นที่ขาย\nFIFO = ต้นทุนที่เข้าก่อนออกก่อน\nWAC = ใช้ต้นทุนเฉลี่ยของสินค้าที่มี", "Slide 6-10", "06-11"], ["c6", "FIFO: COGS และ Ending inventory ใช้ต้นทุนชุดไหน?", "COGS = ต้นทุนเก่าสุด (Oldest)\nEnding inventory = ต้นทุนล่าสุด (Recent)", "Slide 6-15", "06-12"], ["c6", "Weighted average cost ต่อหน่วยคิดอย่างไร?", "Cost of goods available for sale ÷ Units on hand ณ วันขาย", "Slide 6-19", "06-13"], ["c6", "ต้นงวด 10 หน่วย @100 ซื้อเพิ่ม 10 @120 ขาย 12 หน่วย — COGS แบบ FIFO และ WAC?", "FIFO: (10×100)+(2×120) = 1,240 · EI = 8×120 = 960\nWAC: เฉลี่ย 2,200/20 = 110 → COGS 1,320 · EI 880", "ตำรา p.217–221", "06-14"], ["c6", "ข้อดีของ FIFO และ Weighted average ตามสไลด์?", "FIFO: Ending inventory ใกล้ต้นทุนทดแทนปัจจุบัน\nWAC: ช่วยเกลี่ยความผันผวนของราคา", "Slide 6-25", "06-15"], ["c6", "ราคาซื้อเพิ่มขึ้น FIFO ให้ผลอย่างไรเทียบกับวิธีเฉลี่ย?", "COGS ต่ำกว่า · กำไรสูงกว่า · Ending inventory สูงกว่า", "Slides 6-24, 6-25", "06-16"], ["c6", "Consistency คืออะไร เปลี่ยนวิธีได้ไหม?", "ใช้วิธีเดิมกับรายการเดิมทุกงวด (เชื่อมกับ Comparability)\nเปลี่ยนได้ถ้าทำให้รายงานดีขึ้น แต่ต้องเปิดเผยประเภท เหตุผล และผลต่อกำไรในหมายเหตุ", "Slide 6-26", "06-17"], ["c6", "Lower of cost and NRV ใช้อย่างไร?", "ถ้า NRV < Cost ให้แสดงที่ NRV\nทำได้ 2 แบบ: แยกรายสินค้า หรือตามกลุ่มหลัก\nบันทึก Dr. COGS / Cr. Inventory", "Slides 6-27–6-30", "06-18"], ["c6", "Ending inventory สูงเกินจริง กระทบอะไร?", "COGS ต่ำเกินจริง → กำไรสูงเกินจริง (งวดนี้)\nและงวดถัดไปจะผิดในทิศตรงข้าม", "Slides 6-31, 6-32", "06-19"], ["c6", "Inventory turnover คำนวณอย่างไร?", "COGS ÷ Average inventory\nAverage inventory = (ต้นงวด + ปลายงวด) ÷ 2", "Slide 6-33", "06-20"], ["c6", "Days’ sales in inventory คำนวณอย่างไร?", "(Ending inventory ÷ COGS) × 365\n= สินค้าคงเหลือพอขายได้กี่วัน", "Slide 6-34", "06-21"], ["c6", "เมื่อไหร่ต้องประมาณมูลค่า Inventory มีวิธีอะไร?", "งบระหว่างกาล หรือเกิดไฟไหม้/น้ำท่วมจนนับจริงไม่ได้\nวิธี: Retail inventory method · Gross profit method", "Slide 6-36", "06-22"], ["c7", "AIS (Accounting information system) ทำหน้าที่อะไร?", "เก็บและประมวลผลข้อมูลจากรายการค้า จัดเป็นรายงานที่มีประโยชน์ และสื่อสารผลให้ผู้ตัดสินใจ", "Slide 7-2", "07-1"], ["c7", "องค์ประกอบ 5 ส่วนของระบบบัญชี?", "Source documents · Input devices · Information processors · Information storage · Output devices", "Slides 7-3, 7-4", "07-2"], ["c7", "ตัวอย่าง Input devices และ Processor?", "Input: Keyboard, Scanner, Modem, Bar-code reader\nProcessor: Hardware, Software, Professional judgment", "Slide 7-3", "07-3"], ["c7", "ตัวอย่าง Storage และ Output devices?", "Storage: CD/DVD, Hard drive, Tape, Paper document\nOutput: Printer, Monitor, Projector, Web communications", "Slide 7-4", "07-4"], ["c7", "ทำไมใช้ Special journals?", "แยกรายการที่เกิดบ่อยตามประเภท (ขายเชื่อ ซื้อเชื่อ รับเงิน จ่ายเงิน) → บันทึกและ Post ยอดรวมได้เร็วและเป็นระบบ", "Slide 7-5", "07-5"], ["c7", "Special journals 4 แบบหลัก?", "Sales journal · Cash receipts journal · Purchases journal · Cash payments journal", "Slide 7-5", "07-6"], ["c7", "Subsidiary ledger คืออะไร?", "รายการบัญชีรายตัวที่มีลักษณะร่วมกัน เช่น ลูกหนี้แต่ละราย หรือเจ้าหนี้แต่ละราย", "Slide 7-6", "07-7"], ["c7", "Controlling account ของ AR ledger และ AP ledger คืออะไร?", "ลูกหนี้รายตัว → Accounts Receivable\nเจ้าหนี้รายตัว → Accounts Payable\n(อยู่ใน General ledger)", "Slide 7-6", "07-8"], ["c7", "Sales journal บันทึกอะไร?", "เฉพาะ “ขายเชื่อ” (Credit sales)\nขายเงินสด → Cash receipts journal", "Slides 7-8, 7-12", "07-9"], ["c7", "Proving the ledgers (AR) ทำอย่างไร?", "ทำ Schedule of accounts receivable (ลูกค้าแต่ละราย + ยอดค้าง)\nผลรวมต้องเท่ากับ AR controlling account", "Slide 7-9", "07-10"], ["c7", "Sales tax ที่เก็บจากลูกค้าเป็นรายได้ไหม?", "ไม่ใช่ เป็นเงินที่ต้องนำส่งหน่วยงานรัฐเป็นระยะ (หนี้สิน)", "Slide 7-10", "07-11"], ["c7", "Sales returns & allowances บันทึกที่ไหน?", "มีน้อย → General journal\nมีมาก → Sales returns and allowances journal", "Slide 7-11", "07-12"], ["c7", "Cash receipts มี 3 ประเภทอะไร?", "1) เงินจากลูกหนี้ (credit customers) 2) เงินจากขายสด 3) เงินจากแหล่งอื่น", "Slide 7-12", "07-13"], ["c7", "Footing, Crossfooting, Posting คืออะไร?", "Footing = รวมยอดแต่ละคอลัมน์\nCrossfooting = ตรวจว่ารวม Dr. เท่ากับรวม Cr.\nPosting = ผ่านยอดไปบัญชีแยกประเภทและบัญชีย่อย", "Slide 7-13", "07-14"], ["c7", "Proving the ledger (AP) ทำอย่างไร?", "ทำ Schedule of accounts payable (ผู้ขายแต่ละราย + ยอดที่ค้างจ่าย)\nผลรวมต้องเท่ากับ AP controlling account", "Slide 7-15", "07-15"], ["c7", "รายการแบบไหนบันทึกใน General journal?", "Adjusting entries · Closing entries · Sales returns & allowances · Purchase returns & allowances", "Slide 7-17", "07-16"], ["c7", "Off-the-shelf กับ Integrated software ต่างกันอย่างไร?", "Off-the-shelf = โปรแกรมสำเร็จรูปใช้ง่าย มีเมนู (เช่น QuickBooks)\nIntegrated = บันทึกที่จุดเดียว ระบบส่วนอื่นอัปเดตตามอัตโนมัติ", "Slide 7-18", "07-17"], ["c7", "Online processing กับ Batch processing ต่างกันอย่างไร?", "Online = ป้อนและประมวลผลทันที\nBatch = สะสมข้อมูลไว้แล้วประมวลผลพร้อมกัน (รายวัน/สัปดาห์/เดือน)", "Slide 7-19", "07-18"], ["c7", "Computer network ช่วยงานบัญชีอย่างไร?", "เชื่อม Server กับ Work stations ให้ผู้ใช้หลายคนเข้าถึงฐานข้อมูลและโปรแกรมเดียวกัน", "Slide 7-20", "07-19"], ["c7", "ERP คืออะไร?", "Enterprise resource planning = โปรแกรมที่จัดการและบูรณาการการดำเนินงานสำคัญทั้งองค์กร", "Slide 7-21", "07-20"], ["c7", "Segment คืออะไร?", "ส่วนของกิจการที่แยกได้ตามสินค้า บริการ หรือตลาดทางภูมิศาสตร์", "Slide 7-22", "07-21"], ["c7", "Segment return on assets คำนวณอย่างไร?", "Segment operating profit ÷ Segment average assets\nใช้ดูว่าส่วนงานใดใช้สินทรัพย์ได้คุ้มที่สุด", "Slide 7-23", "07-22"], ["c7", "Special journals ใน Periodic system ต่างอย่างไร?", "Sales journal ไม่มีคอลัมน์ COGS/Inventory\nการซื้อบันทึกเข้าบัญชี Purchases แทน Inventory", "Slides 7-24, 7-25", "07-23"], ["c7", "AR ย่อยรวม 9,200 แต่ AR control 9,000 ควรทำอะไร?", "หาการ Post ที่หาย ผิดยอด หรือซ้ำ ก่อนทำงบ — ห้ามปรับยอดโดยไม่มีหลักฐาน", "ตำรา ch.7", "07-24"], ["c8", "Internal control system มีเป้าหมาย 4 ข้ออะไร?", "1) ปกป้องสินทรัพย์ 2) ให้บัญชีเชื่อถือได้ 3) ส่งเสริมการดำเนินงานมีประสิทธิภาพ 4) ให้ทำตามนโยบายบริษัท", "Slide 8-2", "08-1"], ["c8", "หลักการควบคุมภายใน 7 ข้อ?", "1) กำหนดความรับผิดชอบ 2) เก็บหลักฐานให้พอ 3) ประกันทรัพย์สิน/ค้ำประกันพนักงานสำคัญ 4) แยกผู้บันทึกจากผู้ดูแลทรัพย์สิน 5) แบ่งหน้าที่ของรายการที่เกี่ยวข้อง 6) ใช้เทคโนโลยีควบคุม 7) ตรวจทานสม่ำเสมอโดยอิสระ", "Slide 8-3", "08-2"], ["c8", "เทคโนโลยีส่งผลต่อการควบคุมภายในอย่างไร?", "Error จากการประมวลผลลดลง · ทดสอบข้อมูลได้มากขึ้น · หลักฐานการประมวลผลน้อยลง · การแยกหน้าที่สำคัญมากขึ้น · E-commerce เพิ่มขึ้น", "Slide 8-4", "08-3"], ["c8", "Human error กับ Human fraud ต่างกันอย่างไร?", "Error = ไม่ตั้งใจ (Negligence, Fatigue, Misjudgment, Confusion)\nFraud = ตั้งใจเอาชนะการควบคุมเพื่อประโยชน์ส่วนตัว", "Slide 8-5", "08-4"], ["c8", "Fraud triple-threat มีอะไร?", "Opportunity · Pressure · Rationalization", "Slide 8-5", "08-5"], ["c8", "ข้อจำกัดด้านต้นทุนของการควบคุมภายใน?", "ต้นทุนของการควบคุมต้องไม่เกินประโยชน์ที่ได้", "Slide 8-6", "08-6"], ["c8", "แนวทางควบคุมเงินสด 3 ข้อ?", "1) แยกการถือเงินสดจากการบันทึกบัญชี 2) จ่ายเงินด้วยเช็ค 3) ฝากเงินรับเข้าธนาคารทันที", "Slide 8-7", "08-7"], ["c8", "Cash รวมอะไรบ้าง?", "ธนบัตร เหรียญ เงินฝากธนาคาร/กระแสรายวัน/ออมทรัพย์บางประเภท + เช็คลูกค้า แคชเชียร์เช็ค เช็ครับรอง ธนาณัติ", "Slide 8-8", "08-8"], ["c8", "Cash equivalents ต้องมีลักษณะอะไร?", "เงินลงทุนระยะสั้นสภาพคล่องสูงที่\n1) แปลงเป็นเงินสดจำนวนที่รู้แน่นอนได้ง่าย\n2) เสี่ยงต่อการเปลี่ยนมูลค่าน้อยมาก", "Slide 8-8", "08-9"], ["c8", "เป้าหมาย Cash management 2 ข้อ?", "1) วางแผนเงินรับให้พอจ่ายเมื่อถึงกำหนด\n2) ถือเงินสดขั้นต่ำเท่าที่จำเป็น", "Slide 8-9", "08-10"], ["c8", "หลัก Cash management 5 ข้อ?", "เร่งเก็บลูกหนี้ · ชะลอจ่ายหนี้ · ถือสินทรัพย์เท่าที่จำเป็น · วางแผนรายจ่าย · ลงทุนเงินสดส่วนเกิน", "Slide 8-9", "08-11"], ["c8", "เครื่องบันทึก $550 แต่นับได้ $555 บันทึกอย่างไร?", "Dr. Cash 555 / Cr. Cash over and short 5 / Cr. Sales 550\n(ถ้าขาด → Dr. Cash over and short)", "Slide 8-11", "08-12"], ["c8", "รับเงินทางไปรษณีย์ แบ่งหน้าที่อย่างไร?", "2 คนเปิดจดหมาย → Cashier นำเงินฝากธนาคาร → Recordkeeper บันทึกบัญชี", "Slide 8-12", "08-13"], ["c8", "ทำไมการควบคุมเงินจ่ายสำคัญ และหลักคืออะไร?", "การโกงก้อนใหญ่มักมาจากจ่ายตาม Invoice ปลอม\nหลัก: จ่ายทุกอย่างด้วยเช็ค · จำกัดการเข้าถึงเช็คเฉพาะผู้มีอำนาจลงนาม", "Slide 8-13", "08-14"], ["c8", "Voucher system ทำอะไร?", "1) ตรวจสอบ อนุมัติ บันทึกภาระหนี้ก่อน\n2) ออกเช็คจ่ายเฉพาะหนี้ที่ผ่านการตรวจ อนุมัติ และบันทึกแล้ว", "Slide 8-14", "08-15"], ["c8", "Petty cash ใช้กับรายจ่ายแบบไหน?", "รายจ่ายเล็กน้อยที่เกิดบ่อย เช่น ไปรษณีย์ ค่าส่งเอกสาร ซ่อมแซม วัสดุสิ้นเปลือง — ใช้เพื่อธุรกิจเท่านั้น", "Slides 8-16, 8-18", "08-16"], ["c8", "สัญญาณว่า Petty cash ถูกใช้ผิด?", "ใบสำคัญจ่ายที่ไม่มีลายเซ็น หรือลายเซ็นปลอม", "Slide 8-19", "08-17"], ["c8", "ตั้งกองทุนและเติมเงิน Petty cash บันทึกอย่างไร?", "ตั้ง: Dr. Petty cash / Cr. Cash\nเติม: Dr. ค่าใช้จ่ายตามใบสำคัญ / Cr. Cash (บัญชี Petty cash ไม่เปลี่ยน)", "Slides 8-17, 8-20", "08-18"], ["c8", "บริการพื้นฐานของธนาคารมีอะไร?", "Bank accounts · Signature cards · Deposit tickets · Checks · Electronic funds transfer · Bank statements", "Slide 8-22", "08-19"], ["c8", "Bank reconciliation คืออะไร?", "การอธิบายผลต่างระหว่างยอดเงินตาม Bank statement กับยอดในสมุดบัญชีของบริษัท", "Slide 8-24", "08-20"], ["c8", "ฝั่ง Bank ปรับอะไรบ้าง?", "Balance per bank\n+ Deposits in transit\n− Outstanding checks\n± Errors\n= Adjusted balance", "Slide 8-25", "08-21"], ["c8", "ฝั่ง Book ปรับอะไรบ้าง?", "Balance per book\n+ Collections & Interest\n− Uncollectible items (NSF, ค่าธรรมเนียม)\n± Errors\n= Adjusted balance", "Slide 8-25", "08-22"], ["c8", "ต้องทำ Adjusting entry ฝั่งไหน?", "เฉพาะรายการฝั่ง Book (ธนาคารบันทึกแล้วแต่บริษัทยังไม่รู้)", "Slides 8-25, 8-29", "08-23"], ["c8", "Days’ sales uncollected คำนวณอย่างไร?", "(Accounts receivable ÷ Net sales) × 365\n= อีกกี่วันจะได้รับเงินจากการขายเชื่อ", "Slide 8-30", "08-24"], ["c8", "เอกสารควบคุมการซื้อ (Appendix 8A) เรียงอย่างไร?", "Purchase requisition → Purchase order → Invoice → Receiving report → Voucher", "Slide 8-31", "08-25"], ["c8", "Net method ช่วยควบคุม Purchase discounts อย่างไร?", "บันทึกซื้อด้วยยอดสุทธิ ถ้าพลาดส่วนลดจะเกิดบัญชี Discounts lost (ค่าใช้จ่าย) ให้ผู้บริหารเห็น", "Slide 8-32", "08-26"], ["c9", "Receivable คืออะไร?", "จำนวนเงินที่บุคคลอื่นค้างชำระกิจการ\nต้องมีบัญชีแยกรายลูกค้า (ซื้อเท่าไร จ่ายแล้วเท่าไร ค้างเท่าไร)", "Slide 9-2", "09-1"], ["c9", "ขายเชื่อ 950 และรับชำระหนี้เก่า 720 บันทึกอย่างไร?", "Dr. Accounts receivable 950 / Cr. Sales 950\nDr. Cash 720 / Cr. Accounts receivable 720", "Slides 9-3, 9-4", "09-2"], ["c9", "ข้อดีของการรับบัตรเครดิต 3 ข้อ?", "1) โอนความเสี่ยงการให้เครดิตไปที่ผู้ออกบัตร 2) ยอดขายเพิ่ม 3) ได้เงินสดเร็วขึ้น", "Slide 9-5", "09-3"], ["c9", "ขายผ่านบัตร 100 ค่าธรรมเนียม 4% ได้เงินทันที บันทึกอย่างไร?", "Dr. Cash 96\nDr. Credit card expense 4\n   Cr. Sales 100", "Slide 9-6", "09-4"], ["c9", "Installment accounts receivable คืออะไร?", "ลูกหนี้จากการขายเชื่อที่ผ่อนชำระเป็นงวดในระยะยาว โดยทั่วไปคิดดอกเบี้ย", "Slide 9-8", "09-5"], ["c9", "วิธีบัญชีหนี้สูญ (Bad debts) มี 2 วิธีอะไร?", "Direct write-off method · Allowance method", "Slide 9-9", "09-6"], ["c9", "Direct write-off: ลูกหนี้ J. Kent 520 เก็บไม่ได้ บันทึกอย่างไร?", "Dr. Bad debts expense 520 / Cr. Accounts receivable—J. Kent 520", "Slide 9-10", "09-7"], ["c9", "Direct write-off: ลูกหนี้ที่ตัดแล้วกลับมาจ่าย บันทึกอย่างไร?", "1) Dr. Accounts receivable / Cr. Bad debts expense (คืนยอด)\n2) Dr. Cash / Cr. Accounts receivable", "Slide 9-11", "09-8"], ["c9", "ข้อดีของ Allowance method 2 ข้อ?", "1) บันทึกหนี้สูญโดยประมาณในงวดเดียวกับยอดขาย\n2) แสดงลูกหนี้ในงบด้วยยอดที่คาดว่าจะเก็บได้", "Slide 9-12", "09-9"], ["c9", "ประมาณหนี้สูญ 1,500 ตอนสิ้นปี บันทึกอย่างไร?", "Dr. Bad debts expense 1,500 / Cr. Allowance for doubtful accounts 1,500\nงบ: AR 20,000 − Allowance 1,500 = 18,500", "Slides 9-13, 9-14", "09-10"], ["c9", "Allowance method: ตัดหนี้สูญ 520 บันทึกอย่างไร กระทบยอดสุทธิไหม?", "Dr. Allowance for doubtful accounts 520 / Cr. Accounts receivable 520\nไม่กระทบ Realizable value ของลูกหนี้", "Slides 9-15, 9-16", "09-11"], ["c9", "Allowance method: ลูกหนี้ที่ตัดแล้วกลับมาจ่าย 520?", "1) Dr. Accounts receivable 520 / Cr. Allowance 520\n2) Dr. Cash 520 / Cr. Accounts receivable 520", "Slide 9-17", "09-12"], ["c9", "Percent of receivables: หา Bad debts expense อย่างไร?", "1) หายอด Allowance ที่ต้องการ = AR × %\n2) Expense = ยอดที่ต้องการ − ยอดเครดิตเดิมใน Allowance", "Slide 9-19", "09-13"], ["c9", "AR 50,000 คาดสูญ 5% Allowance เครดิตเดิม 200 → Bad debts expense?", "2,500 − 200 = 2,300", "Slide 9-20", "09-14"], ["c9", "Aging of receivables ทำ 3 ขั้นอะไร?", "1) แบ่งลูกหนี้ตามจำนวนวันที่ค้าง 2) คูณแต่ละกลุ่มด้วย % หนี้สูญ 3) รวมยอดประมาณ", "Slide 9-21", "09-15"], ["c9", "Aging ได้ยอดที่ต้องการ 2,270 Allowance มีเครดิต 200 → ปรับเท่าไร?", "2,270 − 200 = 2,070\nDr. Bad debts expense 2,070 / Cr. Allowance 2,070", "Slide 9-23", "09-16"], ["c9", "AR 71,200 มีรายหนึ่ง 6,000 คาดสูญ 10% ที่เหลือ 2% Allowance เดิม 1,700 → ตั้งเพิ่มเท่าไร?", "10%×6,000 + 2%×65,200 = 600 + 1,304 = 1,904\n1,904 − 1,700 = 204", "Slide 9-25", "09-17"], ["c9", "Promissory note คืออะไร?", "คำมั่นเป็นลายลักษณ์อักษรว่าจะจ่ายเงินจำนวนที่ระบุ (มักมีดอกเบี้ย) เมื่อทวงถามหรือในวันที่กำหนด", "Slide 9-26", "09-18"], ["c9", "ตั๋ว 1,000 12% 90 วัน ลงวันที่ 10 ก.ค. ครบกำหนดวันไหน ดอกเบี้ยเท่าไร?", "ครบ 8 ต.ค.\nดอกเบี้ย = 1,000 × 12% × 90/360 = 30 (ใช้ฐาน 360 วัน)", "Slides 9-27, 9-28", "09-19"], ["c9", "รับตั๋วเงินจากการขายสินค้า บันทึกอย่างไร?", "Dr. Notes receivable / Cr. Sales (ตามเงินต้น)", "Slide 9-29", "09-20"], ["c9", "ตั๋ว 600 15% 60 วันได้รับชำระ (Honored) บันทึกอย่างไร?", "ดอกเบี้ย = 600 × 15% × 60/360 = 15\nDr. Cash 615 / Cr. Notes receivable 600 / Cr. Interest revenue 15", "Slide 9-30", "09-21"], ["c9", "Dishonored note คืออะไร ลูกหนี้ยังต้องจ่ายไหม?", "ผู้ออกตั๋วไม่ชำระเมื่อครบกำหนด แต่ยังมีภาระจ่ายเงินต้นและดอกเบี้ย → โอนเป็น Accounts receivable", "Slide 9-31", "09-22"], ["c9", "ตั๋ว 3,000 12% 60 วัน รับ 16 ธ.ค. ดอกเบี้ยค้างรับ ณ 31 ธ.ค.?", "3,000 × 12% × 15/360 = 15\nDr. Interest receivable 15 / Cr. Interest revenue 15\n(ทั้งตั๋ว = 60)", "Slides 9-32, 9-33", "09-23"], ["c9", "เปลี่ยนลูกหนี้เป็นเงินสดก่อนครบกำหนดได้ 2 วิธีอะไร?", "Selling receivables · Pledging receivables (ใช้เป็นหลักประกัน)", "Slide 9-34", "09-24"], ["c9", "Accounts receivable turnover คำนวณอย่างไร?", "Net sales ÷ Average accounts receivable (net)\nบอกประสิทธิภาพการให้เครดิตเพื่อสร้างรายได้", "Slide 9-35", "09-25"], ["c6", "หา COGS แบบ Periodic ทำอย่างไร?", "ไม่มีบัญชีตัดต้นทุนทุกครั้งที่ขาย → นับสินค้าปลายงวดแล้วคำนวณย้อน\nBeginning inventory\n+ Cost of goods purchased (Purchases − Returns − Discounts + Freight-in)\n= Cost of goods available for sale\n− Ending inventory\n= COGS", "สรุปเพิ่มเติม", "06-23"], ["c6", "Perpetual กับ Periodic ต่างกันอย่างไรในการหา COGS?", "Perpetual: ตัด Dr. COGS / Cr. Inventory ทุกครั้งที่ขาย รู้ COGS และ Inventory ตลอดเวลา\nPeriodic: ไม่ตัดตอนขาย ปลายงวดนับ Ending inventory แล้วหา COGS = Available for sale − Ending inventory\nFIFO Periodic: Ending inventory = ต้นทุนล็อตล่าสุด", "สรุปเพิ่มเติม", "06-24"]], "sum": [{"cat": "c1", "h": "พื้นฐานการบัญชี", "head": ["หัวข้อ", "สรุป"], "rows": [["Accounting", "ระบบข้อมูล: Identify → Record → Communicate"], ["สมการบัญชี", "Assets = Liabilities + Equity"], ["งบ 4 งบ", "IS · SCE · SFP · SCF"], ["ROA", "Net income ÷ Avg total assets"]], "tip": "Fraud Triangle: Opportunity · Pressure · Rationalization"}, {"cat": "c1", "h": "หลักการและข้อสมมติ", "head": ["หัวข้อ", "สรุป"], "rows": [["Cost", "บันทึกที่ราคาทุนจริง"], ["Revenue recognition", "รับรู้เมื่อเกิดขึ้น"], ["Matching", "ค่าใช้จ่ายงวดเดียวกับรายได้"], ["Full disclosure", "เปิดเผยข้อมูลสำคัญ"], ["Assumptions", "Going-concern · Monetary unit · Business entity · Time period"]]}, {"cat": "c2", "h": "กฎ Debit / Credit", "head": ["หัวข้อ", "สรุป"], "rows": [["Assets", "เพิ่ม Dr · ลด Cr"], ["Liabilities / Equity", "เพิ่ม Cr · ลด Dr"], ["Revenue", "เพิ่ม Cr"], ["Expenses / Withdrawals", "เพิ่ม Dr"]], "tip": "Trial balance เท่ากัน ≠ ไม่มีข้อผิดพลาด"}, {"cat": "c2", "h": "วงจรบันทึกรายการ", "head": ["หัวข้อ", "สรุป"], "rows": [["1", "Analyze source documents"], ["2", "Journalize"], ["3", "Post to ledger"], ["4", "Trial balance"]]}, {"cat": "c3", "h": "Adjusting entries 4 แบบ", "head": ["หัวข้อ", "สรุป"], "rows": [["Prepaid expense", "Dr Expense / Cr Prepaid asset"], ["Unearned revenue", "Dr Unearned Rev / Cr Revenue"], ["Accrued expense", "Dr Expense / Cr Payable"], ["Accrued revenue", "Dr Receivable / Cr Revenue"], ["Depreciation", "Dr Dep. Expense / Cr Accum. Dep."]], "tip": "Straight-line = (Cost − Salvage) ÷ Life"}, {"cat": "c4", "h": "Closing process", "head": ["หัวข้อ", "สรุป"], "rows": [["ขั้น 1", "Dr Revenues / Cr Income Summary"], ["ขั้น 2", "Dr Income Summary / Cr Expenses"], ["ขั้น 3", "โอน Income Summary เข้า Capital"], ["ขั้น 4", "Dr Capital / Cr Withdrawals"]], "tip": "หลังปิด: เหลือเฉพาะ permanent accounts"}, {"cat": "c4", "h": "Classified balance sheet", "head": ["หัวข้อ", "สรุป"], "rows": [["Current", "ภายใน 1 ปี/operating cycle"], ["Long-term investments", "ถือระยะยาว"], ["PP&E", "สินทรัพย์ถาวรมีตัวตน"], ["Intangibles", "ไม่มีตัวตน"], ["Current ratio", "CA ÷ CL"]]}, {"cat": "c5", "h": "บัญชีสินค้า Perpetual", "head": ["หัวข้อ", "สรุป"], "rows": [["ซื้อ", "Dr Inventory / Cr A/P (หรือ Cash)"], ["ขาย", "Dr A/R / Cr Sales + Dr COGS / Cr Inventory"], ["ส่งคืน", "ลด Inventory (ผู้ซื้อ) · Sales R&A (ผู้ขาย)"], ["Freight-in", "เพิ่มต้นทุน Inventory"], ["Terms 2/10, n/30", "จ่ายใน 10 วัน ลด 2%"]]}, {"cat": "c5", "h": "อัตราส่วน", "head": ["หัวข้อ", "สรุป"], "rows": [["Gross margin ratio", "(Net sales − COGS) ÷ Net sales"], ["Acid-test", "Quick assets ÷ CL"]]}, {"cat": "c5", "h": "Service vs. Merchandising Companies (กิจการให้บริการ vs. กิจการซื้อขายสินค้า)", "head": ["Topic", "Summary"], "rows": [["Service Company (กิจการให้บริการ)", "Earns revenue by providing services. Income statement shows Revenues - Expenses = Net Income.\n• ภาษาไทย: มีรายได้หลักจากการให้บริการ ไม่มีบัญชีสินค้าคงเหลือและต้นทุนขาย"], ["Merchandising Company (กิจการซื้อขายสินค้า)", "Buys and sells merchandise inventory (retailers and wholesalers).\n• ภาษาไทย: ซื้อสินค้าสำเร็จรูปมาเพื่อขายต่อ แบ่งเป็นร้านค้าปลีก (Retailer) และร้านค้าส่ง (Wholesaler)"], ["Income Measurement Process (การวัดผลการดำเนินงาน)", "Sales Revenue - Cost of Goods Sold (COGS) = Gross Profit\nGross Profit - Operating Expenses = Net Income"]]}, {"cat": "c5", "h": "Inventory Systems: Perpetual vs. Periodic (ระบบบัญชีสินค้าคงเหลือ)", "head": ["Topic", "Summary"], "rows": [["**Inventory Account Tracking**", "Perpetual Inventory System (ระบบบันทึกต่อเนื่อง): Updated continuously after every purchase and sale.\n(บันทึกเข้า-ออกบัญชี Inventory ทันทีทุกครั้งที่ซื้อและขาย)\nPeriodic Inventory System (ระบบบันทึกเมื่อสิ้นงวด): Updated only at the end of the accounting period via physical count.\n(ปรับปรุงยอดสินค้าคงเหลือเฉพาะตอนสิ้นงวดจากการตรวจนับจริง)"], ["**COGS Recording**", "Perpetual Inventory System (ระบบบันทึกต่อเนื่อง): Recorded at the time of each sale.\n(บันทึกต้นทุนขายทันทีทุกครั้งที่ขายสินค้า)\nPeriodic Inventory System (ระบบบันทึกเมื่อสิ้นงวด): Calculated at period-end:\nCOGS = Beg. Inv. + Net Purchases - End. Inv."], ["**Purchase of Goods**", "Perpetual Inventory System (ระบบบันทึกต่อเนื่อง): Dr. Inventory / Cr. Accounts Payable (or Cash)\nPeriodic Inventory System (ระบบบันทึกเมื่อสิ้นงวด): Dr. Purchases / Cr. Accounts Payable (or Cash)"], ["**Freight-In (ค่าขนส่งเข้า)**", "Perpetual Inventory System (ระบบบันทึกต่อเนื่อง): Dr. Inventory / Cr. Cash\nPeriodic Inventory System (ระบบบันทึกเมื่อสิ้นงวด): Dr. Freight-In / Cr. Cash"], ["**Purchase Returns & Discounts**", "Perpetual Inventory System (ระบบบันทึกต่อเนื่อง): Cr. Inventory (ลดยอด Inventory โดยตรง)\nPeriodic Inventory System (ระบบบันทึกเมื่อสิ้นงวด): Cr. Purchase Returns & Allowances / Purchase Discounts"], ["**Sale of Goods**", "Perpetual Inventory System (ระบบบันทึกต่อเนื่อง): **2 Entries:**\n1. Dr. AR (or Cash) / Cr. Sales Revenue\n2. Dr. COGS / Cr. Inventory\nPeriodic Inventory System (ระบบบันทึกเมื่อสิ้นงวด): **1 Entry:**\n1. Dr. AR (or Cash) / Cr. Sales Revenue"]]}, {"cat": "c5", "h": "Freight Costs & Credit Terms (เงื่อนไขค่าขนส่งและส่วนลดการค้า)", "head": ["Topic", "Summary"], "rows": [["FOB Shipping Point (ส่งมอบ ณ ต้นทาง)", "• **Ownership (กรรมสิทธิ์):** Transfers to the **buyer** when the carrier accepts the goods from the seller. (โอนเป็นของผู้ซื้อทันทีเมื่อสินค้าออกจากคลังผู้ขาย)\n• **Freight Paid By (ผู้รับผิดชอบค่าขนส่ง):** **Buyer** pays freight → **Freight-In** (added to the cost of Inventory)."], ["FOB Destination (ส่งมอบ ณ ปลายทาง)", "• **Ownership (กรรมสิทธิ์):** Transfers to the **buyer** when the goods arrive at the buyer's location. (โอนเป็นของผู้ซื้อเมื่อสินค้าถึงคลังผู้ซื้อ)\n• **Freight Paid By (ผู้รับผิดชอบค่าขนส่ง):** **Seller** pays freight → **Freight-Out / Delivery Expense** (Operating Expense on seller's Income Statement)."], ["Credit Terms Example: 2/10, n/30", "• 2/10: Buyer gets a 2% cash discount if paid within 10 days of the invoice date. (ได้ส่วนลดเงินสด 2% หากชำระภายใน 10 วัน)\n• n/30: Net amount (full amount) is due within 30 days if discount is missed. (ต้องชำระเต็มจำนวนภายใน 30 วัน)\n• **Important Trap (ข้อควรระวังในการสอบ):** Purchase/Sales discounts apply **ONLY** to the net merchandise price after deducting any returns and allowances, and **NEVER** apply to freight charges! (คิดส่วนลดจากยอดหลังหักรับคืน/ส่งคืนแล้วเท่านั้น และไม่คิดส่วนลดจากค่าขนส่ง)"]]}, {"cat": "c5", "h": "Key Journal Entries under Perpetual System (การบันทึกบัญชีระบบ Perpetual)", "head": ["Topic", "Summary"], "rows": [["Purchase Inventory on Account (ซื้อสินค้าเป็นเงินเชื่อ)", "• Dr. Inventory / Cr. Accounts Payable"], ["Purchase Return / Allowance (ส่งคืนสินค้า / ได้รับส่วนลดเนื่องจากสินค้าชำรุด)", "• Dr. Accounts Payable / Cr. Inventory"], ["Payment within Discount Period (ชำระหนี้ภายในกำหนดส่วนลด)", "• Dr. Accounts Payable (Full balance owed)\n• Cr. Inventory (Discount amount)\n• Cr. Cash (Net cash paid)"], ["Sale of Inventory on Account (ขายสินค้าเป็นเงินเชื่อ)", "• Entry 1 (Selling price): Dr. Accounts Receivable / Cr. Sales Revenue\n• Entry 2 (Cost price): Dr. Cost of Goods Sold / Cr. Inventory"], ["Sales Return from Customer (รับคืนสินค้าจากลูกค้า - กรณีสินค้านำกลับมาขายใหม่ได้)", "• Entry 1 (Selling price): Dr. Sales Returns and Allowances / Cr. Accounts Receivable\n• Entry 2 (Cost price): Dr. Inventory / Cr. Cost of Goods Sold\n• (Note: If returned goods are damaged/scrap, Debit Inventory only for their scrap/fair value.)"], ["Collection from Customer within Discount Period (รับชำระหนี้ภายในกำหนดส่วนลด)", "• Dr. Cash (Net cash received)\n• Dr. Sales Discounts (Discount amount)\n• Cr. Accounts Receivable (Full balance owed)"]]}, {"cat": "c5", "h": "Multiple-Step Income Statement & Ratios (งบกำไรขาดทุนแบบหลายขั้นและอัตราส่วน)", "head": ["Topic", "Summary"], "rows": [["Net Sales (ขายสุทธิ)", "Net Sales = Sales Revenue - Sales Returns and Allowances - Sales Discounts\n(Note: Sales Returns and Allowances and Sales Discounts are **Contra-Revenue** accounts with a normal **Debit** balance.)"], ["Sections of Multiple-Step Income Statement", "• **Sales Revenue** → Net Sales\n• **Cost of Goods Sold** → Subtract from Net Sales to get **Gross Profit**\n• **Operating Expenses** (Selling Expenses + Administrative Expenses) → Subtract from Gross Profit to get **Income from Operations**\n• **Non-Operating Activities** (Other Revenues and Gains e.g. Interest Revenue, Gain on Sale of Plant Assets; Other Expenses and Losses e.g. Interest Expense, Casualty Loss)\n• **Income Tax Expense** → **Net Income**"], ["Key Profitability Ratios", "Gross Profit Rate = (Gross Profit) / (Net Sales) × 100%\nProfit Margin = (Net Income) / (Net Sales) × 100%"]]}, {"cat": "c6", "h": "วิธีต้นทุนสินค้า", "head": ["หัวข้อ", "สรุป"], "rows": [["Specific ID", "ตามชิ้นจริง"], ["FIFO", "เก่าออกก่อน Ending ใกล้ต้นทุนปัจจุบัน"], ["LIFO", "ใหม่ออกก่อน (ไม่อนุญาตใน IFRS)"], ["Weighted avg", "เฉลี่ย"]], "tip": "ราคาขึ้น: FIFO กำไรสูงสุด · LIFO กำไรต่ำสุด"}, {"cat": "c6", "h": "การวัดมูลค่าและอัตราส่วน", "head": ["หัวข้อ", "สรุป"], "rows": [["LCNRV", "รายงานที่ต่ำกว่าของ cost และ NRV"], ["Inventory turnover", "COGS ÷ Avg inventory"], ["Days' sales in inventory", "Ending inv ÷ COGS × 365"], ["Error", "Ending inv สูง → กำไรสูงเกิน"]]}, {"cat": "c6", "h": "Determining Inventory Quantities & Ownership (การตรวจนับและกรรมสิทธิ์ในสินค้า)", "head": ["Topic", "Summary"], "rows": [["Goods in Transit (สินค้าระหว่างทาง ณ วันสิ้นงวด)", "• **FOB Shipping Point:** Belongs to the **Buyer** (include in Buyer's ending inventory).\n• **FOB Destination:** Belongs to the **Seller** (include in Seller's ending inventory)."], ["Consigned Goods (สินค้าฝากขาย)", "• Belong to the **Consignor (ผู้ฝากขาย)** until sold to a third party. Do **NOT** include in the Consignee's (ผู้รับฝากขาย) ending inventory."]]}, {"cat": "c6", "h": "Inventory Costing Methods (วิธีการคำนวณต้นทุนสินค้าคงเหลือ)", "head": ["Topic", "Summary"], "rows": [["Formula", "Cost of Goods Available for Sale (COGAS) = Beginning Inventory + Net Purchases"], ["Formula", "COGAS = Ending Inventory + Cost of Goods Sold (COGS)"], ["Specific Identification (วิธีราคาเจาะจง)", "Tracks the actual physical flow of each individual item (used for cars, jewelry, real estate)."], ["FIFO — First-In, First-Out (วิธีเข้าก่อน-ออกก่อน)", "• Earliest goods purchased are the first to be sold (→ **COGS** uses oldest costs).\n• Most recent purchases remain in **Ending Inventory** (→ closest to current replacement cost)."], ["LIFO — Last-In, First-Out (วิธีเข้าหลัง-ออกก่อน)", "(Allowed under US GAAP, **prohibited under IFRS**)\n• Most recent goods purchased are the first to be sold (→ **COGS** uses newest costs).\n• Earliest purchases remain in **Ending Inventory**."], ["Weighted-Average Cost — WAC (วิธีต้นทุนถัวเฉลี่ยถ่วงน้ำหนัก)", "• **Periodic System (Weighted Average):**\nWeighted-Average Unit Cost = (Cost of Goods Available for Sale) / Total Units Available for Sale\n• **Perpetual System (Moving Average):** Recomputes a new average unit cost after every purchase."], ["▸ Financial Statement Effects During Rising Prices / Inflation (ผลกระทบเมื่อราคาสินค้าสูงขึ้น)", ""], ["**Ending Inventory (สินค้าปลายงวด)**", "FIFO (เข้าก่อน-ออกก่อน): **Highest** (สูงสุด)\nWeighted Average (ถัวเฉลี่ย): Middle (ปานกลาง)\nLIFO (เข้าหลัง-ออกก่อน): **Lowest** (ต่ำสุด)"], ["**Cost of Goods Sold (ต้นทุนขาย)**", "FIFO (เข้าก่อน-ออกก่อน): **Lowest** (ต่ำสุด)\nWeighted Average (ถัวเฉลี่ย): Middle (ปานกลาง)\nLIFO (เข้าหลัง-ออกก่อน): **Highest** (สูงสุด)"], ["**Gross Profit & Net Income (กำไรสุทธิ)**", "FIFO (เข้าก่อน-ออกก่อน): **Highest** (สูงสุด)\nWeighted Average (ถัวเฉลี่ย): Middle (ปานกลาง)\nLIFO (เข้าหลัง-ออกก่อน): **Lowest** (ต่ำสุด)"], ["**Income Taxes (ภาษีเงินได้)**", "FIFO (เข้าก่อน-ออกก่อน): **Highest** (สูงสุด)\nWeighted Average (ถัวเฉลี่ย): Middle (ปานกลาง)\nLIFO (เข้าหลัง-ออกก่อน): **Lowest** (ต่ำสุด - ประหยัดภาษี)"]]}, {"cat": "c6", "h": "Lower-of-Cost-or-Net-Realizable-Value (LCNRV) (การตีราคาสินค้าด้วยราคาทุนหรือมูลค่าสุทธิที่จะได้รับที่ต่ำกว่า)", "head": ["Topic", "Summary"], "rows": [["Conservatism Principle (หลักความระมัดระวัง)", "If inventory declines in value below its original cost, write it down to **Net Realizable Value (NRV)**."], ["Formula", "NRV = Estimated Selling Price - Estimated Costs to Complete and Sell"], ["Journal Entry for Write-Down", "• Dr. Cost of Goods Sold (or Loss on Inventory Write-Down) / Cr. Inventory"], ["IFRS vs. US GAAP Note", "Under **IFRS**, subsequent recoveries in NRV allow reversal of previous write-downs (up to original cost). Under **US GAAP**, reversals are **prohibited**."]]}, {"cat": "c6", "h": "Inventory Errors & Two-Year Self-Correcting Effect (ข้อผิดพลาดของสินค้าคงเหลือ)", "head": ["Topic", "Summary"], "rows": [["Note", "Use the master equation: Beg. Inv. + Net Purchases - End. Inv. = COGS"], ["**Beginning Inventory Understated** (สินค้าต้นงวดต่ำไป)", "Effect on COGS (ต้นทุนขาย): **Understated** (ต่ำไป)\nEffect on Net Income (กำไรสุทธิ): **Overstated** (สูงไป)\nEffect on Assets & Equity (สินทรัพย์และส่วนของเจ้าของ): No effect on Year-End Assets/Equity (assuming Ending Inv. is correct)"], ["**Beginning Inventory Overstated** (สินค้าต้นงวดสูงไป)", "Effect on COGS (ต้นทุนขาย): **Overstated** (สูงไป)\nEffect on Net Income (กำไรสุทธิ): **Understated** (ต่ำไป)\nEffect on Assets & Equity (สินทรัพย์และส่วนของเจ้าของ): No effect on Year-End Assets/Equity"], ["**Ending Inventory Understated** (สินค้าปลายงวดต่ำไป)", "Effect on COGS (ต้นทุนขาย): **Overstated** (สูงไป)\nEffect on Net Income (กำไรสุทธิ): **Understated** (ต่ำไป)\nEffect on Assets & Equity (สินทรัพย์และส่วนของเจ้าของ): **Understated** (ต่ำไป)"], ["**Ending Inventory Overstated** (สินค้าปลายงวดสูงไป)", "Effect on COGS (ต้นทุนขาย): **Understated** (ต่ำไป)\nEffect on Net Income (กำไรสุทธิ): **Overstated** (สูงไป)\nEffect on Assets & Equity (สินทรัพย์และส่วนของเจ้าของ): **Overstated** (สูงไป)"], ["Two-Year Rule (กฎการชดเชยอัตโนมัติใน 2 ปี)", "Year 1's Ending Inventory is Year 2's Beginning Inventory. Therefore, an Ending Inventory error in Year 1 causes an **opposite** error in Year 2's Net Income. After 2 years, total 2-year Net Income and Year 2 Ending Retained Earnings are **correct**!"]]}, {"cat": "c6", "h": "Inventory Estimation Methods & Ratios (การประมาณราคาสินค้าคงเหลือและอัตราส่วน)", "head": ["Topic", "Summary"], "rows": [["Gross Profit Method (วิธีอัตรากำไรขั้นต้น)", "Estimated Gross Profit = Net Sales × Gross Profit Rate\nEstimated COGS = Net Sales - Estimated Gross Profit\nEstimated Ending Inventory = Cost of Goods Available for Sale - Estimated COGS"], ["Retail Inventory Method (วิธีราคาขายปลีก)", "Cost-to-Retail Ratio = (Goods Available for Sale at Cost) / Goods Available for Sale at Retail\nEnding Inventory at Retail = Goods Available for Sale at Retail - Net Sales\nEstimated Ending Inventory at Cost = Ending Inventory at Retail × Cost-to-Retail Ratio"], ["Inventory Ratios", "Inventory Turnover = (Cost of Goods Sold) / (Average Inventory), where Average Inventory = (Beg. Inv. + End. Inv.) / 2\nDays in Inventory = 365 / Inventory Turnover"]]}, {"cat": "c7", "h": "AIS และ Special journals", "head": ["หัวข้อ", "สรุป"], "rows": [["Sales journal", "ขายเชื่อ"], ["Cash receipts", "รับเงินสดทุกชนิด"], ["Purchases journal", "ซื้อเชื่อ"], ["Cash payments", "จ่ายเงินสดทุกชนิด"], ["General journal", "ปรับ ปิด ส่งคืน"], ["Subsidiary ledger", "ผลรวม = Controlling account"]]}, {"cat": "c7", "h": "Principles of Accounting Information Systems (หลักการของระบบสารสนเทศทางการบัญชี)", "head": ["Topic", "Summary"], "rows": [["Cost-Effectiveness (คุ้มค่ากับต้นทุน)", "Benefits of information must outweigh the cost of providing it."], ["Usefulness (มีประโยชน์ต่อการตัดสินใจ)", "Understandable, relevant, reliable, timely, and comparable."], ["Flexibility (มีความยืดหยุ่น)", "Able to accommodate business growth and changes in reporting needs."]]}, {"cat": "c7", "h": "Subsidiary Ledgers & Control Accounts (บัญชีแยกประเภทย่อยและบัญชีคุมยอด)", "head": ["Topic", "Summary"], "rows": [["Subsidiary Ledger (บัญชีแยกประเภทย่อย)", "Groups of accounts with a common characteristic (provides individual details).\n• **Accounts Receivable Subsidiary Ledger (บัญชีลูกหนี้รายตัว):** Tracks balances owed by each individual customer.\n• **Accounts Payable Subsidiary Ledger (บัญชีเจ้าหนี้รายตัว):** Tracks balances owed to each individual supplier/creditor."], ["Control Account (บัญชีคุมยอด)", "General Ledger summary account (Accounts Receivable or Accounts Payable) whose balance **must equal** the sum of all individual balances in its respective subsidiary ledger at the end of the period."], ["Advantages", "Frees the general ledger from excessive detail, provides up-to-date individual balances, enables division of labor, and helps locate errors."]]}, {"cat": "c7", "h": "Special Journals (สมุดรายวันเฉพาะ)", "head": ["Topic", "Summary"], "rows": [["Note", "Used to group similar types of routine transactions to speed up recording and posting:"], ["**Sales Journal (S)** (สมุดรายวันขาย)", "Types of Transactions Recorded (รายการที่บันทึก): **Credit sales of merchandise inventory ONLY.**\n(ขายสินค้าเป็นเงินเชื่อเท่านั้น)\nPosting Rules (หลักการผ่านรายการ): **Daily:** Individual debits to AR Subsidiary Ledger.\n**Monthly:** Column totals to GL (Dr. AR / Cr. Sales & Dr. COGS / Cr. Inv.)."], ["**Cash Receipts Journal (CR)** (สมุดรายวันรับเงิน)", "Types of Transactions Recorded (รายการที่บันทึก): **All receipts of cash** (cash sales, collections from customers on account, cash from sale of assets/notes/loans).\n(รายการรับเงินสดทุกประเภท)\nPosting Rules (หลักการผ่านรายการ): **Daily:** Individual credits to AR Subsidiary Ledger & \"Other Accounts\" to GL.\n**Monthly:** Special column totals (Cash, Sales Discounts, AR, Sales) to GL."], ["**Purchases Journal (P)** (สมุดรายวันซื้อ)", "Types of Transactions Recorded (รายการที่บันทึก): **Purchases on account.** (Single-column PJ = credit purchases of merchandise inventory only; Multi-column PJ = credit purchases of inventory, supplies, equipment).\n(ซื้อสินค้า/สินทรัพย์เป็นเงินเชื่อ)\nPosting Rules (หลักการผ่านรายการ): **Daily:** Individual credits to AP Subsidiary Ledger.\n**Monthly:** Column totals to GL (Dr. Inventory / Cr. AP)."], ["**Cash Payments Journal (CP)** (สมุดรายวันจ่ายเงิน)", "Types of Transactions Recorded (รายการที่บันทึก): **All disbursements/payments of cash** (cash purchases, payments to suppliers on account, cash expenses, dividends, petty cash).\n(รายการจ่ายเงินสดทุกประเภท)\nPosting Rules (หลักการผ่านรายการ): **Daily:** Individual debits to AP Subsidiary Ledger & \"Other Accounts\" to GL.\n**Monthly:** Special column totals (AP, Inventory/Discounts, Cash) to GL."], ["**General Journal (G)** (สมุดรายวันทั่วไป)", "Types of Transactions Recorded (รายการที่บันทึก): Transactions that **cannot** be entered in any special journal: **adjusting entries, closing entries, correcting entries, purchase returns on account, sales returns on account, issuance/receipt of notes**, credit purchases/sales of plant assets (if single-column PJ/SJ).\nPosting Rules (หลักการผ่านรายการ): **Daily / At period-end:** Every line is posted individually to GL (and to AR/AP Subsidiary Ledger if AR/AP is affected — dual posting ✓ and account number)."], ["Crucial Posting Trap (ข้อควรระวังในการผ่านรายการ)", "• Totals of **Special Columns** (e.g., Cash, AR, AP, Sales) are posted **monthly** to the General Ledger.\n• The total of the **\"Other Accounts\" column** is **NEVER posted** (marked with an X below the total) because each item in that column was already posted **individually** to its respective General Ledger account!"]]}, {"cat": "c8", "h": "Internal control และ Cash", "head": ["หัวข้อ", "สรุป"], "rows": [["Separation of duties", "แยกผู้ถือเงินกับผู้บันทึก"], ["Voucher system", "อนุมัติก่อนจ่าย"], ["Petty cash", "ตั้งกองทุน เติมคืนตามใบสำคัญ"], ["Cash equivalents", "≤ 3 เดือน"]]}, {"cat": "c8", "h": "Bank reconciliation", "head": ["หัวข้อ", "สรุป"], "rows": [["Bank side", "+ Deposits in transit · − Outstanding checks"], ["Book side", "+ ดอกเบี้ย/เก็บให้ · − ค่าธรรมเนียม, NSF"], ["Journal entry", "ลงเฉพาะ Book side"]]}, {"cat": "c8", "h": "The Fraud Triangle & Principles of Internal Control (สามเหลี่ยมการทุจริตและการควบคุมภายใน)", "head": ["Topic", "Summary"], "rows": [["The Fraud Triangle (สามเหลี่ยมการทุจริต)", "• **Opportunity (โอกาส):** Weak internal controls allow fraud to occur (most controllable by the company).\n• **Financial Pressure (แรงกดดันทางการเงิน):** Personal debt, greed, or unrealistic profit targets.\n• **Rationalization (การหาเหตุผลเข้าข้างตนเอง):** Justifying unethical behavior (e.g., \"I'm underpaid,\" \"I'll pay it back later\")."], ["Six Principles of Internal Control Activities (หลักการควบคุมภายใน 6 ข้อ)", "• **Establishment of Responsibility (การกำหนดหน้าที่ความรับผิดชอบ):** Assign specific tasks to specific individuals (e.g., one cashier per cash register).\n• **Segregation of Duties (การแบ่งแยกหน้าที่):**\n  – Separate **record-keeping (accounting)** from **physical custody of assets**. (แยกคนทำบัญชีออกจากคนถือเงิน/สินทรัพย์)\n  – Separate authorization, custody, and accounting for related activities (purchasing, receiving, paying).\n• **Documentation Procedures (การใช้เอกสารหลักฐาน):** Use **pre-numbered documents** (checks, invoices) and account for all numbers.\n• **Physical Controls (การควบคุมทางกายภาพ):** Safes, locked warehouses, passwords, surveillance cameras, time clocks.\n• **Independent Internal Verification (การตรวจสอบภายในอย่างอิสระ):** Reconcile records periodically by someone independent of the employee who maintains them (e.g., monthly bank reconciliation, surprise cash counts).\n• **Human Resource Controls (การควบคุมด้านทรัพยากรบุคคล):** Bond employees who handle cash (fidelity insurance), rotate duties, require mandatory vacations, conduct background checks."], ["Limitations of Internal Control", "• **Cost vs. Benefit:** Control cost should not exceed expected benefit.\n• **Human Element:** Fatigue, carelessness, and **Collusion (การสมรู้ร่วมคิดของพนักงานตั้งแต่ 2 คนขึ้นไป)** which can override segregation of duties."]]}, {"cat": "c8", "h": "Petty Cash Fund (เงินสดย่อย - ระบบ Imprest System)", "head": ["Topic", "Summary"], "rows": [["Establishing the Fund (ตั้งวงเงินสดย่อย)", "• Dr. Petty Cash / Cr. Cash"], ["Making Payments from the Fund (จ่ายเงินสดย่อย)", "• **NO journal entry** is made when cash is disbursed from the box! The custodian collects signed petty cash receipts (vouchers). At all times: Cash remaining in box + Total petty cash receipts = Petty Cash Fund balance."], ["Replenishing the Fund (เบิกชดเชยเงินสดย่อย)", "• Done when cash gets low and **always at the end of the accounting period** (so expenses are recorded in the proper period).\n• Dr. Various Expenses (Postage Expense, Delivery Expense, Supplies, etc.)\n• Cr. Cash (for the exact amount needed to restore cash in the box back to the fixed fund limit — **DO NOT** debit or credit Petty Cash here!)\n• **Cash Over and Short:** If Cash needed to replenish ≠ Total receipts, record the difference in **Cash Over and Short**:\n  – **Debit** Cash Over and Short = Cash shortage (reported as Miscellaneous Expense).\n  – **Credit** Cash Over and Short = Cash overage (reported as Other Revenue)."], ["Changing the Fund Size (เพิ่มหรือลดวงเงินสดย่อย)", "• Only time Petty Cash is debited (to increase) or credited (to decrease) after initial setup."]]}, {"cat": "c8", "h": "Bank Reconciliation (งบพิสูจน์ยอดเงินฝากธนาคาร)", "head": ["Topic", "Summary"], "rows": [["Note", "Reconciles the **Bank Statement Balance** and the **Company's Book Balance** to the **Adjusted (True) Cash Balance**:"], ["Bank side (bank statement)", "**Bank Balance per Bank Statement**\n**+ Deposits in Transit** (เงินฝากระหว่างทาง)\n**- Outstanding Checks** (เช็คค้างจ่าย)\n**± Bank Errors** (ข้อผิดพลาดที่ธนาคารทำผิด)\n**= Adjusted Cash Balance per Bank**"], ["Book side (company books)", "**Cash Balance per Books**\n**+ EFT Collections & Notes Collected by Bank** (เงินโอนเข้า / ธนาคารเก็บเงินตามตั๋วให้ + ดอกเบี้ยรับ)\n**- NSF Checks (Non-Sufficient Funds)** (เช็คคืน/เช็คเด้งจากลูกค้า)\n**- Bank Service Charges / Debit Memos** (ค่าธรรมเนียมธนาคาร)\n**± Book Errors** (ข้อผิดพลาดที่กิจการบันทึกบัญชีผิด)\n**= Adjusted Cash Balance per Books**"], ["Golden Rules for Bank Reconciliation Exams (กฎเหล็กสำหรับข้อสอบงบพิสูจน์ยอดเงินฝาก)", "• **Adjusted Bank Balance MUST EQUAL Adjusted Book Balance.**\n• **ONLY items on the BOOK side require Adjusting Journal Entries!** Never journalize Deposits in Transit, Outstanding Checks, or Bank Errors.\n• **Transposition Error Rule (ตัวเลขสลับหลัก):** If the difference between recorded amount and actual amount is evenly divisible by 9 (e.g., $54 vs $45, diff = $9), it is likely a transposition error.\n  – Example: Company wrote a check to pay a supplier for $45 (actual cash outflow = $45), but recorded it in the books as $54 (deducted $9 too much from Cash). To fix the Book balance: **Add $9** (Dr. Cash $9 / Cr. Accounts Payable $9)."]]}, {"cat": "c8", "h": "Reporting Cash & Cash Equivalents (การแสดงรายการเงินสดและรายการเทียบเท่าเงินสด)", "head": ["Topic", "Summary"], "rows": [["Cash", "Coins, currency, available funds on deposit at banks, petty cash, money orders, certified checks."], ["Cash Equivalents", "Short-term, highly liquid investments that are readily convertible to known amounts of cash and have original maturities of **3 months or less** when purchased (e.g., Treasury bills, money market funds)."], ["Restricted Cash", "Cash set aside for a special purpose (e.g., plant expansion, debt retirement) is reported **separately** as either a Current Asset or Noncurrent Asset depending on when it will be used—**NOT** combined with unrestricted Cash."], ["Postdated Checks & IOUs", "Reported as **Receivables**, NOT Cash."]]}, {"cat": "c9", "h": "ลูกหนี้และหนี้สูญ", "head": ["หัวข้อ", "สรุป"], "rows": [["Direct write-off", "Dr Bad Debts Exp / Cr A/R"], ["Allowance method", "ประมาณล่วงหน้า (matching)"], ["% of sales", "income statement approach"], ["% of receivables / aging", "balance sheet approach"], ["Write-off", "Dr Allowance / Cr A/R · net ไม่เปลี่ยน"]]}, {"cat": "c9", "h": "ตั๋วเงินรับ", "head": ["หัวข้อ", "สรุป"], "rows": [["Interest", "P × R × T (360 วัน)"], ["Honored", "Dr Cash / Cr Notes Rec + Interest Rev"], ["Dishonored", "Dr A/R / Cr Notes Rec + Interest Rev"], ["A/R turnover", "Net sales ÷ Avg net A/R"]]}, {"cat": "c9", "h": "Types of Receivables (ประเภทของลูกหนี้)", "head": ["Topic", "Summary"], "rows": [["Accounts Receivable (ลูกหนี้การค้า)", "Amounts customers owe on account from the sale of goods and services (informal credit, typically collected in 30–60 days, non-interest-bearing)."], ["Notes Receivable (ตั๋วเงินรับ)", "Written promise (formal credit instrument) for amounts to be received; requires payment of principal plus interest at a specified maturity date."], ["Other Receivables (ลูกหนี้อื่น)", "Non-trade receivables such as interest receivable, loans to company officers, advances to employees, and income taxes refundable."]]}, {"cat": "c9", "h": "Valuing Accounts Receivable & Uncollectible Accounts (การตีราคาและค่าเผื่อหนี้สงสัยจะสูญ)", "head": ["Topic", "Summary"], "rows": [["Cash (Net) Realizable Value of AR", "Cash Realizable Value = Accounts Receivable - Allowance for Doubtful Accounts"], ["Two Methods of Accounting for Uncollectible Accounts", "• **Direct Write-Off Method (วิธีตัดจำหน่ายโดยตรง):**\n  – Records bad debt expense only when a specific account is determined to be uncollectible: Dr. Bad Debt Expense / Cr. Accounts Receivable.\n  – **Flaw:** Violates the **Expense Recognition (Matching) Principle** and overstates AR on the balance sheet. **Not acceptable** under GAAP/IFRS unless bad debts are immaterial.\n• **Allowance Method (วิธีตั้งค่าเผื่อหนี้สงสัยจะสูญ — Required under GAAP & IFRS):**\n  – **Step 1: Recording Estimated Uncollectibles (ปรับปรุงสิ้นงวด):**\n  – Dr. Bad Debt Expense / Cr. Allowance for Doubtful Accounts (Contra-Asset, normal Credit balance)\n  – **Step 2: Writing Off an Uncollectible Account (ตัดหนี้สูญเมื่อทวงถามไม่ได้แน่นอน):**\n  – Dr. Allowance for Doubtful Accounts / Cr. Accounts Receivable\n  – **CRITICAL EXAM TRAP:** Writing off an account does **NOT** affect Bad Debt Expense, does **NOT** affect Net Income, and does **NOT** change the Cash Realizable Value of Accounts Receivable (because both AR and the Contra-Asset Allowance decrease by the exact same amount!).\n  – **Step 3: Recovery of a Previously Written-Off Account (ได้รับชำระหนี้คืนหลังจากตัดหนี้สูญไปแล้ว):**\n  – **Entry 1 (Reinstate AR):** Dr. Accounts Receivable / Cr. Allowance for Doubtful Accounts\n  – **Entry 2 (Record Cash Collection):** Dr. Cash / Cr. Accounts Receivable"], ["Estimating the Allowance — Percentage-of-Receivables / Aging Basis (วิธีคำนวณจากยอดลูกหนี้ / อายุหนี้)", "• Focuses on the **Balance Sheet** (desired ending balance in Allowance for Doubtful Accounts).\n• **Formula for Adjusting Entry Amount:**\nBad Debt Expense = Target Ending Allowance - Existing Credit Balance in Allowance\n(If Allowance currently has an **unadjusted Debit balance**, **ADD** it to the Target Ending Allowance!)"]]}, {"cat": "c9", "h": "Notes Receivable (ตั๋วเงินรับ)", "head": ["Topic", "Summary"], "rows": [["Determining Maturity Date (การนับวันครบกำหนด)", "• Stated in **months**: Matures on the same numerical day of the maturity month (e.g., 3-month note dated May 10 matures August 10).\n• Stated in **days**: Omit the date the note is issued, include the due date (use exact days in each month: Jan 31, Feb 28, Mar 31, Apr 30, May 31, Jun 30, Jul 31, Aug 31, Sep 30, Oct 31, Nov 30, Dec 31)."], ["Computing Interest (การคำนวณดอกเบี้ย)", "Interest = Face Value of Note × Annual Interest Rate × Time in Terms of One Year\n(Standard convention uses a 360-day year for days, e.g., 90 / 360, or (Months) / 12 for months.)"], ["Key Journal Entries for Notes Receivable", "• **Receipt of Note in Settlement of AR (รับตั๋วเงินเพื่อชำระหนี้การค้า):**\n  – Dr. Notes Receivable / Cr. Accounts Receivable\n• **Accruing Interest at Fiscal Year-End (ปรับปรุงดอกเบี้ยค้างรับ ณ วันสิ้นงวดบัญชี):**\n  – Dr. Interest Receivable / Cr. Interest Revenue\n• **Honoring a Note at Maturity (รับชำระเงินตามตั๋วเมื่อครบกำหนด):**\n  – Dr. Cash (Principal + Total Interest)\n  – Cr. Notes Receivable (Principal)\n  – Cr. Interest Receivable (any interest already accrued at prior year-end)\n  – Cr. Interest Revenue (interest earned in current period)\n• **Dishonoring a Note at Maturity (ตั๋วเงินขาดความเชื่อถือ / ผู้จ่ายปฏิเสธการจ่ายเงิน):**\n  – **If eventual collection is still expected:** Transfer Principal + Interest earned into Accounts Receivable:\n  – Dr. Accounts Receivable / Cr. Notes Receivable & Cr. Interest Revenue\n  – **If there is no hope of collection:** Write off the principal to the Allowance account:\n  – Dr. Allowance for Doubtful Accounts / Cr. Notes Receivable (no interest revenue is recorded)."]]}, {"cat": "c9", "h": "Disposing of Receivables & Financial Ratios (การจำหน่ายลูกหนี้และอัตราส่วนทางการเงิน)", "head": ["Topic", "Summary"], "rows": [["National Credit Card Sales (การขายผ่านบัตรเครดิต เช่น Visa/Mastercard)", "• Treated like a **cash sale** (retailer receives cash immediately less a credit card fee of 2%–4%):\n• Dr. Cash (Net proceeds) & Dr. Service Charge Expense (Fee) / Cr. Sales Revenue (Full sale price)"], ["Factoring Receivables (การขายลูกหนี้ให้บริษัทแฟคตอริง)", "• Selling Accounts Receivable to a finance company (factor) for immediate cash less a service charge/factoring fee:\n• Dr. Cash & Dr. Service Charge Expense (or Loss on Sale of Receivables) / Cr. Accounts Receivable"], ["Receivables Management Ratios", "Accounts Receivable Turnover = (Net Credit Sales) / Average Net Accounts Receivable\nAverage Collection Period (in days) = 365 / Accounts Receivable Turnover"]]}], "quiz": [["c1", "Which is the correct accounting equation?", ["Assets = Liabilities + Equity", "Assets = Equity − Liabilities", "Liabilities = Assets + Equity", "Equity = Assets + Liabilities"], 0, "Assets equal the sources of funding: liabilities plus owner's equity."], ["c1", "Which is NOT a component of the Fraud Triangle?", ["Opportunity", "Pressure", "Rationalization", "Materiality"], 3, "Materiality is part of Relevance, not the Fraud Triangle."], ["c1", "A customer pays 5,000 owed on account. What is the result?", ["Cash +5,000 · A/R −5,000", "Revenue +5,000", "Equity +5,000", "Liabilities −5,000"], 0, "One asset is exchanged for another; it is not new revenue."], ["c1", "How is ROA calculated?", ["Net income ÷ Avg total assets", "Net income ÷ Sales", "Assets ÷ Liabilities", "Equity ÷ Assets"], 0, "ROA measures return on average total assets."], ["c2", "Which account is increased by a credit?", ["Revenue", "Expenses", "Withdrawals", "Cash"], 0, "Revenue, liabilities and equity increase with credits."], ["c2", "How is a purchase of supplies on credit recorded?", ["Dr Supplies / Cr A/P", "Dr Supplies / Cr Cash", "Dr A/P / Cr Supplies", "Dr Expense / Cr Cash"], 0, "An asset increases and a liability increases."], ["c2", "A balanced trial balance means what?", ["Total debits = total credits, but errors may still exist", "There are definitely no errors", "The financial statements are correct", "Every ledger account is included"], 0, "Some errors, such as omitting an entire transaction, do not unbalance the trial balance."], ["c2", "Debt ratio is calculated from?", ["Liabilities ÷ Assets", "Assets ÷ Liabilities", "Equity ÷ Assets", "Liabilities ÷ Equity"], 0, "It measures the share of assets financed by debt."], ["c3", "Prepaid insurance of 2,400 covers 24 months. How much is expensed per month?", ["100", "200", "2,400", "24"], 0, "2,400 ÷ 24 = 100"], ["c3", "Equipment costs 26,000, residual value is 8,000 and useful life is 48 months. What is monthly straight-line depreciation?", ["375", "542", "750", "18,000"], 0, "(26,000 − 8,000) ÷ 48 = 375 · 542 = forgot to subtract residual value · 18,000 = not yet divided by the number of months"], ["c3", "An accrued revenue adjustment is recorded with?", ["Dr A/R / Cr Revenue", "Dr Cash / Cr Revenue", "Dr Revenue / Cr A/R", "Dr Unearned / Cr Revenue"], 0, "The service was performed but cash has not been received."], ["c3", "Accumulated depreciation is what type of account?", ["Contra asset", "Expense", "Liability", "Equity"], 0, "It is deducted from the asset on the statement of financial position."], ["c3", "A 6,000 loan at 6% per year has 1 month of interest unpaid. What is accrued interest?", ["30", "360", "300", "3"], 0, "6,000 × 6% × 1/12 = 30 · 360 = a full year of interest · 300 and 3 = misplaced decimal"], ["c4", "Which account is a temporary account?", ["Withdrawals", "Cash", "Capital", "Land"], 0, "Withdrawals is closed to Capital each period."], ["c4", "Revenues are 20,000 and expenses are 15,000. What is left in Income Summary?", ["Cr 5,000", "Dr 5,000", "Cr 35,000", "0"], 0, "Net income of 5,000 is a credit balance."], ["c4", "Which accounts appear on the post-closing trial balance?", ["Permanent accounts only", "Temporary accounts only", "All accounts", "Revenue accounts only"], 0, "After closing, temporary accounts have a zero balance."], ["c4", "Current ratio =", ["CA ÷ CL", "CL ÷ CA", "CA − CL", "Quick ÷ CL"], 0, "It measures short-term liquidity."], ["c5", "What does the term 2/10, n/30 mean?", ["Pay within 10 days for a 2% discount", "Pay within 2 days for a 10% discount", "Pay at day 30 for a 2% discount", "Get a 10% discount if paid within 2 days"], 0, "Without the discount, the full amount is due within 30 days."], ["c5", "Freight-in causes what?", ["Inventory cost increases", "It is a selling expense", "Sales decrease", "COGS decreases immediately"], 0, "It is a cost of bringing the goods in."], ["c5", "Under the perpetual system, what must also be recorded at each sale?", ["Dr COGS / Cr Inventory", "Dr Inventory / Cr COGS", "Dr Sales / Cr Cash", "Nothing more"], 0, "Cost of goods sold is recorded with every sale."], ["c5", "Gross profit =", ["Net sales − COGS", "Net sales − Expenses", "Sales + COGS", "COGS − Sales"], 0, "It is before operating expenses."], ["c5", "Which is excluded from the acid-test ratio?", ["Inventory", "Cash", "Short-term investments", "Current receivables"], 0, "Quick assets exclude inventory."], ["c6", "Purchase prices keep rising and the same number of units is sold. Which method gives the highest profit?", ["FIFO", "LIFO", "Weighted average", "All the same"], 0, "FIFO expenses the older, lower costs as COGS, so profit is highest · LIFO is the opposite (lowest profit) and IFRS does not allow it"], ["c6", "Beginning inventory is 10 units at 100 each. 10 more units are bought at 120 each, then 12 units are sold. What is COGS under FIFO?", ["1,240", "1,320", "1,200", "1,440"], 0, "FIFO expenses the oldest first: (10×100)+(2×120) = 1,240 · 1,320 = the average-cost result · 1,200 = all 12 units at 100 · 1,440 = all 12 units at 120"], ["c6", "Beginning inventory is 10 units at 100 each. 10 more units are bought at 120 each, then 12 units are sold. What is COGS under weighted average?", ["1,320", "1,240", "1,100", "1,200"], 0, "Total cost 2,200 ÷ 20 units = 110 per unit → 12 × 110 = 1,320 · 1,240 = the FIFO result · 1,100 = only 10 units counted"], ["c6", "Ending inventory is counted too high at period end. What is the effect for that period?", ["COGS understated, profit overstated", "COGS overstated, profit understated", "COGS understated, profit understated", "No effect on COGS or profit"], 0, "COGS = Beginning + Purchases − Ending. If Ending is too high, COGS is too low and profit is too high."], ["c6", "Under IFRS, which inventory costing method is not permitted?", ["LIFO", "FIFO", "Weighted average", "Specific identification"], 0, "IFRS prohibits LIFO."], ["c6", "How is inventory turnover calculated?", ["COGS ÷ Average inventory", "Sales ÷ Ending inventory", "Ending inventory ÷ COGS", "COGS ÷ Sales"], 0, "COGS ÷ average inventory, where average = (beginning + ending) ÷ 2 · the higher it is, the faster inventory sells"], ["c7", "A sales journal is used to record?", ["Credit sales", "Cash sales", "Credit purchases", "Collections from customers"], 0, "Cash sales go to the cash receipts journal."], ["c7", "The total of the subsidiary ledger must be:", ["Equal to the controlling account", "Greater than it", "Less than it", "Unrelated to it"], 0, "It is used to check accuracy."], ["c7", "Which transaction is recorded in the general journal?", ["Adjusting entries", "Credit sales", "Cash receipts", "Check payments"], 0, "Transactions outside the special journals."], ["c7", "What is sales tax payable?", ["A liability to be remitted", "Revenue", "Expense", "Asset"], 0, "It is collected on behalf of the government."], ["c8", "Which is a good cash control principle?", ["Separate the person who handles cash from the person who records it", "Have one employee receive cash, deposit it and record it", "Keep receipts at the store for several days, then deposit them together", "Pay every item in cash for speed"], 0, "Separation of duties reduces the chance of fraud · deposit receipts in the bank immediately and pay by check"], ["c8", "In a bank reconciliation, how are outstanding checks (checks the company issued that the bank has not yet paid) adjusted?", ["Deduct from the bank statement balance", "Add to the bank statement balance", "Deduct from the company's book balance", "Add to the company's book balance"], 0, "The company has already recorded the payment but the bank has not deducted it, so the bank balance is too high and must be reduced (no journal entry needed)"], ["c8", "How are deposits in transit (deposits the company made that the bank has not yet recorded) adjusted?", ["Add to the bank statement balance", "Deduct from the bank statement balance", "Add to the book balance and record a journal entry", "No adjustment, because the bank will record it on its own"], 0, "The company has recorded it and the bank has not, so the bank balance is too low and must be increased (no journal entry needed)"], ["c8", "A customer's check the company deposited is returned by the bank (NSF check). How is it adjusted?", ["Deduct from the book balance and record a journal entry", "Add to the book balance", "Deduct from the bank statement balance", "Add to the bank statement balance"], 0, "The bank has deducted it but the company did not know, so it is a book-side item: deduct it and record a journal entry"], ["c8", "A short-term investment qualifies as a cash equivalent only if it matures within how long of the investment date?", ["3 months", "1 year", "6 months", "5 years"], 0, "It must be highly liquid, easily convertible to cash, low risk, and mature within 3 months"], ["c9", "How is the Allowance for Doubtful Accounts recorded?", ["Dr Bad Debts Exp / Cr Allowance", "Dr Allowance / Cr A/R", "Dr A/R / Cr Allowance", "Dr Cash / Cr A/R"], 0, "Bad debts are estimated in advance."], ["c9", "Under the allowance method, a write-off makes net receivables:", ["Unchanged", "Decrease", "Increase", "Zero"], 0, "It reduces both A/R and the Allowance."], ["c9", "Receivables are 50,000 and 5% is expected to be uncollectible. The Allowance already has a 200 credit balance. How much Bad debts expense must be recorded?", ["2,300", "2,500", "2,700", "200"], 0, "Required balance 50,000 × 5% = 2,500 less the existing 200 → 2,300 · 2,500 = existing balance not deducted · 2,700 = existing balance added in the wrong direction"], ["c9", "A 1,000 note bears 12% annual interest and runs 90 days (360-day year). How much is the interest?", ["30", "120", "90", "12"], 0, "1,000 × 12% × 90/360 = 30 · 120 = a full year of interest"], ["c9", "A 100 sale is paid by credit card with a 4% fee. How much cash is received?", ["96", "100", "104", "4"], 0, "The 4 fee is an expense."], ["c6", "Purchase prices keep rising. Which statement about FIFO ending inventory is correct?", ["It consists of the cost of the most recently purchased lots", "It consists of the cost of the earliest purchased lots", "It uses the average cost of goods available for sale", "It uses the actual cost of the specific items left in stock"], 0, "FIFO assumes first in, first out, so what remains is the latest lots, while COGS uses the oldest costs (people often swap these)"], ["c6", "Beginning inventory 20 units @50 · bought 30 units @60 · bought 50 units @70 · sold 60 units after all purchases\nWhat is COGS under FIFO?", ["3,500", "4,100", "3,600", "2,800"], 0, "FIFO: (20×50)+(30×60)+(10×70) = 1,000+1,800+700 = 3,500\n4,100 = costing from the latest lot first (LIFO) · 3,600 = unweighted average of 50/60/70 · 2,800 = ending inventory, not COGS"], ["c6", "Beginning inventory 20 units @50 · bought 30 units @60 · bought 50 units @70 · sold 60 units after all purchases\nWhat is ending inventory under weighted average?", ["2,520", "2,800", "2,400", "3,780"], 0, "Total cost 6,300 ÷ 100 units = 63 per unit → 40 units left × 63 = 2,520\n2,800 = the FIFO result · 2,400 = used 60 (unweighted average) · 3,780 = COGS, not ending inventory"], ["c6", "Lot A 10 units @200 · Lot B 10 units @240 · 8 units sold, identified as 5 from B and 3 from A\nWhat is COGS under specific identification?", ["1,800", "1,600", "1,760", "1,920"], 0, "Specific ID uses the actual cost of the units sold: (5×240)+(3×200) = 1,200+600 = 1,800\n1,600 = FIFO (8×200) · 1,760 = average of 220 · 1,920 = all 8 units at 240"], ["c6", "At the end of year 1, ending inventory is overstated by 5,000 and never corrected. What happens to net income?", ["Year 1 overstated by 5,000 · Year 2 understated by 5,000", "Year 1 understated by 5,000 · Year 2 overstated by 5,000", "Overstated in both years, 5,000 each", "Year 1 overstated by 5,000 · Year 2 not affected"], 0, "Year 1: COGS is too low → income overstated by 5,000. Year 2: beginning inventory is too high → COGS too high → income understated by 5,000 (the error cancels out over 2 years)"], ["c6", "Goods cost 80,000, are expected to sell for 95,000 and need 20,000 of selling costs. The company applies lower of cost and NRV. How should it record this?", ["Dr. Cost of goods sold 5,000 / Cr. Merchandise inventory 5,000", "Dr. Merchandise inventory 5,000 / Cr. Cost of goods sold 5,000", "No entry, because the 95,000 selling price exceeds the 80,000 cost", "Dr. Cost of goods sold 20,000 / Cr. Merchandise inventory 20,000"], 0, "NRV = 95,000 − 20,000 = 75,000, below cost of 80,000, so write down by 5,000 with Dr. COGS / Cr. Inventory\nOption 3 forgets selling costs · option 4 writes down by the whole selling cost"], ["c6", "A company used FIFO and wants to switch to weighted average. Under the consistency principle, which is correct?", ["It may switch if reports improve, but must disclose the type, reason and effect on profit in the notes", "It can never switch and must use FIFO for its whole life", "It may switch freely every period without disclosure, as it is management's judgment", "It must switch every period to match the latest market price"], 0, "Consistency means using the same method every period for comparability, but a change is allowed when reports improve and all 3 items are disclosed"], ["c8", "Which item makes the bank balance differ from the company's Cash balance but needs no journal entry in the company's books?", ["Outstanding checks", "A customer's NSF check", "Bank service charges", "Interest the bank added"], 0, "Outstanding checks are already recorded by the company; the bank has not paid them yet → adjust the bank side only, no entry\nThe other 3 are recorded by the bank but not yet known to the company → adjust the book side with a journal entry"], ["c8", "The bank added 100 of interest income to the deposit account, but the company has not recorded it. How should it be adjusted?", ["Add to the book side and record Dr. Cash / Cr. Interest revenue", "Add to the bank side, since the bank pays the interest", "Deduct from the book side, since it is not yet recorded", "Add to the bank side and make no entry in the company's books"], 0, "The bank has already recorded the interest, so the bank balance is already higher; do not adjust the bank side. The company adds it to the book side and records the entry"], ["c8", "Bank statement balance 18,400 · Deposits in transit 3,000 · Outstanding checks 2,200 · The bank deducted a 40 service charge that the company has not recorded\nWhat is the adjusted cash balance on the bank side?", ["19,200", "19,160", "17,600", "23,600"], 0, "18,400 + 3,000 − 2,200 = 19,200 · the service charge is a book-side item and is not applied to the bank side\n19,160 = deducted 40 on the wrong side · 17,600 and 23,600 = signs of deposits in transit and outstanding checks swapped"], ["c8", "Company book cash balance 19,640 · bank collected interest 100 · NSF check 500 · bank service charge 40 not yet recorded\nWhat is the adjusted cash balance on the book side?", ["19,200", "20,200", "19,240", "19,000"], 0, "19,640 + 100 − 500 − 40 = 19,200\n20,200 = added NSF instead of deducting · 19,240 = forgot the service charge · 19,000 = deducted interest instead of adding"], ["c8", "The bank returns a customer's 500 check (NSF) and deducts a 40 fee. How should the company record it?", ["Dr. Accounts receivable 500 + Dr. Bank service charges 40 / Cr. Cash 540", "Dr. Cash 540 / Cr. Accounts receivable 500 + Cr. Bank service charges 40", "Dr. Sales revenue 500 + Dr. Bank service charges 40 / Cr. Cash 540", "No entry, since the bank already recorded it on the statement"], 0, "NSF means the customer still owes, so Accounts receivable is reinstated; the fee is an expense; Cash falls by 540 in total\nOption 3 is wrong because the sale still happened · option 4 is wrong because the company's books must match reality"], ["c8", "The company issued a 450 check for electricity but recorded it as 540. The bank paid the actual 450. How should this be adjusted?", ["Add 90 on the book side and record Dr. Cash 90 / Cr. Utilities expense 90", "Add 90 on the bank side, since the bank paid less", "Deduct 90 on the book side and record Dr. Utilities expense 90 / Cr. Cash 90", "Add 90 on the book side in the reconciliation only, with no journal entry"], 0, "The error is in the company's books (payment overstated by 90), so cash is understated by 90: add it back on the book side and reduce Utilities expense\nOption 4 is wrong because book-side items need a journal entry"], ["c8", "Why must the adjusted bank balance and the adjusted book balance be equal?", ["Because both are the correct cash balance at the same date; if they differ, an item or error is still unidentified", "Because the bank must adjust its balance to match the company's", "Because deposits in transit and outstanding checks always cancel out exactly", "Because both sides start from the same balance"], 0, "A reconciliation explains every difference until one true balance remains; a mismatch means differences are still missing"], ["c6", "Under the periodic system, which is the correct formula for cost of goods sold?", ["Beginning inventory + Cost of goods purchased − Ending inventory", "Beginning inventory + Cost of goods purchased + Ending inventory", "Cost of goods purchased − Ending inventory", "Ending inventory − Beginning inventory + Cost of goods purchased"], 0, "COGS = goods available for sale (beginning + net purchases) − ending inventory · option 2 adds ending inventory in the wrong direction · option 3 forgets beginning inventory · option 4 swaps the beginning and ending signs"], ["c6", "Why does the periodic system require a count of ending inventory?", ["Because COGS is not recorded at each sale, so ending inventory is used to work back to COGS", "To find the selling price of each item", "Because the system already records COGS at each sale, so the count is only a double-check", "To find selling and administrative expenses for the period"], 0, "Periodic has no inventory or COGS updated at the time of sale, so count ending inventory and find COGS from available for sale − ending inventory (only perpetual records COGS at each sale)"], ["c6", "Beginning inventory 30,000 · purchases 120,000 · purchase returns 4,000 · purchase discounts 2,000 · freight-in 6,000 · ending inventory 35,000 (periodic system). What is COGS?", ["115,000", "109,000", "121,000", "185,000"], 0, "Cost of goods purchased = 120,000−4,000−2,000+6,000 = 120,000 → available 150,000 → COGS = 150,000−35,000 = 115,000\n109,000 = forgot freight-in · 121,000 = ignored returns and discounts · 185,000 = added ending inventory instead of subtracting"], ["c6", "Periodic system: beginning inventory 10 units @100, bought 10 units @120, ending count 8 units. What is COGS under FIFO?", ["1,240", "960", "1,320", "1,440"], 0, "FIFO ending = latest lot 8×120 = 960 · available 2,200 → COGS = 2,200−960 = 1,240 · 960 = ending inventory, not COGS · 1,320 = weighted-average result · 1,440 = all 12 units at 120"], ["c6", "Perpetual system, FIFO. Beginning inventory is 40 units at 75 each. The company sells 30 units, then buys 20 units at 90 each, then sells 15 units. What is the inventory balance after the second sale?", ["1,350", "1,125", "1,275", "1,200"], 0, "15 units remain, all from the latest lot: 15×90 = 1,350\n1,125 = assumed the oldest lot remains · 1,275 = used a weighted average of the goods on hand · 1,200 = gave the cost of the second sale instead of the inventory balance"], ["c6", "Which statement describes FIFO?", ["The oldest costs are assigned to cost of goods sold first", "The newest costs are assigned to cost of goods sold first", "Every unit sold gets the same average cost", "Each sold unit is matched to its own actual cost"], 0, "FIFO = first in, first out: oldest costs go to COGS, latest costs stay in ending inventory\n\"The newest costs are assigned to cost of goods sold first\" = described LIFO · \"Every unit sold gets the same average cost\" = described weighted average · \"Each sold unit is matched to its own actual cost\" = described specific identification"], ["c6", "A fire destroyed the inventory. Net sales were 350,000 at a normal gross profit rate of 25% of sales. Beginning inventory was 90,000 and net purchases 300,000. Using the gross profit method, what is the estimated inventory lost?", ["127,500", "302,500", "40,000", "262,500"], 0, "Estimated COGS = 350,000 × (1 − 25%) = 262,500; goods available 390,000 − 262,500 = 127,500\n302,500 = used the gross profit as cost of goods sold · 40,000 = ignored the gross margin and treated sales as cost · 262,500 = gave estimated cost of goods sold instead of ending inventory"], ["c6", "Periodic system: net sales 309,000; beginning inventory 50,000; purchases 250,000; purchase returns 4,000; purchase discounts 1,000; freight-in 9,000; ending inventory 45,000. What is gross profit?", ["50,000", "59,000", "55,000", "264,000"], 0, "COGS = 50,000 + 254,000 − 45,000 = 259,000; gross profit = 309,000 − 259,000 = 50,000\n59,000 = left freight-in out of COGS · 55,000 = used cost of goods purchased as COGS · 264,000 = used ending inventory as COGS"], ["c6", "Inventory costs 110,000. Its estimated selling price is 130,000, with estimated completion costs of 7,000 and selling costs of 7,000. At what amount is it reported under lower of cost and NRV?", ["110,000", "116,000", "130,000", "6,000"], 0, "NRV = 116,000 is above cost, so inventory stays at cost 110,000; inventory is never written up\n116,000 = wrote the inventory up to NRV · 130,000 = used the selling price · 6,000 = reported the NRV excess as the carrying amount"], ["c6", "A company buys three lots during the period: 10 units at 40, 10 units at 50 and 40 units at 60. 30 units remain unsold at period end. What is ending inventory under weighted average?", ["1,650", "1,500", "1,800", "1,200"], 0, "Average cost 3,300 ÷ 60 = 55; 30 × 55 = 1,650\n1,500 = used the simple average of unit costs · 1,800 = used the latest cost · 1,200 = used the oldest cost"], ["c6", "During the count, staff find goods on the shelf that belong to a consignor. What should the company do?", ["Exclude them from its inventory count", "Include them at selling price", "Include them at cost, since they are in its warehouse", "Include them only if the company insures them"], 0, "Only goods the company owns belong in its inventory\n\"Include them at selling price\" = valued at selling price and ignored ownership · \"Include them at cost, since they are in its warehouse\" = equated location with ownership · \"Include them only if the company insures them\" = tied ownership to insurance"], ["c6", "Ending inventory is understated at the end of the year. What is the effect on that year’s net income?", ["Net income is understated", "Net income is overstated", "No effect on net income", "The effect cannot be determined"], 0, "Ending inventory too low makes COGS too high, so profit too low\n\"Net income is overstated\" = reversed the direction · \"No effect on net income\" = thought an inventory error stays in the balance sheet only · \"The effect cannot be determined\" = assumed there is no formula link"], ["c6", "Periodic system: beginning inventory 30,000; purchases 210,000; purchase returns 2,000; purchase discounts 1,000; freight-in 8,000; ending inventory 70,000. What is the cost of goods available for sale?", ["245,000", "240,000", "175,000", "215,000"], 0, "30,000 + (210,000 − 2,000 − 1,000 + 8,000) = 245,000\n240,000 = used gross purchases, ignoring returns, discounts and freight-in · 175,000 = subtracted ending inventory (that is cost of goods sold) · 215,000 = left out beginning inventory"], ["c6", "Beginning inventory is 35 units at 80 each. The company buys 35 more units at 100 each, then sells 40 units at 135 each (periodic system). What is gross profit under FIFO?", ["2,100", "1,500", "1,800", "2,400"], 0, "Sales 5,400 − FIFO COGS 3,300 = 2,100 (COGS = 35×80 + 5×100)\n1,500 = used LIFO cost of goods sold · 1,800 = used weighted-average cost of goods sold · 2,400 = subtracted ending inventory instead of cost of goods sold"], ["c6", "What do days' sales in inventory show?", ["How many days of sales the ending inventory can cover", "How many days a customer takes to pay", "How many days suppliers allow before payment", "How many days the physical count takes"], 0, "Days' sales in inventory = (ending inventory ÷ COGS) × 365\n\"How many days a customer takes to pay\" = confused it with receivables · \"How many days suppliers allow before payment\" = confused it with payables · \"How many days the physical count takes\" = confused it with counting time"], ["c6", "A company buys three lots during the period: 20 units at 70, 20 units at 75 and 35 units at 80. What is the weighted-average cost per unit?", ["76", "75", "80", "70"], 0, "Total cost 5,700 ÷ 75 units = 76\n75 = simple average of the unit costs, ignoring quantities · 80 = used only the latest cost · 70 = used only the oldest cost"], ["c6", "When is the gross profit method used to estimate inventory?", ["For interim reports or when records are destroyed, for example by fire", "To replace the annual physical count every year", "To value inventory at selling price in the financial statements", "To measure the cost of goods purchased"], 0, "The method estimates ending inventory when a count is impractical\n\"To replace the annual physical count every year\" = treated an estimate as a permanent substitute · \"To value inventory at selling price in the financial statements\" = confused cost-based estimates with selling-price valuation · \"To measure the cost of goods purchased\" = confused purchases with ending inventory"], ["c6", "Beginning inventory 30,000, ending inventory 50,000, cost of goods sold 200,000. What is the inventory turnover (times)?", ["5.0", "4.0", "6.7", "0.4"], 0, "Average inventory = (30,000 + 50,000) ÷ 2 = 40,000; 200,000 ÷ 40,000 = 5\n4.0 = used ending inventory instead of the average · 6.7 = used beginning inventory instead of the average · 0.4 = divided average inventory by COGS (inverted)"], ["c6", "How is net realizable value (NRV) calculated?", ["Estimated selling price − costs to complete and sell", "Estimated selling price − original cost", "Original cost + costs to complete and sell", "Estimated selling price + estimated selling costs"], 0, "NRV is the net amount expected from sale after remaining costs\n\"Estimated selling price − original cost\" = used cost instead of the selling costs · \"Original cost + costs to complete and sell\" = added costs to cost · \"Estimated selling price + estimated selling costs\" = added selling costs instead of subtracting"], ["c6", "Lot A: 10 units at 290; Lot B: 30 units at 250; Lot C: 30 units at 220. The company sells 35 units, identified as 10 from A, 20 from B and 5 from C. What is ending inventory under specific identification?", ["8,000", "7,850", "8,500", "10,150"], 0, "Units left: A 0, B 10, C 25 at their own costs = 8,000 (goods available 17,000 − COGS 9,000)\n7,850 = used the FIFO ending inventory · 8,500 = used the weighted-average ending inventory · 10,150 = costed every remaining unit at the highest lot cost"], ["c6", "Ending inventory 28,000, beginning inventory 12,000, cost of goods sold 200,000 (365-day year). What are days' sales in inventory (to the nearest day)?", ["51 days", "37 days", "22 days", "50 days"], 0, "(28,000 ÷ 200,000) × 365 = 51 days\n37 days = used average inventory instead of ending inventory · 22 days = used beginning inventory · 50 days = used a 360-day year"], ["c6", "At the end of Year 1, ending inventory was overstated by 8,000 and was never corrected. What is the effect on combined net income for Years 1 and 2?", ["No effect", "Overstated by 8,000", "Understated by 8,000", "Overstated by 16,000"], 0, "The Year 1 error reverses in Year 2, so cumulative profit and retained earnings are correct by the end of Year 2\nOverstated by 8,000 = carried the Year 1 error forward without it reversing · Understated by 8,000 = reversed the direction of the effect · Overstated by 16,000 = double counted the error"], ["c6", "Perpetual system, FIFO. Beginning inventory is 55 units at 35 each. The company sells 15 units, then buys 40 units at 55 each, then sells 45 units. What is the cost of the second sale?", ["1,675", "2,475", "2,025", "1,575"], 0, "40 older units at 35 are used first, then 5 units at 55: 1,675\n2,475 = costed the whole sale at the latest purchase cost · 2,025 = used a weighted average of the goods on hand · 1,575 = costed the whole sale at the beginning cost"], ["c6", "Lot A: 10 units at 270; Lot B: 10 units at 250; Lot C: 30 units at 140. The company sells 40 units, identified as 10 from A, 5 from B and 25 from C. What is cost of goods sold under specific identification?", ["7,450", "8,000", "7,520", "10,800"], 0, "Actual cost of units sold: (10×270) + (5×250) + (25×140) = 7,450\n8,000 = costed the units sold oldest lot first (FIFO) · 7,520 = used the weighted-average cost · 10,800 = costed every unit at the highest lot cost"], ["c6", "Which method most smooths the effect of price changes on cost of goods sold?", ["Weighted average", "FIFO", "Specific identification", "LIFO"], 0, "Weighted average blends all costs available, so COGS moves less than under the extreme methods\n\"FIFO\" = thought FIFO averages costs · \"Specific identification\" = thought actual costs smooth price changes · \"LIFO\" = thought LIFO averages costs"], ["c6", "Lot A: 15 units at 250; Lot B: 15 units at 270; Lot C: 20 units at 230. The company sells 40 units, identified as 5 from A, 15 from B and 20 from C. What is ending inventory under specific identification?", ["2,500", "2,300", "2,480", "2,700"], 0, "Units left: A 10, B 0, C 0 at their own costs = 2,500 (goods available 12,400 − COGS 9,900)\n2,300 = used the FIFO ending inventory · 2,480 = used the weighted-average ending inventory · 2,700 = costed every remaining unit at the highest lot cost"], ["c6", "A manufacturer places goods in a retailer's store on consignment. Which company includes the unsold goods in its inventory?", ["The manufacturer (the consignor), who still owns them", "The retailer (the consignee), because the goods are in its store", "Both companies, one half each", "Neither, because consigned goods are never inventory"], 0, "The consignor keeps ownership until the consignee sells the goods\n\"The retailer (the consignee), because the goods are in its store\" = equated physical location with ownership · \"Both companies, one half each\" = invented a split of ownership · \"Neither, because consigned goods are never inventory\" = believed consigned goods are excluded by everyone"], ["c6", "Goods ordered FOB destination are in transit to the buyer at year end. Which statement is correct?", ["They remain the seller's inventory until they reach the buyer", "They belong to the buyer from the moment of shipment", "They are excluded by both companies", "They belong to whichever party pays the freight"], 0, "Under FOB destination, ownership passes on arrival\n\"They belong to the buyer from the moment of shipment\" = mixed up FOB destination with FOB shipping point · \"They are excluded by both companies\" = believed goods in transit are never counted · \"They belong to whichever party pays the freight\" = tied ownership to who pays freight"], ["c6", "Beginning inventory is 56,000 and ending inventory is 64,000. What is average inventory?", ["60,000", "64,000", "120,000", "8,000"], 0, "(56,000 + 64,000) ÷ 2 = 60,000\n64,000 = used ending inventory only · 120,000 = added without dividing by 2 · 8,000 = took the change in inventory"], ["c6", "For which inventory is specific identification most appropriate?", ["Unique, high-value items such as custom-built yachts", "Large quantities of identical bolts", "Bulk grain mixed in one silo", "Low-cost interchangeable office supplies"], 0, "Specific ID needs each unit to be identifiable, which suits unique, costly items\n\"Large quantities of identical bolts\" = used it for interchangeable items that cannot be tracked individually · \"Bulk grain mixed in one silo\" = used it where units cannot be told apart · \"Low-cost interchangeable office supplies\" = used it where tracking costs exceed the benefit"], ["c6", "A company buys three lots during the period: 40 units at 60, 10 units at 70 and 10 units at 80. What is the weighted-average cost per unit?", ["65", "70", "80", "60"], 0, "Total cost 3,900 ÷ 60 units = 65\n70 = simple average of the unit costs, ignoring quantities · 80 = used only the latest cost · 60 = used only the oldest cost"], ["c6", "Perpetual system, FIFO. Beginning inventory is 20 units at 20 each. The company sells 10 units, then buys 20 units at 35 each, then sells 25 units. What is the inventory balance after the second sale?", ["175", "100", "150", "725"], 0, "5 units remain, all from the latest lot: 5×35 = 175\n100 = assumed the oldest lot remains · 150 = used a weighted average of the goods on hand · 725 = gave the cost of the second sale instead of the inventory balance"], ["c6", "A fire destroyed the inventory. Net sales were 350,000 at a normal gross profit rate of 40% of sales. Beginning inventory was 80,000 and net purchases 390,000. Using the gross profit method, what is the estimated inventory lost?", ["260,000", "330,000", "120,000", "210,000"], 0, "Estimated COGS = 350,000 × (1 − 40%) = 210,000; goods available 470,000 − 210,000 = 260,000\n330,000 = used the gross profit as cost of goods sold · 120,000 = ignored the gross margin and treated sales as cost · 210,000 = gave estimated cost of goods sold instead of ending inventory"], ["c6", "At the end of Year 1, ending inventory was understated by 7,000 and was never corrected. What is the effect on Year 1 ending total assets?", ["Understated by 7,000", "Overstated by 7,000", "No effect", "Understated by 14,000"], 0, "Year 1: COGS = Beginning + Purchases − Ending, so an ending-inventory error moves COGS the opposite way and profit the same way; the same amount reverses in Year 2 through beginning inventory\nOverstated by 7,000 = reversed the direction of the effect · No effect = assumed the error has no effect · Understated by 14,000 = double counted the error"], ["c6", "Beginning inventory is 25 units at 20 each. The company buys 25 more units at 30 each and sells 35 units. What is ending inventory under FIFO?", ["450", "375", "300", "800"], 0, "15 units remain, all from the latest lot: 15×30 = 450\n375 = used the weighted-average cost · 300 = assumed the oldest lot is what remains · 800 = gave cost of goods sold instead of ending inventory"], ["c6", "Periodic system: beginning inventory 60,000; purchases 190,000; purchase returns 4,000; purchase discounts 5,000; freight-in 4,000; ending inventory 35,000. What is cost of goods sold?", ["210,000", "206,000", "219,000", "280,000"], 0, "Cost of goods purchased = 190,000 − 4,000 − 5,000 + 4,000 = 185,000; COGS = 60,000 + 185,000 − 35,000 = 210,000\n206,000 = left out freight-in · 219,000 = ignored purchase returns and discounts · 280,000 = added ending inventory instead of subtracting it"], ["c6", "Purchases were 160,000, purchase returns 7,000, purchase discounts 2,000 and freight-in 7,000. What is the cost of goods purchased?", ["158,000", "151,000", "144,000", "167,000"], 0, "160,000 − 7,000 − 2,000 + 7,000 = 158,000\n151,000 = left out freight-in · 144,000 = subtracted freight-in · 167,000 = ignored returns and discounts"], ["c6", "Periodic system: beginning inventory 50,000; purchases 280,000; purchase returns 4,000; purchase discounts 3,000; freight-in 5,000; cost of goods sold 150,000. What is ending inventory?", ["178,000", "478,000", "128,000", "180,000"], 0, "Available 328,000 − COGS 150,000 = 178,000\n478,000 = added cost of goods sold instead of subtracting it · 128,000 = left out beginning inventory · 180,000 = ignored returns, discounts and freight-in"], ["c6", "At the end of Year 1, ending inventory was understated by 3,000 and was never corrected. What is the effect on Year 2 net income?", ["Overstated by 3,000", "Understated by 3,000", "No effect", "Overstated by 6,000"], 0, "Year 1: COGS = Beginning + Purchases − Ending, so an ending-inventory error moves COGS the opposite way and profit the same way; the same amount reverses in Year 2 through beginning inventory\nUnderstated by 3,000 = reversed the direction of the effect · No effect = assumed the error has no effect · Overstated by 6,000 = double counted the error"], ["c6", "At the end of Year 1, ending inventory was understated by 9,000 and was never corrected. What is the effect on Year 2 cost of goods sold?", ["Understated by 9,000", "Overstated by 9,000", "No effect", "Understated by 18,000"], 0, "Year 1: COGS = Beginning + Purchases − Ending, so an ending-inventory error moves COGS the opposite way and profit the same way; the same amount reverses in Year 2 through beginning inventory\nOverstated by 9,000 = reversed the direction of the effect · No effect = assumed the error has no effect · Understated by 18,000 = double counted the error"], ["c6", "Inventory costs 100,000. Its estimated selling price is 119,000, with estimated completion costs of 7,000 and selling costs of 4,000. At what amount is it reported under lower of cost and NRV?", ["100,000", "108,000", "119,000", "8,000"], 0, "NRV = 108,000 is above cost, so inventory stays at cost 100,000; inventory is never written up\n108,000 = wrote the inventory up to NRV · 119,000 = used the selling price · 8,000 = reported the NRV excess as the carrying amount"], ["c6", "A company buys three lots during the period: 35 units at 50, 20 units at 60 and 20 units at 70. 15 units remain unsold at period end. What is ending inventory under weighted average?", ["870", "900", "1,050", "750"], 0, "Average cost 4,350 ÷ 75 = 58; 15 × 58 = 870\n900 = used the simple average of unit costs · 1,050 = used the latest cost · 750 = used the oldest cost"], ["c6", "At the end of Year 1, ending inventory was overstated by 2,000 and was never corrected. What is the effect on Year 1 net income?", ["Overstated by 2,000", "Understated by 2,000", "No effect", "Overstated by 4,000"], 0, "Year 1: COGS = Beginning + Purchases − Ending, so an ending-inventory error moves COGS the opposite way and profit the same way; the same amount reverses in Year 2 through beginning inventory\nUnderstated by 2,000 = reversed the direction of the effect · No effect = assumed the error has no effect · Overstated by 4,000 = double counted the error"], ["c6", "Must the cost flow assumption match the physical flow of the goods?", ["No; it is an accounting choice and need not match physical movement", "Yes; FIFO must be used for perishable goods only", "Yes; the physical flow always dictates the method", "No, but only if the auditor approves each sale"], 0, "Cost flow assumptions are accounting conventions, not records of physical movement\n\"Yes; FIFO must be used for perishable goods only\" = invented a perishable-goods rule · \"Yes; the physical flow always dictates the method\" = assumed costing follows the warehouse · \"No, but only if the auditor approves each sale\" = invented per-sale approval"], ["c6", "Beginning inventory is 10 units at 30 each. The company buys 15 more units at 50 each, then sells 20 units (periodic system, all purchases made before the sales). What is cost of goods sold under FIFO?", ["800", "900", "840", "250"], 0, "FIFO uses the oldest costs first: (10×30) + (10×50) = 800\n900 = costed the latest lots first (LIFO) · 840 = used the weighted-average cost · 250 = gave ending inventory instead of cost of goods sold"], ["c6", "When purchase prices rise, which of FIFO and weighted average reports the lower net income?", ["Weighted average", "FIFO", "They report the same net income", "Neither; price changes do not affect income"], 0, "FIFO puts older, lower costs into COGS, so weighted average has higher COGS and lower income\n\"FIFO\" = mixed up the direction of the price effect · \"They report the same net income\" = ignored the cost flow assumption · \"Neither; price changes do not affect income\" = believed cost flow does not affect income"], ["c6", "Which is a good control over a physical inventory count?", ["Counters are independent of those who look after the goods, and a second count is made", "Count sheets are not numbered so they can be revised freely", "The warehouse keeper counts his own goods to save time", "Counts are made once with no review by management"], 0, "Independence, numbered sheets, recounts and management review all reduce counting errors and theft\n\"Count sheets are not numbered so they can be revised freely\" = removed accountability for count sheets · \"The warehouse keeper counts his own goods to save time\" = removed independence · \"Counts are made once with no review by management\" = removed verification"], ["c6", "Periodic system: beginning inventory 20,000; purchases 160,000; purchase returns 5,000; purchase discounts 5,000; freight-in 8,000; ending inventory 25,000. What is cost of goods sold?", ["153,000", "145,000", "163,000", "203,000"], 0, "Cost of goods purchased = 160,000 − 5,000 − 5,000 + 8,000 = 158,000; COGS = 20,000 + 158,000 − 25,000 = 153,000\n145,000 = left out freight-in · 163,000 = ignored purchase returns and discounts · 203,000 = added ending inventory instead of subtracting it"], ["c6", "Lot A: 20 units at 280; Lot B: 30 units at 270; Lot C: 25 units at 140. The company sells 60 units, identified as 10 from A, 25 from B and 25 from C. What is cost of goods sold under specific identification?", ["13,050", "15,100", "13,760", "16,800"], 0, "Actual cost of units sold: (10×280) + (25×270) + (25×140) = 13,050\n15,100 = costed the units sold oldest lot first (FIFO) · 13,760 = used the weighted-average cost · 16,800 = costed every unit at the highest lot cost"], ["c6", "Periodic system: beginning inventory 45,000; purchases 270,000; purchase returns 8,000; purchase discounts 3,000; freight-in 3,000; cost of goods sold 240,000. What is ending inventory?", ["67,000", "547,000", "22,000", "75,000"], 0, "Available 307,000 − COGS 240,000 = 67,000\n547,000 = added cost of goods sold instead of subtracting it · 22,000 = left out beginning inventory · 75,000 = ignored returns, discounts and freight-in"], ["c6", "Beginning inventory is 15 units at 65 each. The company buys 15 more units at 75 each, then sells 20 units (periodic system, all purchases made before the sales). What is cost of goods sold under FIFO?", ["1,350", "1,450", "1,400", "750"], 0, "FIFO uses the oldest costs first: (15×65) + (5×75) = 1,350\n1,450 = costed the latest lots first (LIFO) · 1,400 = used the weighted-average cost · 750 = gave ending inventory instead of cost of goods sold"], ["c6", "When purchase prices fall, which of FIFO and weighted average reports the lower net income?", ["FIFO", "Weighted average", "They report the same net income", "Neither; price changes do not affect income"], 0, "With falling prices FIFO sends the older, higher costs to COGS, so COGS is higher and income lower\n\"Weighted average\" = mixed up the direction of the price effect · \"They report the same net income\" = ignored the cost flow assumption · \"Neither; price changes do not affect income\" = believed cost flow does not affect income"], ["c6", "During the period under the periodic system, what does the Merchandise inventory account show?", ["The beginning balance, until adjusted at period end", "The current stock after every sale", "Purchases only", "Zero"], 0, "The account is not updated during the period; it is adjusted when COGS is computed\n\"The current stock after every sale\" = described the perpetual system · \"Purchases only\" = confused inventory with the Purchases account · \"Zero\" = believed the account is emptied each period"], ["c6", "At the end of Year 1, ending inventory was overstated by 6,000 and was never corrected. What is the effect on Year 1 gross profit?", ["Overstated by 6,000", "Understated by 6,000", "No effect", "Overstated by 12,000"], 0, "Year 1: COGS = Beginning + Purchases − Ending, so an ending-inventory error moves COGS the opposite way and profit the same way; the same amount reverses in Year 2 through beginning inventory\nUnderstated by 6,000 = reversed the direction of the effect · No effect = assumed the error has no effect · Overstated by 12,000 = double counted the error"], ["c6", "A fire destroyed the inventory. Net sales were 350,000 at a normal gross profit rate of 40% of sales. Beginning inventory was 70,000 and net purchases 390,000. Using the gross profit method, what is the estimated inventory lost?", ["250,000", "320,000", "110,000", "210,000"], 0, "Estimated COGS = 350,000 × (1 − 40%) = 210,000; goods available 460,000 − 210,000 = 250,000\n320,000 = used the gross profit as cost of goods sold · 110,000 = ignored the gross margin and treated sales as cost · 210,000 = gave estimated cost of goods sold instead of ending inventory"], ["c6", "A higher inventory turnover generally indicates what?", ["Inventory is selling more quickly", "Inventory is selling more slowly", "Inventory is overstated", "Gross margin is higher"], 0, "Turnover = COGS ÷ average inventory; higher means faster sales\n\"Inventory is selling more slowly\" = read the ratio backwards · \"Inventory is overstated\" = confused turnover with valuation · \"Gross margin is higher\" = confused turnover with margin"], ["c6", "A company buys three lots during the period: 25 units at 65, 10 units at 70 and 15 units at 75. 25 units remain unsold at period end. What is ending inventory under weighted average?", ["1,725", "1,750", "1,875", "1,625"], 0, "Average cost 3,450 ÷ 50 = 69; 25 × 69 = 1,725\n1,750 = used the simple average of unit costs · 1,875 = used the latest cost · 1,625 = used the oldest cost"], ["c6", "Perpetual system, FIFO. Beginning inventory is 40 units at 20 each. The company sells 30 units, then buys 40 units at 30 each, then sells 20 units. What is the inventory balance after the second sale?", ["900", "600", "840", "500"], 0, "30 units remain, all from the latest lot: 30×30 = 900\n600 = assumed the oldest lot remains · 840 = used a weighted average of the goods on hand · 500 = gave the cost of the second sale instead of the inventory balance"], ["c6", "Beginning inventory 54,000, ending inventory 66,000, cost of goods sold 300,000. What is the inventory turnover (times)?", ["5.0", "4.5", "5.6", "0.4"], 0, "Average inventory = (54,000 + 66,000) ÷ 2 = 60,000; 300,000 ÷ 60,000 = 5\n4.5 = used ending inventory instead of the average · 5.6 = used beginning inventory instead of the average · 0.4 = divided average inventory by COGS (inverted)"], ["c6", "Ending inventory 56,000, beginning inventory 44,000, cost of goods sold 400,000 (365-day year). What are days' sales in inventory (to the nearest day)?", ["51 days", "46 days", "40 days", "50 days"], 0, "(56,000 ÷ 400,000) × 365 = 51 days\n46 days = used average inventory instead of ending inventory · 40 days = used beginning inventory · 50 days = used a 360-day year"], ["c6", "Beginning inventory is 40 units at 65 each. The company buys 40 more units at 75 each, then sells 50 units (periodic system, all purchases made before the sales). What is cost of goods sold under FIFO?", ["3,350", "3,650", "3,500", "2,250"], 0, "FIFO uses the oldest costs first: (40×65) + (10×75) = 3,350\n3,650 = costed the latest lots first (LIFO) · 3,500 = used the weighted-average cost · 2,250 = gave ending inventory instead of cost of goods sold"], ["c6", "Purchases were 120,000, purchase returns 5,000, purchase discounts 5,000 and freight-in 7,000. What is the cost of goods purchased?", ["117,000", "110,000", "103,000", "127,000"], 0, "120,000 − 5,000 − 5,000 + 7,000 = 117,000\n110,000 = left out freight-in · 103,000 = subtracted freight-in · 127,000 = ignored returns and discounts"], ["c6", "Inventory has an estimated selling price of 190,000, estimated costs to complete of 2,000 and estimated selling costs of 4,000. What is its net realizable value?", ["184,000", "186,000", "188,000", "190,000"], 0, "NRV = 190,000 − 2,000 − 4,000 = 184,000\n186,000 = left out the cost to complete · 188,000 = left out the selling costs · 190,000 = used the selling price"], ["c6", "Which are acceptable ways of applying lower of cost and NRV?", ["Item by item, or by major group of items", "Only to the whole inventory in total", "Only to items that are damaged", "Only to items sold after year end"], 0, "The test can be applied per item or per major group\n\"Only to the whole inventory in total\" = believed only a total comparison is allowed · \"Only to items that are damaged\" = limited it to damaged goods · \"Only to items sold after year end\" = limited it to later sales"], ["c6", "Beginning inventory is 40 units at 35 each. The company buys 35 more units at 50 each, then sells 45 units at 60 each (periodic system). What is gross profit under FIFO?", ["1,050", "600", "810", "1,200"], 0, "Sales 2,700 − FIFO COGS 1,650 = 1,050 (COGS = 40×35 + 5×50)\n600 = used LIFO cost of goods sold · 810 = used weighted-average cost of goods sold · 1,200 = subtracted ending inventory instead of cost of goods sold"], ["c6", "Beginning inventory is 10 units at 55 each. The company buys 15 more units at 60 each and sells 15 units. What is ending inventory under FIFO?", ["600", "580", "550", "850"], 0, "10 units remain, all from the latest lot: 10×60 = 600\n580 = used the weighted-average cost · 550 = assumed the oldest lot is what remains · 850 = gave cost of goods sold instead of ending inventory"], ["c6", "A very low inventory turnover most likely signals which problem?", ["Overstocking or obsolete goods", "Stock-outs and lost sales", "Excessive cash payments to suppliers", "A fall in credit sales only"], 0, "Slow turnover means goods sit unsold, a sign of too much stock or obsolescence\n\"Stock-outs and lost sales\" = read low turnover as too little stock · \"Excessive cash payments to suppliers\" = confused turnover with payment timing · \"A fall in credit sales only\" = confused turnover with credit policy"], ["c6", "A company buys three lots during the period: 10 units at 65, 10 units at 75 and 40 units at 85. What is the weighted-average cost per unit?", ["80", "75", "85", "65"], 0, "Total cost 4,800 ÷ 60 units = 80\n75 = simple average of the unit costs, ignoring quantities · 85 = used only the latest cost · 65 = used only the oldest cost"], ["c6", "Perpetual system, FIFO. Beginning inventory is 20 units at 80 each. The company sells 10 units, then buys 40 units at 90 each, then sells 40 units. What is the cost of the second sale?", ["3,500", "3,600", "3,520", "3,200"], 0, "10 older units at 80 are used first, then 30 units at 90: 3,500\n3,600 = costed the whole sale at the latest purchase cost · 3,520 = used a weighted average of the goods on hand · 3,200 = costed the whole sale at the beginning cost"], ["c6", "Beginning inventory is 10 units at 50 each. The company buys 15 more units at 60 each and sells 20 units. What is ending inventory under FIFO?", ["300", "280", "250", "1,100"], 0, "5 units remain, all from the latest lot: 5×60 = 300\n280 = used the weighted-average cost · 250 = assumed the oldest lot is what remains · 1,100 = gave cost of goods sold instead of ending inventory"], ["c6", "Under the periodic system, when is cost of goods sold determined?", ["At period end, after the physical count", "At each sale", "At each purchase", "When the supplier is paid"], 0, "Periodic COGS = beginning inventory + purchases − ending inventory, which needs the count\n\"At each sale\" = described the perpetual system · \"At each purchase\" = confused purchases with cost of sales · \"When the supplier is paid\" = tied COGS to payment timing"], ["c6", "Why should a company use the same costing method every period?", ["So results are comparable from period to period", "So taxes are always lower", "So inventory always equals market price", "Because standards prohibit any change in all circumstances"], 0, "Consistency supports comparability\n\"So taxes are always lower\" = assumed the goal is lower taxes · \"So inventory always equals market price\" = confused consistency with market valuation · \"Because standards prohibit any change in all circumstances\" = overlooked that justified changes are allowed with disclosure"], ["c6", "Inventory has an estimated selling price of 190,000, estimated costs to complete of 3,000 and estimated selling costs of 7,000. What is its net realizable value?", ["180,000", "183,000", "187,000", "190,000"], 0, "NRV = 190,000 − 3,000 − 7,000 = 180,000\n183,000 = left out the cost to complete · 187,000 = left out the selling costs · 190,000 = used the selling price"], ["c6", "Beginning inventory is 40 units at 55 each. The company buys 35 more units at 70 each, then sells 45 units (periodic system, all purchases made before the sales). What is cost of goods sold under FIFO?", ["2,550", "3,000", "2,790", "2,100"], 0, "FIFO uses the oldest costs first: (40×55) + (5×70) = 2,550\n3,000 = costed the latest lots first (LIFO) · 2,790 = used the weighted-average cost · 2,100 = gave ending inventory instead of cost of goods sold"], ["c6", "Inventory costs 120,000. Its estimated selling price is 129,000, with estimated completion costs of 6,000 and selling costs of 6,000. Applying lower of cost and NRV, what write-down is required?", ["3,000", "12,000", "117,000", "9,000"], 0, "NRV = 129,000 − 6,000 − 6,000 = 117,000, below cost 120,000; write-down = 120,000 − 117,000 = 3,000\n12,000 = wrote down by the completion and selling costs · 117,000 = treated NRV itself as the loss · 9,000 = wrote down by the amount the selling price exceeds cost"], ["c6", "Periodic system: beginning inventory 20,000; purchases 230,000; purchase returns 2,000; purchase discounts 1,000; freight-in 7,000; ending inventory 60,000. What is cost of goods sold?", ["194,000", "187,000", "197,000", "314,000"], 0, "Cost of goods purchased = 230,000 − 2,000 − 1,000 + 7,000 = 234,000; COGS = 20,000 + 234,000 − 60,000 = 194,000\n187,000 = left out freight-in · 197,000 = ignored purchase returns and discounts · 314,000 = added ending inventory instead of subtracting it"], ["c6", "On the last day of the year, goods shipped FOB shipping point are still in transit to your company. Whose inventory are they?", ["Your company's (the buyer's), because ownership passes when the goods are shipped", "The seller's, until the goods arrive", "The carrier's, until delivery", "Neither, until the invoice is paid"], 0, "FOB shipping point transfers ownership at shipment, so the buyer includes the goods in its inventory\n\"The seller's, until the goods arrive\" = mixed up FOB shipping point with FOB destination · \"The carrier's, until delivery\" = thought the carrier owns goods in transit · \"Neither, until the invoice is paid\" = tied ownership to payment instead of shipping terms"], ["c6", "Beginning inventory 40,000, ending inventory 60,000, cost of goods sold 200,000. What is the inventory turnover (times)?", ["4.0", "3.3", "5.0", "0.5"], 0, "Average inventory = (40,000 + 60,000) ÷ 2 = 50,000; 200,000 ÷ 50,000 = 4\n3.3 = used ending inventory instead of the average · 5.0 = used beginning inventory instead of the average · 0.5 = divided average inventory by COGS (inverted)"], ["c6", "Under the periodic system, purchases of merchandise are debited to which account?", ["Purchases", "Merchandise inventory", "Cost of goods sold", "Accounts payable"], 0, "Periodic systems collect purchases in a Purchases account until the end-of-period count\n\"Merchandise inventory\" = used the perpetual system treatment · \"Cost of goods sold\" = recorded cost of sales at purchase time · \"Accounts payable\" = confused the debit side with the credit"], ["c6", "Ending inventory 42,000, beginning inventory 38,000, cost of goods sold 320,000 (365-day year). What are days' sales in inventory (to the nearest day)?", ["48 days", "46 days", "43 days", "47 days"], 0, "(42,000 ÷ 320,000) × 365 = 48 days\n46 days = used average inventory instead of ending inventory · 43 days = used beginning inventory · 47 days = used a 360-day year"], ["c6", "Which costing method can give different cost of goods sold under the periodic and perpetual systems?", ["Weighted average", "FIFO", "Specific identification", "None; all methods always differ"], 0, "FIFO and specific ID give the same results either way; weighted average depends on when the average is computed\n\"FIFO\" = assumed FIFO changes between systems · \"Specific identification\" = assumed actual costs change between systems · \"None; all methods always differ\" = assumed every method differs"], ["c6", "Inventory cost is 50,000 and its NRV is 58,000. At what amount is it reported?", ["50,000, its cost; there is no write-up", "58,000", "54,000", "58,000 with an 8,000 gain recognised"], 0, "Lower of cost and NRV never writes inventory above cost\n\"58,000\" = wrote the inventory up to NRV · \"54,000\" = averaged cost and NRV · \"58,000 with an 8,000 gain recognised\" = recognised an unrealised gain"], ["c6", "Inventory costs 60,000. Its estimated selling price is 68,000, with estimated completion costs of 3,000 and selling costs of 7,000. Applying lower of cost and NRV, what write-down is required?", ["2,000", "10,000", "58,000", "8,000"], 0, "NRV = 68,000 − 3,000 − 7,000 = 58,000, below cost 60,000; write-down = 60,000 − 58,000 = 2,000\n10,000 = wrote down by the completion and selling costs · 58,000 = treated NRV itself as the loss · 8,000 = wrote down by the amount the selling price exceeds cost"], ["c6", "Beginning inventory is 48,000 and ending inventory is 52,000. What is average inventory?", ["50,000", "52,000", "100,000", "4,000"], 0, "(48,000 + 52,000) ÷ 2 = 50,000\n52,000 = used ending inventory only · 100,000 = added without dividing by 2 · 4,000 = took the change in inventory"], ["c6", "Beginning inventory is 20 units at 40 each. The company buys 30 more units at 60 each and sells 45 units. What is ending inventory under weighted average?", ["260", "300", "200", "2,340"], 0, "Average cost = 2,600 ÷ 50 = 52; 5 units × 52 = 260\n300 = used the latest cost (FIFO) · 200 = used the oldest cost · 2,340 = gave cost of goods sold instead of ending inventory"], ["c6", "Beginning inventory is 20 units at 35 each. The company buys 30 more units at 50 each, then sells 30 units at 75 each (periodic system). What is gross profit under FIFO?", ["1,050", "750", "930", "1,250"], 0, "Sales 2,250 − FIFO COGS 1,200 = 1,050 (COGS = 20×35 + 10×50)\n750 = used LIFO cost of goods sold · 930 = used weighted-average cost of goods sold · 1,250 = subtracted ending inventory instead of cost of goods sold"], ["c6", "A buyer returns defective goods to the supplier. How is inventory cost affected?", ["Cost decreases by the invoice price of the returned goods", "Cost is unchanged; the return is recorded as an expense", "Cost increases by the shipping cost to send them back", "Cost decreases only if the goods were already sold"], 0, "Purchase returns reduce the cost of goods purchased and so inventory\n\"Cost is unchanged; the return is recorded as an expense\" = treated a return as an expense · \"Cost increases by the shipping cost to send them back\" = added return shipping to inventory · \"Cost decreases only if the goods were already sold\" = confused returns of unsold goods with sales returns"], ["c6", "A company reporting under IFRS wants to use LIFO. What is the correct response?", ["It is not allowed; it must use FIFO, weighted average or specific identification", "It is allowed if disclosed in the notes", "It is allowed only for items bought in the last quarter", "It is allowed when prices are rising"], 0, "IFRS prohibits LIFO\n\"It is allowed if disclosed in the notes\" = assumed disclosure makes LIFO acceptable · \"It is allowed only for items bought in the last quarter\" = invented a partial exception · \"It is allowed when prices are rising\" = thought price trends permit LIFO"], ["c6", "A fire destroyed the inventory. Net sales were 250,000 at a normal gross profit rate of 30% of sales. Beginning inventory was 50,000 and net purchases 310,000. Using the gross profit method, what is the estimated inventory lost?", ["185,000", "285,000", "110,000", "175,000"], 0, "Estimated COGS = 250,000 × (1 − 30%) = 175,000; goods available 360,000 − 175,000 = 185,000\n285,000 = used the gross profit as cost of goods sold · 110,000 = ignored the gross margin and treated sales as cost · 175,000 = gave estimated cost of goods sold instead of ending inventory"], ["c6", "Beginning inventory is 35 units at 70 each. The company buys 35 more units at 80 each, then sells 45 units at 95 each (periodic system). What is gross profit under FIFO?", ["1,025", "775", "900", "2,275"], 0, "Sales 4,275 − FIFO COGS 3,250 = 1,025 (COGS = 35×70 + 10×80)\n775 = used LIFO cost of goods sold · 900 = used weighted-average cost of goods sold · 2,275 = subtracted ending inventory instead of cost of goods sold"], ["c6", "Periodic system: beginning inventory 60,000; purchases 290,000; purchase returns 8,000; purchase discounts 2,000; freight-in 7,000; ending inventory 55,000. What is the cost of goods available for sale?", ["347,000", "350,000", "292,000", "287,000"], 0, "60,000 + (290,000 − 8,000 − 2,000 + 7,000) = 347,000\n350,000 = used gross purchases, ignoring returns, discounts and freight-in · 292,000 = subtracted ending inventory (that is cost of goods sold) · 287,000 = left out beginning inventory"], ["c6", "Beginning inventory is 10 units at 40 each. The company buys 15 more units at 55 each and sells 20 units. What is ending inventory under weighted average?", ["245", "275", "200", "980"], 0, "Average cost = 1,225 ÷ 25 = 49; 5 units × 49 = 245\n275 = used the latest cost (FIFO) · 200 = used the oldest cost · 980 = gave cost of goods sold instead of ending inventory"], ["c6", "A company buys three lots during the period: 40 units at 50, 25 units at 55 and 10 units at 60. 35 units remain unsold at period end. What is ending inventory under weighted average?", ["1,855", "1,925", "2,100", "1,750"], 0, "Average cost 3,975 ÷ 75 = 53; 35 × 53 = 1,855\n1,925 = used the simple average of unit costs · 2,100 = used the latest cost · 1,750 = used the oldest cost"], ["c6", "Inventory has an estimated selling price of 110,000, estimated costs to complete of 6,000 and estimated selling costs of 8,000. What is its net realizable value?", ["96,000", "102,000", "104,000", "110,000"], 0, "NRV = 110,000 − 6,000 − 8,000 = 96,000\n102,000 = left out the cost to complete · 104,000 = left out the selling costs · 110,000 = used the selling price"], ["c6", "Which system updates the Merchandise inventory account at every purchase and sale?", ["Perpetual", "Periodic", "Both systems equally", "Neither; inventory is updated only by auditors"], 0, "Perpetual records keep inventory and COGS up to date after each transaction\n\"Periodic\" = mixed up the two systems · \"Both systems equally\" = assumed no difference between the systems · \"Neither; inventory is updated only by auditors\" = believed inventory is never updated in the books"], ["c6", "Which cost is NOT part of the cost of merchandise inventory?", ["Freight-out on delivery to customers", "Freight-in", "Import duties", "Insurance on goods in transit"], 0, "Inventory cost includes costs to bring goods to a saleable condition and location; freight-out is a selling expense\n\"Freight-in\" = thought transport into the business is a selling cost · \"Import duties\" = thought taxes on purchases are period expenses · \"Insurance on goods in transit\" = thought insurance is always an expense"], ["c6", "At the end of Year 1, ending inventory was overstated by 5,000 and was never corrected. What is the effect on Year 1 cost of goods sold?", ["Understated by 5,000", "Overstated by 5,000", "No effect", "Understated by 10,000"], 0, "Year 1: COGS = Beginning + Purchases − Ending, so an ending-inventory error moves COGS the opposite way and profit the same way; the same amount reverses in Year 2 through beginning inventory\nOverstated by 5,000 = reversed the direction of the effect · No effect = assumed the error has no effect · Understated by 10,000 = double counted the error"], ["c6", "Inventory costs 100,000. Its estimated selling price is 107,000, with estimated completion costs of 4,000 and selling costs of 6,000. Applying lower of cost and NRV, what write-down is required?", ["3,000", "10,000", "97,000", "7,000"], 0, "NRV = 107,000 − 4,000 − 6,000 = 97,000, below cost 100,000; write-down = 100,000 − 97,000 = 3,000\n10,000 = wrote down by the completion and selling costs · 97,000 = treated NRV itself as the loss · 7,000 = wrote down by the amount the selling price exceeds cost"], ["c6", "At the end of Year 1, ending inventory was understated by 10,000 and was never corrected. What is the effect on retained earnings at the end of Year 2?", ["No effect", "Understated by 10,000", "Overstated by 10,000", "Understated by 20,000"], 0, "The Year 1 error reverses in Year 2, so cumulative profit and retained earnings are correct by the end of Year 2\nUnderstated by 10,000 = carried the Year 1 error forward without it reversing · Overstated by 10,000 = reversed the direction of the effect · Understated by 20,000 = double counted the error"], ["c6", "When purchase prices rise, which method gives the highest ending inventory?", ["FIFO", "Weighted average", "LIFO", "They are all the same"], 0, "FIFO leaves the latest, higher costs in ending inventory\n\"Weighted average\" = thought averaging gives the highest value · \"LIFO\" = mixed up which lots remain under LIFO · \"They are all the same\" = ignored the cost flow assumption"], ["c6", "A company buys three lots during the period: 10 units at 80, 15 units at 90 and 25 units at 100. What is the weighted-average cost per unit?", ["93", "90", "100", "80"], 0, "Total cost 4,650 ÷ 50 units = 93\n90 = simple average of the unit costs, ignoring quantities · 100 = used only the latest cost · 80 = used only the oldest cost"], ["c6", "Perpetual system, FIFO. Beginning inventory is 35 units at 40 each. The company sells 20 units, then buys 30 units at 55 each, then sells 20 units. What is the cost of the second sale?", ["875", "1,100", "1,000", "800"], 0, "15 older units at 40 are used first, then 5 units at 55: 875\n1,100 = costed the whole sale at the latest purchase cost · 1,000 = used a weighted average of the goods on hand · 800 = costed the whole sale at the beginning cost"], ["c6", "A product is damaged but can still be sold at a reduced price. At what amount should it be reported?", ["At net realizable value if that is below cost", "At original cost until it is sold", "At zero, because damaged goods are never inventory", "At the original selling price"], 0, "Goods that can still be sold are written down to NRV when NRV is below cost\n\"At original cost until it is sold\" = ignored lower of cost and NRV · \"At zero, because damaged goods are never inventory\" = confused sellable damaged goods with unsellable ones · \"At the original selling price\" = reported at selling price instead of a cost-based amount"], ["c6", "Beginning inventory is 10 units at 45 each. The company buys 30 more units at 65 each and sells 25 units. What is ending inventory under weighted average?", ["900", "975", "675", "1,500"], 0, "Average cost = 2,400 ÷ 40 = 60; 15 units × 60 = 900\n975 = used the latest cost (FIFO) · 675 = used the oldest cost · 1,500 = gave cost of goods sold instead of ending inventory"], ["c8", "Checks issued in the month: #401 for 450, #402 for 850, #403 for 1,650, #404 for 1,950, #405 for 800, #406 for 1,200. The bank statement shows these checks cleared: #403, #404, #405, #406. What is the total of outstanding checks?", ["1,300", "5,600", "6,900", "850"], 0, "Outstanding = issued but not cleared: #401, #402 = 1,300\n5,600 = added the checks that cleared · 6,900 = added every check issued · 850 = overlooked one outstanding check"], ["c8", "Checks issued in the month: #401 for 1,400, #402 for 1,650, #403 for 100, #404 for 850, #405 for 800, #406 for 450. The bank statement shows these checks cleared: #401, #404, #405. What is the total of outstanding checks?", ["2,200", "3,050", "5,250", "2,100"], 0, "Outstanding = issued but not cleared: #402, #403, #406 = 2,200\n3,050 = added the checks that cleared · 5,250 = added every check issued · 2,100 = overlooked one outstanding check"], ["c8", "After reconciling, which balance does the company report on the balance sheet?", ["The adjusted balance", "The bank statement balance", "The book balance before adjustments", "The higher of the two balances"], 0, "The adjusted (reconciled) balance is the correct cash amount\n\"The bank statement balance\" = used an unadjusted balance · \"The book balance before adjustments\" = used an unadjusted balance · \"The higher of the two balances\" = chose by size instead of correctness"], ["c8", "A reconciliation leads to these entries in the company's books: automatic insurance debit not yet recorded 90; NSF check 150; customer EFT receipt not yet recorded 520. By how much do the adjusting entries change the Cash account?", ["Increase of 280", "Decrease of 280", "Increase of 370", "Decrease of 760"], 0, "Increases: 520; decreases: 240; net = Increase of 280\nDecrease of 280 = reversed the direction of the net change · Increase of 370 = left out the automatic insurance debit not yet recorded · Decrease of 760 = treated every item as a decrease"], ["c8", "Balance per books 13,250. The bank statement shows: automatic insurance debit not yet recorded 580; bank service charge 520; interest earned 200; NSF check 270. Deposits in transit are 2,950 and outstanding checks 900. What is the adjusted cash balance on the book side?", ["12,080", "13,240", "11,180", "11,680"], 0, "13,250 − 580 − 520 + 200 − 270 = 12,080; deposits in transit and outstanding checks are bank-side items\n13,240 = added the automatic insurance debit not yet recorded instead of deducting it · 11,180 = also deducted outstanding checks, which are bank-side items · 11,680 = deducted the interest earned instead of adding it"], ["c8", "Bank statement balance 46,800; deposits in transit 4,600; outstanding checks 3,300. Balance per books 48,375; interest earned 140; NSF check 400; service charge 15. What cash amount is reported on the balance sheet?", ["48,100", "46,800", "48,375", "43,500"], 0, "Bank side: 46,800 + 4,600 − 3,300 = 48,100; book side: 48,375 + 140 − 400 − 15 = 48,100\n46,800 = used the unadjusted bank balance · 48,375 = used the unadjusted book balance · 43,500 = left out deposits in transit"], ["c8", "The bank deducted a 35 service charge that the company has not recorded. Which entry does the company record?", ["Dr. Bank service charges expense 35 / Cr. Cash 35", "Dr. Cash 35 / Cr. Bank service charges expense 35", "Dr. Accounts payable 35 / Cr. Cash 35", "No entry; the bank has already recorded it"], 0, "The fee is an expense that reduces Cash\n\"Dr. Cash 35 / Cr. Bank service charges expense 35\" = reversed the entry · \"Dr. Accounts payable 35 / Cr. Cash 35\" = used a payable that never existed · \"No entry; the bank has already recorded it\" = treated it as a bank-only item"], ["c8", "Checks issued in the month: #401 for 1,150, #402 for 2,000, #403 for 100, #404 for 900, #405 for 1,200, #406 for 1,950. The bank statement shows these checks cleared: #401, #402, #404. What is the total of outstanding checks?", ["3,250", "4,050", "7,300", "3,150"], 0, "Outstanding = issued but not cleared: #403, #405, #406 = 3,250\n4,050 = added the checks that cleared · 7,300 = added every check issued · 3,150 = overlooked one outstanding check"], ["c8", "Balance per books 39,800. The bank statement shows: customer EFT receipt not yet recorded 150; NSF check 550; automatic insurance debit not yet recorded 420. Deposits in transit are 2,950 and outstanding checks 3,350. What is the adjusted cash balance on the book side?", ["38,980", "40,080", "35,630", "38,680"], 0, "39,800 + 150 − 550 − 420 = 38,980; deposits in transit and outstanding checks are bank-side items\n40,080 = added the NSF check instead of deducting it · 35,630 = also deducted outstanding checks, which are bank-side items · 38,680 = deducted the customer EFT receipt not yet recorded instead of adding it"], ["c8", "After reconciliation the adjusted cash balance is 22,700 (bank balance 21,000, deposits in transit 4,950, outstanding checks 3,250). The company's adjusting entries were interest earned 160, NSF check 550 and service charge 80. What was the balance per books before adjustments?", ["23,170", "22,230", "21,000", "22,700"], 0, "Book balance + 160 − 550 − 80 = 22,700, so book balance = 22,700 − 160 + 550 + 80 = 23,170\n22,230 = reversed every book-side adjustment · 21,000 = used the unadjusted bank balance · 22,700 = assumed no book-side adjustments were needed"], ["c8", "Who should prepare the bank reconciliation?", ["Someone who neither handles cash receipts nor records cash transactions", "The cashier who deposits the receipts", "The bookkeeper who writes the checks", "Whoever signs the checks"], 0, "Separation of duties prevents one person from hiding theft\n\"The cashier who deposits the receipts\" = removed separation of duties · \"The bookkeeper who writes the checks\" = removed separation of duties · \"Whoever signs the checks\" = removed separation of duties"], ["c8", "After reconciliation the adjusted cash balance is 28,050 (bank balance 30,900, deposits in transit 900, outstanding checks 3,750). The company's adjusting entries were interest earned 230, NSF check 300 and service charge 65. What was the balance per books before adjustments?", ["28,185", "27,915", "30,900", "28,050"], 0, "Book balance + 230 − 300 − 65 = 28,050, so book balance = 28,050 − 230 + 300 + 65 = 28,185\n27,915 = reversed every book-side adjustment · 30,900 = used the unadjusted bank balance · 28,050 = assumed no book-side adjustments were needed"], ["c8", "The bank added 60 of interest to the account. Which entry does the company record?", ["Dr. Cash 60 / Cr. Interest revenue 60", "Dr. Interest revenue 60 / Cr. Cash 60", "Dr. Cash 60 / Cr. Unearned revenue 60", "No entry; the bank has already recorded it"], 0, "Interest earned is revenue that increases Cash\n\"Dr. Interest revenue 60 / Cr. Cash 60\" = reversed the entry · \"Dr. Cash 60 / Cr. Unearned revenue 60\" = treated earned interest as unearned · \"No entry; the bank has already recorded it\" = treated it as a bank-only item"], ["c8", "A customer's deposited check was returned by the bank for insufficient funds (NSF), and the company has not recorded this. How is this item handled in the bank reconciliation?", ["Deduct from the book balance; record a journal entry", "Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Add to the book balance; record a journal entry"], 0, "The bank has already deducted the NSF check, so the company deducts it from its books and records an entry\n\"Add to the bank statement balance; no journal entry\" = wrong side and wrong direction · \"Deduct from the bank statement balance; no journal entry\" = wrong side, right direction · \"Add to the book balance; record a journal entry\" = right side, wrong direction"], ["c8", "Which is a correct first step in preparing a bank reconciliation?", ["Compare deposits in the books to statement credits, and checks written to checks cleared", "Record the adjusting entries before comparing", "Adjust the bank balance for service charges", "Subtract outstanding checks from the book balance"], 0, "Matching the records identifies the reconciling items\n\"Record the adjusting entries before comparing\" = recorded entries before identifying items · \"Adjust the bank balance for service charges\" = applied a book-side item to the bank side · \"Subtract outstanding checks from the book balance\" = applied a bank-side item to the book side"], ["c8", "Which list contains only book-side reconciling items?", ["NSF check, service charge, interest earned", "Deposits in transit, outstanding checks, NSF check", "Outstanding checks, service charge, bank error", "Deposits in transit, interest earned, bank error"], 0, "Book-side items are known to the bank but not yet recorded by the company\n\"Deposits in transit, outstanding checks, NSF check\" = mixed bank-side items into the list · \"Outstanding checks, service charge, bank error\" = mixed bank-side items into the list · \"Deposits in transit, interest earned, bank error\" = mixed bank-side items into the list"], ["c8", "A difference remains after adjusting for all known items. What is the best action?", ["Investigate it, since it may signal errors or fraud, and do not hide it in another account", "Record it in Miscellaneous expense and move on", "Adjust the bank balance until it agrees", "Ignore it if it is under 1%"], 0, "Unexplained differences should be investigated, not plugged\n\"Record it in Miscellaneous expense and move on\" = buried the difference · \"Adjust the bank balance until it agrees\" = forced the balances to agree · \"Ignore it if it is under 1%\" = applied an arbitrary materiality rule"], ["c8", "Deposits recorded by the company: Oct 26 3,850, Oct 28 1,200, Oct 30 1,500, Oct 31 800. The bank statement dated Oct 31 shows credits for the Oct 26 and Oct 28 deposits only. What are the deposits in transit?", ["2,300", "5,050", "7,350", "1,500"], 0, "Not yet on the statement: Oct 30 1,500 + Oct 31 800 = 2,300\n5,050 = added the deposits the bank already recorded · 7,350 = added every deposit · 1,500 = overlooked one deposit in transit"], ["c8", "Which accounts change when the company records the entries from a bank reconciliation?", ["Cash and the accounts for the book-side items, such as receivables or expenses", "Only the bank’s records", "Only Cash", "Only Accounts payable"], 0, "Each book-side item has a debit and a credit, one of which is Cash\n\"Only the bank’s records\" = confused the company’s books with the bank’s · \"Only Cash\" = forgot double-entry bookkeeping · \"Only Accounts payable\" = assumed one account takes every entry"], ["c8", "The bank recorded a company deposit of 1,300 as 1,030. How is this item handled in the bank reconciliation?", ["Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Add to the book balance; record a journal entry", "Deduct from the book balance; record a journal entry"], 0, "A bank error is corrected on the bank side by adding 270; no company entry is needed\n\"Deduct from the bank statement balance; no journal entry\" = right side, wrong direction · \"Add to the book balance; record a journal entry\" = wrong side, right direction · \"Deduct from the book balance; record a journal entry\" = wrong side and wrong direction"], ["c8", "A reconciliation leads to these entries in the company's books: bank service charge 240; interest earned 160; customer EFT receipt not yet recorded 370; NSF check 480. By how much do the adjusting entries change the Cash account?", ["Decrease of 190", "Increase of 190", "Decrease of 350", "Decrease of 1,250"], 0, "Increases: 530; decreases: 720; net = Decrease of 190\nIncrease of 190 = reversed the direction of the net change · Decrease of 350 = left out the interest earned · Decrease of 1,250 = treated every item as a decrease"], ["c8", "A reconciliation leads to these entries in the company's books: automatic insurance debit not yet recorded 30; interest earned 210; customer EFT receipt not yet recorded 400. By how much do the adjusting entries change the Cash account?", ["Increase of 580", "Decrease of 580", "Increase of 610", "Decrease of 640"], 0, "Increases: 610; decreases: 30; net = Increase of 580\nDecrease of 580 = reversed the direction of the net change · Increase of 610 = left out the automatic insurance debit not yet recorded · Decrease of 640 = treated every item as a decrease"], ["c8", "The bank collected a note receivable of 7,000 plus 130 interest for the company and deducted a 20 collection fee. The company had not recorded any of this. How much is debited to Cash in the adjusting entry?", ["7,110", "7,130", "6,980", "7,000"], 0, "Cash received = 7,000 + 130 − 20 = 7,110\n7,130 = ignored the collection fee · 6,980 = left out the interest · 7,000 = recorded the principal only"], ["c8", "The reconciled (adjusted) cash balance is 15,900. Deposits in transit were 2,200 and outstanding checks 3,150. What was the bank statement balance?", ["16,850", "14,950", "13,700", "15,900"], 0, "Bank balance + 2,200 − 3,150 = 15,900, so bank balance = 15,900 − 2,200 + 3,150 = 16,850\n14,950 = swapped the signs of deposits in transit and outstanding checks · 13,700 = left out outstanding checks · 15,900 = assumed there were no bank-side reconciling items"], ["c8", "The reconciled (adjusted) cash balance is 42,700. Deposits in transit were 5,000 and outstanding checks 3,800. What was the bank statement balance?", ["41,500", "43,900", "37,700", "42,700"], 0, "Bank balance + 5,000 − 3,800 = 42,700, so bank balance = 42,700 − 5,000 + 3,800 = 41,500\n43,900 = swapped the signs of deposits in transit and outstanding checks · 37,700 = left out outstanding checks · 42,700 = assumed there were no bank-side reconciling items"], ["c8", "Bank statement balance 33,050. Deposits in transit 2,000. Outstanding checks: #301 for 1,750, #305 for 2,300. The company has not yet recorded a bank service charge of 50. What is the adjusted cash balance on the bank side?", ["31,000", "35,100", "30,950", "29,000"], 0, "33,050 + 2,000 − 4,050 = 31,000; the service charge is a book-side item\n35,100 = swapped the signs of deposits in transit and outstanding checks · 30,950 = also deducted a service charge, which is a book-side item · 29,000 = left out deposits in transit"], ["c8", "The bank credited the company’s account with interest earned that the company has not recorded. How is this item handled in the bank reconciliation?", ["Add to the book balance; record a journal entry", "Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Deduct from the book balance; record a journal entry"], 0, "The bank has already added the interest, so the company adds it to its books and records revenue\n\"Add to the bank statement balance; no journal entry\" = wrong side, right direction · \"Deduct from the bank statement balance; no journal entry\" = wrong side and wrong direction · \"Deduct from the book balance; record a journal entry\" = right side, wrong direction"], ["c8", "The company finds a bank error on the statement. What should it do?", ["Notify the bank to correct it; the company makes no journal entry", "Record a journal entry to match the bank’s figure", "Wait until the bank notices", "Adjust Cash on the book side anyway"], 0, "Bank errors are fixed by the bank; the bank-side adjusted balance corrects for them\n\"Record a journal entry to match the bank’s figure\" = corrected the books for a bank mistake · \"Wait until the bank notices\" = left a known error uncorrected · \"Adjust Cash on the book side anyway\" = applied a bank-side item to the book side"], ["c8", "A customer paid the company by electronic transfer, and the bank credited it; the company has not recorded it. How is this item handled in the bank reconciliation?", ["Add to the book balance; record a journal entry", "Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Deduct from the book balance; record a journal entry"], 0, "Unrecorded bank credits are added on the book side with an entry\n\"Add to the bank statement balance; no journal entry\" = wrong side, right direction · \"Deduct from the bank statement balance; no journal entry\" = wrong side and wrong direction · \"Deduct from the book balance; record a journal entry\" = right side, wrong direction"], ["c8", "A deposit of 380 was recorded in the company's books as 830; the bank credited 380. The balance per books before correcting the error is 39,700. What is the correct book balance?", ["39,250", "40,150", "39,700", "40,080"], 0, "Books were increased by 830 instead of 380; correct balance = 39,700 + 380 − 830 = 39,250\n40,150 = reversed the direction of the correction · 39,700 = treated it as a bank-side item and left the book balance unchanged · 40,080 = added the full deposit a second time"], ["c8", "What is a signature card used for?", ["It shows who is authorised to sign on the account", "It lists deposits in transit", "It records outstanding checks", "It shows interest earned"], 0, "The card identifies authorised signers\n\"It lists deposits in transit\" = confused it with a reconciliation list · \"It records outstanding checks\" = confused it with a check register · \"It shows interest earned\" = confused it with a statement item"], ["c8", "Balance per books 21,550. The bank statement shows: interest earned 360; customer EFT receipt not yet recorded 330; bank service charge 170; automatic insurance debit not yet recorded 290. Deposits in transit are 2,950 and outstanding checks 1,600. What is the adjusted cash balance on the book side?", ["21,780", "22,120", "20,180", "21,060"], 0, "21,550 + 360 + 330 − 170 − 290 = 21,780; deposits in transit and outstanding checks are bank-side items\n22,120 = added the bank service charge instead of deducting it · 20,180 = also deducted outstanding checks, which are bank-side items · 21,060 = deducted the interest earned instead of adding it"], ["c8", "Why do outstanding checks arise?", ["Payees take time to present the checks, so the company records the payment first", "The bank pays checks before they are written", "The bank refuses to clear them", "The company forgot to record them"], 0, "The company records the payment when it issues the check; the bank records it when paid\n\"The bank pays checks before they are written\" = reversed the timing · \"The bank refuses to clear them\" = confused them with returned checks · \"The company forgot to record them\" = confused timing differences with omissions"], ["c8", "Checks issued in the month: #401 for 1,200, #402 for 1,350, #403 for 1,050, #404 for 1,100, #405 for 850, #406 for 700. The bank statement shows these checks cleared: #402, #403, #404. What is the total of outstanding checks?", ["2,750", "3,500", "6,250", "2,050"], 0, "Outstanding = issued but not cleared: #401, #405, #406 = 2,750\n3,500 = added the checks that cleared · 6,250 = added every check issued · 2,050 = overlooked one outstanding check"], ["c8", "Bank statement balance 58,250. Deposits in transit 2,200. Outstanding checks: #301 for 300, #305 for 1,550, #309 for 2,350, #313 for 1,250. The company has not yet recorded a bank service charge of 20. What is the adjusted cash balance on the bank side?", ["55,000", "61,500", "54,980", "52,800"], 0, "58,250 + 2,200 − 5,450 = 55,000; the service charge is a book-side item\n61,500 = swapped the signs of deposits in transit and outstanding checks · 54,980 = also deducted a service charge, which is a book-side item · 52,800 = left out deposits in transit"], ["c8", "Balance per books 16,750. The bank statement shows: interest earned 370; NSF check 170; bank service charge 240; customer EFT receipt not yet recorded 80. Deposits in transit are 5,150 and outstanding checks 3,450. What is the adjusted cash balance on the book side?", ["16,790", "17,130", "13,340", "16,050"], 0, "16,750 + 370 − 170 − 240 + 80 = 16,790; deposits in transit and outstanding checks are bank-side items\n17,130 = added the NSF check instead of deducting it · 13,340 = also deducted outstanding checks, which are bank-side items · 16,050 = deducted the interest earned instead of adding it"], ["c8", "A customer’s 500 check deposited earlier was returned NSF. Which entry does the company record?", ["Dr. Accounts receivable 500 / Cr. Cash 500", "Dr. Cash 500 / Cr. Accounts receivable 500", "Dr. Sales returns 500 / Cr. Cash 500", "No entry; the bank has already recorded it"], 0, "The customer still owes the amount, so Accounts receivable is reinstated\n\"Dr. Cash 500 / Cr. Accounts receivable 500\" = reversed the entry · \"Dr. Sales returns 500 / Cr. Cash 500\" = treated it as a sales return although the sale stands · \"No entry; the bank has already recorded it\" = treated it as a bank-only item"], ["c8", "Balance per books 18,100. The bank statement shows: interest earned 50; NSF check 470; bank service charge 290; automatic insurance debit not yet recorded 380. Deposits in transit are 4,150 and outstanding checks 3,700. What is the adjusted cash balance on the book side?", ["17,010", "17,950", "13,310", "16,910"], 0, "18,100 + 50 − 470 − 290 − 380 = 17,010; deposits in transit and outstanding checks are bank-side items\n17,950 = added the NSF check instead of deducting it · 13,310 = also deducted outstanding checks, which are bank-side items · 16,910 = deducted the interest earned instead of adding it"], ["c8", "Deposits recorded by the company: Oct 26 2,900, Oct 28 3,350, Oct 30 2,300, Oct 31 3,450. The bank statement dated Oct 31 shows credits for the Oct 26 and Oct 28 deposits only. What are the deposits in transit?", ["5,750", "6,250", "12,000", "3,450"], 0, "Not yet on the statement: Oct 30 2,300 + Oct 31 3,450 = 5,750\n6,250 = added the deposits the bank already recorded · 12,000 = added every deposit · 3,450 = overlooked one deposit in transit"], ["c8", "Bank statement balance 43,500; deposits in transit 2,300; outstanding checks 1,300. Balance per books 45,145; interest earned 260; NSF check 850; service charge 55. What cash amount is reported on the balance sheet?", ["44,500", "43,500", "45,145", "42,200"], 0, "Bank side: 43,500 + 2,300 − 1,300 = 44,500; book side: 45,145 + 260 − 850 − 55 = 44,500\n43,500 = used the unadjusted bank balance · 45,145 = used the unadjusted book balance · 42,200 = left out deposits in transit"], ["c8", "After the two adjusted balances agree, what should the company do next?", ["Record journal entries for the book-side items only", "Record entries for all items, including deposits in transit and outstanding checks", "Adjust the bank balance in the company’s books", "Nothing; the reconciliation is only a memo"], 0, "Book-side items correct the company’s Cash account\n\"Record entries for all items, including deposits in transit and outstanding checks\" = recorded timing items that are already in the books · \"Adjust the bank balance in the company’s books\" = changed books for the bank’s balance · \"Nothing; the reconciliation is only a memo\" = treated adjusting entries as optional"], ["c8", "On a bank statement, what does a debit memo mean?", ["The bank deducted an amount from the customer’s account", "The bank added money to the customer’s account", "The customer made a deposit", "The customer has a deposit in transit"], 0, "A debit memo reduces the depositor’s balance\n\"The bank added money to the customer’s account\" = mixed up debit and credit memos · \"The customer made a deposit\" = confused a memo with a deposit · \"The customer has a deposit in transit\" = confused a bank memo with a timing item"], ["c8", "The reconciled (adjusted) cash balance is 32,600. Deposits in transit were 500 and outstanding checks 1,150. What was the bank statement balance?", ["33,250", "31,950", "32,100", "32,600"], 0, "Bank balance + 500 − 1,150 = 32,600, so bank balance = 32,600 − 500 + 1,150 = 33,250\n31,950 = swapped the signs of deposits in transit and outstanding checks · 32,100 = left out outstanding checks · 32,600 = assumed there were no bank-side reconciling items"], ["c8", "What is the main purpose of a bank reconciliation?", ["To explain the difference between the bank statement balance and the company’s cash balance", "To replace the monthly bank statement", "To increase the cash balance", "To estimate next month’s cash needs"], 0, "A reconciliation explains why the two balances differ and finds the correct cash balance\n\"To replace the monthly bank statement\" = thought the reconciliation substitutes the statement · \"To increase the cash balance\" = thought it creates cash · \"To estimate next month’s cash needs\" = confused it with cash forecasting"], ["c8", "Balance per books 23,000. The bank statement shows: bank service charge 190; interest earned 170; NSF check 360; customer EFT receipt not yet recorded 370. Deposits in transit are 1,750 and outstanding checks 550. What is the adjusted cash balance on the book side?", ["22,990", "23,370", "22,440", "22,650"], 0, "23,000 − 190 + 170 − 360 + 370 = 22,990; deposits in transit and outstanding checks are bank-side items\n23,370 = added the bank service charge instead of deducting it · 22,440 = also deducted outstanding checks, which are bank-side items · 22,650 = deducted the interest earned instead of adding it"], ["c8", "Checks issued in the month: #401 for 1,600, #402 for 450, #403 for 500, #404 for 550, #405 for 350, #406 for 400. The bank statement shows these checks cleared: #401, #403, #405, #406. What is the total of outstanding checks?", ["1,000", "2,850", "3,850", "550"], 0, "Outstanding = issued but not cleared: #402, #404 = 1,000\n2,850 = added the checks that cleared · 3,850 = added every check issued · 550 = overlooked one outstanding check"], ["c8", "Bank statement balance 49,800. Deposits in transit 1,100. Outstanding checks: #301 for 2,300, #305 for 2,150. The company has not yet recorded a bank service charge of 85. The bank wrongly charged 100 for another customer's check. What is the adjusted cash balance on the bank side?", ["46,550", "53,250", "46,465", "46,350"], 0, "49,800 + 1,100 − 4,450 + 100 = 46,550; the service charge is a book-side item\n53,250 = swapped the signs of deposits in transit and outstanding checks · 46,465 = also deducted a service charge, which is a book-side item · 46,350 = deducted the bank error instead of adding it back"], ["c8", "The bank collected a note receivable of 1,500 plus 180 interest for the company and deducted a 30 collection fee. The company had not recorded any of this. How much is credited to Interest revenue?", ["180", "150", "1,680", "30"], 0, "Interest earned of 180 is revenue; the fee 30 is a separate expense\n150 = netted the fee against interest · 1,680 = included the principal · 30 = recorded the fee amount instead"], ["c8", "Bank statement balance 13,350; deposits in transit 4,100; outstanding checks 1,450. Balance per books 16,635; interest earned 30; NSF check 600; service charge 65. What cash amount is reported on the balance sheet?", ["16,000", "13,350", "16,635", "11,900"], 0, "Bank side: 13,350 + 4,100 − 1,450 = 16,000; book side: 16,635 + 30 − 600 − 65 = 16,000\n13,350 = used the unadjusted bank balance · 16,635 = used the unadjusted book balance · 11,900 = left out deposits in transit"], ["c8", "Why do deposits in transit arise?", ["Receipts are recorded by the company before the bank has processed them", "The bank records deposits before the company does", "Customers’ checks are returned unpaid", "The company makes arithmetic errors"], 0, "A deposit made late in the month may reach the bank’s records after the statement date\n\"The bank records deposits before the company does\" = reversed the timing · \"Customers’ checks are returned unpaid\" = confused them with NSF checks · \"The company makes arithmetic errors\" = confused timing differences with errors"], ["c8", "The bank collected a note receivable of 2,000 plus 100 interest for the company and deducted a 25 collection fee. The company had not recorded any of this. How much is credited to Notes receivable?", ["2,000", "2,100", "1,975", "2,075"], 0, "Notes receivable is reduced by the principal only: 2,000\n2,100 = included interest in the principal · 1,975 = netted the fee against the principal · 2,075 = credited the net cash received"], ["c8", "Which of these is NOT a purpose of preparing a bank reconciliation?", ["To increase the cash held at the bank", "To detect errors", "To identify unrecorded items", "To help safeguard cash"], 0, "A reconciliation checks records; it does not change the cash actually held\n\"To detect errors\" = listed a real purpose · \"To identify unrecorded items\" = listed a real purpose · \"To help safeguard cash\" = listed a real purpose"], ["c8", "Bank statement balance 37,000. Deposits in transit 4,500. Outstanding checks: #301 for 1,000, #305 for 1,700. The company has not yet recorded a bank service charge of 15. What is the adjusted cash balance on the bank side?", ["38,800", "35,200", "38,785", "34,300"], 0, "37,000 + 4,500 − 2,700 = 38,800; the service charge is a book-side item\n35,200 = swapped the signs of deposits in transit and outstanding checks · 38,785 = also deducted a service charge, which is a book-side item · 34,300 = left out deposits in transit"], ["c8", "Which reconciling items require a journal entry?", ["NSF checks, service charges and interest earned", "Deposits in transit and outstanding checks", "Bank errors and outstanding checks", "All reconciling items"], 0, "Only book-side items change the company’s Cash account\n\"Deposits in transit and outstanding checks\" = listed timing items that the company already recorded · \"Bank errors and outstanding checks\" = listed bank-side items · \"All reconciling items\" = assumed every item needs an entry"], ["c8", "A customer paid a 900 invoice by electronic transfer and the bank credited it. Which entry does the company record?", ["Dr. Cash 900 / Cr. Accounts receivable 900", "Dr. Cash 900 / Cr. Sales revenue 900", "Dr. Accounts receivable 900 / Cr. Cash 900", "No entry; the bank has already recorded it"], 0, "The receivable is collected, so Accounts receivable falls and Cash rises\n\"Dr. Cash 900 / Cr. Sales revenue 900\" = recorded revenue again although the sale was already recognised · \"Dr. Accounts receivable 900 / Cr. Cash 900\" = reversed the entry · \"No entry; the bank has already recorded it\" = treated it as a bank-only item"], ["c8", "How often should bank reconciliations be prepared?", ["Monthly, when the statement arrives", "Only at fiscal year end", "Only when a difference is suspected", "Every five years by auditors"], 0, "Monthly reconciliations catch problems promptly\n\"Only at fiscal year end\" = delayed detection of errors and theft · \"Only when a difference is suspected\" = relied on suspicion instead of routine · \"Every five years by auditors\" = assumed auditors replace routine control"], ["c8", "Bank statement balance 20,150. Deposits in transit 2,750. Outstanding checks: #301 for 750, #305 for 750, #309 for 2,200. The company has not yet recorded a bank service charge of 25. The bank wrongly charged 300 for another customer's check. What is the adjusted cash balance on the bank side?", ["19,500", "21,400", "19,475", "18,900"], 0, "20,150 + 2,750 − 3,700 + 300 = 19,500; the service charge is a book-side item\n21,400 = swapped the signs of deposits in transit and outstanding checks · 19,475 = also deducted a service charge, which is a book-side item · 18,900 = deducted the bank error instead of adding it back"], ["c8", "Balance per books 27,750. The bank statement shows: NSF check 130; customer EFT receipt not yet recorded 280; automatic insurance debit not yet recorded 480; interest earned 130. Deposits in transit are 600 and outstanding checks 3,800. What is the adjusted cash balance on the book side?", ["27,550", "27,810", "23,750", "26,990"], 0, "27,750 − 130 + 280 − 480 + 130 = 27,550; deposits in transit and outstanding checks are bank-side items\n27,810 = added the NSF check instead of deducting it · 23,750 = also deducted outstanding checks, which are bank-side items · 26,990 = deducted the customer EFT receipt not yet recorded instead of adding it"], ["c8", "Deposits recorded by the company: Oct 26 1,350, Oct 28 2,050, Oct 30 3,950, Oct 31 3,350. The bank statement dated Oct 31 shows credits for the Oct 26 and Oct 28 deposits only. What are the deposits in transit?", ["7,300", "3,400", "10,700", "3,950"], 0, "Not yet on the statement: Oct 30 3,950 + Oct 31 3,350 = 7,300\n3,400 = added the deposits the bank already recorded · 10,700 = added every deposit · 3,950 = overlooked one deposit in transit"], ["c8", "Deposits recorded by the company: Oct 26 3,450, Oct 28 3,150, Oct 30 700, Oct 31 2,250. The bank statement dated Oct 31 shows credits for the Oct 26 and Oct 28 deposits only. What are the deposits in transit?", ["2,950", "6,600", "9,550", "2,250"], 0, "Not yet on the statement: Oct 30 700 + Oct 31 2,250 = 2,950\n6,600 = added the deposits the bank already recorded · 9,550 = added every deposit · 2,250 = overlooked one deposit in transit"], ["c8", "A deposit of 1,890 was recorded in the company's books as 1,980; the bank credited 1,890. The balance per books before correcting the error is 19,700. What is the correct book balance?", ["19,610", "19,790", "19,700", "21,590"], 0, "Books were increased by 1,980 instead of 1,890; correct balance = 19,700 + 1,890 − 1,980 = 19,610\n19,790 = reversed the direction of the correction · 19,700 = treated it as a bank-side item and left the book balance unchanged · 21,590 = added the full deposit a second time"], ["c8", "A check for 1,260 was recorded in the company's books as 1,620; the bank paid 1,260. The balance per books before correcting the error is 33,050. What is the correct book balance?", ["33,410", "32,690", "33,050", "31,790"], 0, "Books were reduced by 1,620 instead of 1,260; correct balance = 33,050 + 1,620 − 1,260 = 33,410\n32,690 = reversed the direction of the correction · 33,050 = treated it as a bank-side item and left the book balance unchanged · 31,790 = deducted the full check amount a second time"], ["c8", "The bank collected a note receivable of 2,500 plus 70 interest for the company and deducted a 10 collection fee. The company had not recorded any of this. How much is debited to Cash in the adjusting entry?", ["2,560", "2,570", "2,490", "2,500"], 0, "Cash received = 2,500 + 70 − 10 = 2,560\n2,570 = ignored the collection fee · 2,490 = left out the interest · 2,500 = recorded the principal only"], ["c8", "Balance per books 21,600. The bank statement shows: bank service charge 350; automatic insurance debit not yet recorded 240; interest earned 100. Deposits in transit are 1,050 and outstanding checks 1,500. What is the adjusted cash balance on the book side?", ["21,110", "21,810", "19,610", "20,910"], 0, "21,600 − 350 − 240 + 100 = 21,110; deposits in transit and outstanding checks are bank-side items\n21,810 = added the bank service charge instead of deducting it · 19,610 = also deducted outstanding checks, which are bank-side items · 20,910 = deducted the interest earned instead of adding it"], ["c8", "Bank statement balance 28,050; deposits in transit 1,250; outstanding checks 2,200. Balance per books 27,705; interest earned 200; NSF check 750; service charge 55. What cash amount is reported on the balance sheet?", ["27,100", "28,050", "27,705", "25,850"], 0, "Bank side: 28,050 + 1,250 − 2,200 = 27,100; book side: 27,705 + 200 − 750 − 55 = 27,100\n28,050 = used the unadjusted bank balance · 27,705 = used the unadjusted book balance · 25,850 = left out deposits in transit"], ["c8", "What is an NSF check?", ["A customer’s check returned unpaid because the customer’s account lacked funds", "A check the company wrote that has not cleared", "A check certified by the bank as good", "A deposit made after hours"], 0, "NSF = not sufficient funds\n\"A check the company wrote that has not cleared\" = confused it with an outstanding check · \"A check certified by the bank as good\" = confused it with a certified check · \"A deposit made after hours\" = confused it with a deposit in transit"], ["c8", "Which formula gives the adjusted book balance?", ["Book balance + interest and collections − NSF checks and fees ± book errors", "Book balance + outstanding checks − deposits in transit", "Book balance − interest + NSF checks", "Book balance + deposits in transit − outstanding checks"], 0, "The book side adjusts for items the bank has already recorded\n\"Book balance + outstanding checks − deposits in transit\" = used bank-side items · \"Book balance − interest + NSF checks\" = reversed the signs · \"Book balance + deposits in transit − outstanding checks\" = used bank-side items"], ["c8", "What is a primary internal-control benefit of the bank reconciliation?", ["It independently checks cash records and can reveal errors or theft", "It removes the need to record cash receipts", "It guarantees the bank is never wrong", "It replaces the cash count"], 0, "An independent comparison exposes differences\n\"It removes the need to record cash receipts\" = thought it replaces recording · \"It guarantees the bank is never wrong\" = thought it proves the bank correct · \"It replaces the cash count\" = confused bank cash with cash on hand"], ["c8", "A reconciliation leads to these entries in the company's books: bank service charge 600; NSF check 150; interest earned 600. By how much do the adjusting entries change the Cash account?", ["Decrease of 150", "Increase of 150", "Increase of 0", "Decrease of 1,350"], 0, "Increases: 600; decreases: 750; net = Decrease of 150\nIncrease of 150 = reversed the direction of the net change · Increase of 0 = left out the NSF check · Decrease of 1,350 = treated every item as a decrease"], ["c8", "A deposit of 1,260 was recorded in the company's books as 1,620; the bank credited 1,260. The balance per books before correcting the error is 19,550. What is the correct book balance?", ["19,190", "19,910", "19,550", "20,810"], 0, "Books were increased by 1,620 instead of 1,260; correct balance = 19,550 + 1,260 − 1,620 = 19,190\n19,910 = reversed the direction of the correction · 19,550 = treated it as a bank-side item and left the book balance unchanged · 20,810 = added the full deposit a second time"], ["c8", "The bank collected a note receivable for the company and credited the account; the company has not recorded the collection. How is this item handled in the bank reconciliation?", ["Add to the book balance; record a journal entry", "Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Deduct from the book balance; record a journal entry"], 0, "The collection is a book-side item: add it and record the entry\n\"Add to the bank statement balance; no journal entry\" = wrong side, right direction · \"Deduct from the bank statement balance; no journal entry\" = wrong side and wrong direction · \"Deduct from the book balance; record a journal entry\" = right side, wrong direction"], ["c8", "A reconciliation leads to these entries in the company's books: interest earned 310; bank service charge 20; automatic insurance debit not yet recorded 540; NSF check 430. By how much do the adjusting entries change the Cash account?", ["Decrease of 680", "Increase of 680", "Decrease of 660", "Decrease of 1,300"], 0, "Increases: 310; decreases: 990; net = Decrease of 680\nIncrease of 680 = reversed the direction of the net change · Decrease of 660 = left out the bank service charge · Decrease of 1,300 = treated every item as a decrease"], ["c8", "Balance per books 8,750. The bank statement shows: bank service charge 130; automatic insurance debit not yet recorded 430; NSF check 190; customer EFT receipt not yet recorded 40. Deposits in transit are 5,600 and outstanding checks 3,200. What is the adjusted cash balance on the book side?", ["8,040", "8,300", "4,840", "7,960"], 0, "8,750 − 130 − 430 − 190 + 40 = 8,040; deposits in transit and outstanding checks are bank-side items\n8,300 = added the bank service charge instead of deducting it · 4,840 = also deducted outstanding checks, which are bank-side items · 7,960 = deducted the customer EFT receipt not yet recorded instead of adding it"], ["c8", "Balance per books 12,250. The bank statement shows: NSF check 90; customer EFT receipt not yet recorded 90; interest earned 20; automatic insurance debit not yet recorded 240. Deposits in transit are 550 and outstanding checks 1,050. What is the adjusted cash balance on the book side?", ["12,030", "12,210", "10,980", "11,850"], 0, "12,250 − 90 + 90 + 20 − 240 = 12,030; deposits in transit and outstanding checks are bank-side items\n12,210 = added the NSF check instead of deducting it · 10,980 = also deducted outstanding checks, which are bank-side items · 11,850 = deducted the customer EFT receipt not yet recorded instead of adding it"], ["c8", "Which formula gives the adjusted bank balance?", ["Bank balance + deposits in transit − outstanding checks ± bank errors", "Bank balance − deposits in transit + outstanding checks", "Book balance + deposits in transit − outstanding checks", "Bank balance + NSF checks − service charges"], 0, "The bank side adjusts for items the bank has not yet recorded\n\"Bank balance − deposits in transit + outstanding checks\" = swapped the signs · \"Book balance + deposits in transit − outstanding checks\" = started from the book balance · \"Bank balance + NSF checks − service charges\" = used book-side items"], ["c8", "The bank paid a 120 monthly insurance premium by automatic debit that the company has not recorded. Which entry does the company record?", ["Dr. Insurance expense 120 / Cr. Cash 120", "Dr. Cash 120 / Cr. Insurance expense 120", "Dr. Accounts receivable 120 / Cr. Cash 120", "No entry; the bank has already recorded it"], 0, "The premium is an expense paid in cash\n\"Dr. Cash 120 / Cr. Insurance expense 120\" = reversed the entry · \"Dr. Accounts receivable 120 / Cr. Cash 120\" = used a receivable for a payment made · \"No entry; the bank has already recorded it\" = treated it as a bank-only item"], ["c8", "A check for 1,980 was recorded in the company's books as 1,890; the bank paid 1,980. The balance per books before correcting the error is 18,150. What is the correct book balance?", ["18,060", "18,240", "18,150", "16,170"], 0, "Books were reduced by 1,890 instead of 1,980; correct balance = 18,150 + 1,890 − 1,980 = 18,060\n18,240 = reversed the direction of the correction · 18,150 = treated it as a bank-side item and left the book balance unchanged · 16,170 = deducted the full check amount a second time"], ["c8", "The company deposited cash receipts on the last day of the month, but the bank statement does not show the deposit. How is this item handled in the bank reconciliation?", ["Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Add to the book balance; record a journal entry", "Deduct from the book balance; record a journal entry"], 0, "Deposits in transit are recorded by the company before the bank, so they are added to the bank balance\n\"Deduct from the bank statement balance; no journal entry\" = right side, wrong direction · \"Add to the book balance; record a journal entry\" = wrong side, right direction · \"Deduct from the book balance; record a journal entry\" = wrong side and wrong direction"], ["c8", "On a bank statement, what does a credit memo mean?", ["The bank added an amount to the customer’s account", "The bank deducted an amount from the customer’s account", "The customer wrote an outstanding check", "The bank found an error in the company’s books"], 0, "A credit memo increases the depositor’s balance, for example interest or a collection\n\"The bank deducted an amount from the customer’s account\" = mixed up credit and debit memos · \"The customer wrote an outstanding check\" = confused a memo with an outstanding check · \"The bank found an error in the company’s books\" = confused a memo with an error notice"], ["c8", "A deposit of 380 was recorded in the company's books as 830; the bank credited 380. The balance per books before correcting the error is 22,050. What is the correct book balance?", ["21,600", "22,500", "22,050", "22,430"], 0, "Books were increased by 830 instead of 380; correct balance = 22,050 + 380 − 830 = 21,600\n22,500 = reversed the direction of the correction · 22,050 = treated it as a bank-side item and left the book balance unchanged · 22,430 = added the full deposit a second time"], ["c8", "Bank statement balance 10,600. Deposits in transit 5,350. Outstanding checks: #301 for 400, #305 for 900, #309 for 1,000, #313 for 550. The company has not yet recorded a bank service charge of 85. What is the adjusted cash balance on the bank side?", ["13,100", "8,100", "13,015", "7,750"], 0, "10,600 + 5,350 − 2,850 = 13,100; the service charge is a book-side item\n8,100 = swapped the signs of deposits in transit and outstanding checks · 13,015 = also deducted a service charge, which is a book-side item · 7,750 = left out deposits in transit"], ["c8", "A reconciliation leads to these entries in the company's books: bank service charge 360; customer EFT receipt not yet recorded 40; NSF check 510. By how much do the adjusting entries change the Cash account?", ["Decrease of 830", "Increase of 830", "Decrease of 870", "Decrease of 910"], 0, "Increases: 40; decreases: 870; net = Decrease of 830\nIncrease of 830 = reversed the direction of the net change · Decrease of 870 = left out the customer EFT receipt not yet recorded · Decrease of 910 = treated every item as a decrease"], ["c8", "Bank statement balance 25,450. Deposits in transit 1,750. Outstanding checks: #301 for 2,150, #305 for 500. The company has not yet recorded a bank service charge of 15. What is the adjusted cash balance on the bank side?", ["24,550", "26,350", "24,535", "22,800"], 0, "25,450 + 1,750 − 2,650 = 24,550; the service charge is a book-side item\n26,350 = swapped the signs of deposits in transit and outstanding checks · 24,535 = also deducted a service charge, which is a book-side item · 22,800 = left out deposits in transit"], ["c8", "A check for 830 was recorded in the company's books as 380; the bank paid 830. The balance per books before correcting the error is 35,850. What is the correct book balance?", ["35,400", "36,300", "35,850", "35,020"], 0, "Books were reduced by 380 instead of 830; correct balance = 35,850 + 380 − 830 = 35,400\n36,300 = reversed the direction of the correction · 35,850 = treated it as a bank-side item and left the book balance unchanged · 35,020 = deducted the full check amount a second time"], ["c8", "Bank statement balance 38,100. Deposits in transit 2,400. Outstanding checks: #301 for 1,000, #305 for 1,800, #309 for 1,250. The company has not yet recorded a bank service charge of 85. The bank wrongly charged 250 for another customer's check. What is the adjusted cash balance on the bank side?", ["36,700", "40,000", "36,615", "36,200"], 0, "38,100 + 2,400 − 4,050 + 250 = 36,700; the service charge is a book-side item\n40,000 = swapped the signs of deposits in transit and outstanding checks · 36,615 = also deducted a service charge, which is a book-side item · 36,200 = deducted the bank error instead of adding it back"], ["c8", "The bank collected a 2,000 note plus 80 interest for the company and deducted a 15 fee. Which entry does the company record?", ["Dr. Cash 2,065 and Dr. Bank service charges 15 / Cr. Notes receivable 2,000 and Cr. Interest revenue 80", "Dr. Cash 2,080 / Cr. Notes receivable 2,000 and Cr. Interest revenue 80", "Dr. Cash 2,000 / Cr. Notes receivable 2,000", "Dr. Cash 2,065 / Cr. Notes receivable 2,065"], 0, "Cash rises by the net 2,065; the note is reduced by its principal, interest is revenue and the fee is an expense\n\"Dr. Cash 2,080 / Cr. Notes receivable 2,000 and Cr. Interest revenue 80\" = ignored the collection fee · \"Dr. Cash 2,000 / Cr. Notes receivable 2,000\" = ignored the interest and the fee · \"Dr. Cash 2,065 / Cr. Notes receivable 2,065\" = put interest and fee into the principal"], ["c8", "A reconciliation leads to these entries in the company's books: bank service charge 580; interest earned 150; NSF check 600; customer EFT receipt not yet recorded 140. By how much do the adjusting entries change the Cash account?", ["Decrease of 890", "Increase of 890", "Decrease of 1,030", "Decrease of 1,470"], 0, "Increases: 290; decreases: 1,180; net = Decrease of 890\nIncrease of 890 = reversed the direction of the net change · Decrease of 1,030 = left out the customer EFT receipt not yet recorded · Decrease of 1,470 = treated every item as a decrease"], ["c8", "A reconciliation leads to these entries in the company's books: automatic insurance debit not yet recorded 200; interest earned 340; customer EFT receipt not yet recorded 520; NSF check 200. By how much do the adjusting entries change the Cash account?", ["Increase of 460", "Decrease of 460", "Increase of 660", "Decrease of 1,260"], 0, "Increases: 860; decreases: 400; net = Increase of 460\nDecrease of 460 = reversed the direction of the net change · Increase of 660 = left out the automatic insurance debit not yet recorded · Decrease of 1,260 = treated every item as a decrease"], ["c8", "Why should the bank statement go unopened to the person preparing the reconciliation?", ["To reduce the chance that someone alters it to hide theft", "To speed up posting", "Because banks require it", "To check the bank’s arithmetic only"], 0, "Independent receipt of the statement protects its integrity\n\"To speed up posting\" = confused control with speed · \"Because banks require it\" = invented a bank requirement · \"To check the bank’s arithmetic only\" = limited the purpose to arithmetic"], ["c8", "Checks issued in the month: #401 for 500, #402 for 1,900, #403 for 1,350, #404 for 1,800, #405 for 1,650, #406 for 1,950. The bank statement shows these checks cleared: #402, #403, #405. What is the total of outstanding checks?", ["4,250", "4,900", "9,150", "3,750"], 0, "Outstanding = issued but not cleared: #401, #404, #406 = 4,250\n4,900 = added the checks that cleared · 9,150 = added every check issued · 3,750 = overlooked one outstanding check"], ["c8", "From the bank’s point of view, what is a customer’s deposit account?", ["A liability, so a deposit is a credit to it", "An asset, so a deposit is a debit", "Revenue, so deposits are earned", "An expense, so deposits are costs"], 0, "The bank owes the depositor the money, which is why deposits are credits\n\"An asset, so a deposit is a debit\" = viewed the account from the customer’s side · \"Revenue, so deposits are earned\" = confused deposits with revenue · \"An expense, so deposits are costs\" = confused deposits with expenses"], ["c8", "The bank charged another customer's check of 400 to the company's account. How is this item handled in the bank reconciliation?", ["Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Add to the book balance; record a journal entry", "Deduct from the book balance; record a journal entry"], 0, "A bank error is corrected on the bank side by adding it back; the company only notifies the bank\n\"Deduct from the bank statement balance; no journal entry\" = right side, wrong direction · \"Add to the book balance; record a journal entry\" = wrong side, right direction · \"Deduct from the book balance; record a journal entry\" = wrong side and wrong direction"], ["c8", "Which list contains only bank-side reconciling items?", ["Deposits in transit, outstanding checks, bank errors", "NSF check, service charge, interest earned", "Deposits in transit, service charge, bank error", "Outstanding checks, interest earned, NSF check"], 0, "Bank-side items are known to the company but not yet in the bank’s records, plus bank errors\n\"NSF check, service charge, interest earned\" = listed book-side items · \"Deposits in transit, service charge, bank error\" = mixed a book-side item into the list · \"Outstanding checks, interest earned, NSF check\" = mixed book-side items into the list"], ["c8", "After reconciliation the adjusted cash balance is 41,100 (bank balance 41,600, deposits in transit 1,400, outstanding checks 1,900). The company's adjusting entries were interest earned 130, NSF check 500 and service charge 65. What was the balance per books before adjustments?", ["41,535", "40,665", "41,600", "41,100"], 0, "Book balance + 130 − 500 − 65 = 41,100, so book balance = 41,100 − 130 + 500 + 65 = 41,535\n40,665 = reversed every book-side adjustment · 41,600 = used the unadjusted bank balance · 41,100 = assumed no book-side adjustments were needed"], ["c8", "The bank paid an automatic insurance premium debit that the company has not recorded. How is this item handled in the bank reconciliation?", ["Deduct from the book balance; record a journal entry", "Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Add to the book balance; record a journal entry"], 0, "Unrecorded bank debits are deducted on the book side with an entry\n\"Add to the bank statement balance; no journal entry\" = wrong side and wrong direction · \"Deduct from the bank statement balance; no journal entry\" = wrong side, right direction · \"Add to the book balance; record a journal entry\" = right side, wrong direction"], ["c8", "Bank statement balance 50,900. Deposits in transit 2,200. Outstanding checks: #301 for 2,450, #305 for 150. The company has not yet recorded a bank service charge of 80. The bank wrongly charged 700 for another customer's check. What is the adjusted cash balance on the bank side?", ["51,200", "52,000", "51,120", "49,800"], 0, "50,900 + 2,200 − 2,600 + 700 = 51,200; the service charge is a book-side item\n52,000 = swapped the signs of deposits in transit and outstanding checks · 51,120 = also deducted a service charge, which is a book-side item · 49,800 = deducted the bank error instead of adding it back"], ["c8", "A check for 540 was recorded in the company's books as 450; the bank paid 540. The balance per books before correcting the error is 9,400. What is the correct book balance?", ["9,310", "9,490", "9,400", "8,860"], 0, "Books were reduced by 450 instead of 540; correct balance = 9,400 + 450 − 540 = 9,310\n9,490 = reversed the direction of the correction · 9,400 = treated it as a bank-side item and left the book balance unchanged · 8,860 = deducted the full check amount a second time"], ["c8", "Check #214 was mailed to a supplier and recorded by the company, but it has not cleared the bank. How is this item handled in the bank reconciliation?", ["Deduct from the bank statement balance; no journal entry", "Add to the bank statement balance; no journal entry", "Add to the book balance; record a journal entry", "Deduct from the book balance; record a journal entry"], 0, "Outstanding checks are recorded by the company before the bank pays them, so they are deducted from the bank balance\n\"Add to the bank statement balance; no journal entry\" = right side, wrong direction · \"Add to the book balance; record a journal entry\" = wrong side and wrong direction · \"Deduct from the book balance; record a journal entry\" = wrong side, right direction"], ["c8", "Bank statement balance 32,150. Deposits in transit 2,100. Outstanding checks: #301 for 2,450, #305 for 800, #309 for 1,800. The company has not yet recorded a bank service charge of 35. The bank wrongly charged 550 for another customer's check. What is the adjusted cash balance on the bank side?", ["29,750", "35,650", "29,715", "28,650"], 0, "32,150 + 2,100 − 5,050 + 550 = 29,750; the service charge is a book-side item\n35,650 = swapped the signs of deposits in transit and outstanding checks · 29,715 = also deducted a service charge, which is a book-side item · 28,650 = deducted the bank error instead of adding it back"], ["c8", "The bank deducted a monthly service charge that the company has not recorded. How is this item handled in the bank reconciliation?", ["Deduct from the book balance; record a journal entry", "Add to the bank statement balance; no journal entry", "Deduct from the bank statement balance; no journal entry", "Add to the book balance; record a journal entry"], 0, "The charge is a book-side item: deduct it and record an expense\n\"Add to the bank statement balance; no journal entry\" = wrong side and wrong direction · \"Deduct from the bank statement balance; no journal entry\" = wrong side, right direction · \"Add to the book balance; record a journal entry\" = right side, wrong direction"]], "pages": {"c1": "3c4f0298-4125-8008-bb39-e0ee72065010", "c2": "40cf0298-4125-81f4-9dba-ca60308b0494", "c3": "40cf0298-4125-81e1-a0e7-c02a8fc29d93", "c4": "40cf0298-4125-81fe-a791-d5133c4124b8", "c5": "3f0f0298-4125-80f9-8e05-f7a920a42ee4", "c6": "3f7f0298-4125-8062-b828-fa6104327a25", "c7": "405f0298-4125-8024-8703-d759d929fdda", "c8": "40cf0298-4125-801a-a605-de4f1d648b0d", "c9": "40cf0298-4125-8169-9338-da91988ac24b"}, "markKey": "acc-flashcards-v1"};
